INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nymvq', 'nymvq', 'A educação médica na América Latina', NULL, '["Juan César García"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Este livro integra a importante obra de Juan César García, durante seu trabalho na Organização Pan-Americana da Saúde (Opas). Publicado pela primeira vez em 1972, contém uma rigorosa e ampla análise da educação médica nos países latino-americanos, apontando os condicionantes sociais da configuração curricular e as características do processo de ensino. Nos últimos 50 anos, este livro tornou-se um clássico no campo da Saúde Coletiva brasileira e latino-americana, inspirando estudos e pesquisas que subsidiaram a introdução de práticas transformadoras e movimentos de reforma na formação de pessoal e na organização de sistemas de saúde, o que estimulou sua publicação, pela primeira vez, em português.', '["medical education","Latin America","course program","social determinants of education","teaching process","health professions education","health care reform","Pan American Health Organization"]', '10.7476/9786556304687', '9786556304687', 'https://books.scielo.org/id/nymvq', 'https://books.scielo.org/id/nymvq/pdf/garcia-9786556304687.pdf', NULL, 'https://books.scielo.org/id/nymvq/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nyrwd', 'nyrwd', 'Sílvio Romero e José Veríssimo em combate: Brasil, literatura, ensino e legitimação', 'Brasil, literatura, ensino e legitimação', '["Wagner Gonzaga Lemos"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A obra discute como a historiografia literária frequentemente ignora a docência exercida por muitos intelectuais dos séculos XIX e XX. Autores como Romero, Veríssimo, João Ribeiro e outros tiveram no magistério parte central de suas vidas, embora pesquisas reduzam esse vínculo a mero dado biográfico. O texto revela como essa omissão reforça a desvalorização histórica da carreira docente e propõe recolocar o ensino no centro da compreensão da produção intelectual brasileira.', '["Sílvio Romero","José Veríssimo","João Ribeiro","literary historiography","Brazilian literature"]', '10.7476/9788585813826', '9788585813697', 'https://books.scielo.org/id/nyrwd', 'https://books.scielo.org/id/nyrwd/pdf/lemos-9788585813826.pdf', NULL, 'https://books.scielo.org/id/nyrwd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nz9r3', 'nz9r3', 'Educação universitária: práxis coletiva em busca de veraz qualidade e de precisa cientificidade', NULL, '["Pedro Bergamo"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro deverá ultrapassar um mero ensaio, porque nele se encontram argumentos pouco ou nada comuns sobre caráter veraz de qualidade e sobre precisa cientificidade de certa educação universitária. Esta obra presume objeto de uma pedagogia que, a partir da sua autoafirmação enquanto práxis coletiva em ambiência acadêmica, há de enfim se tornar apta a romper com o vezo colonizador do seu humano campo de atuação.', '["university education","collective praxis","university pedagogy","higher education quality","scientific rigor","coloniality","decolonization of academia","truth in education"]', '10.7476/9788578791896', '9788578791896', 'https://books.scielo.org/id/nz9r3', 'https://books.scielo.org/id/nz9r3/pdf/bergamo-9788578791896.pdf', NULL, 'https://books.scielo.org/id/nz9r3/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-nzdvb', 'nzdvb', 'Trabalho, democracia e participação no Brasil', NULL, '["Neves, Angela Vieira","Ghiraldelli, Reginaldo"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '“Trabalho, democracia e participação no Brasil” desvela o que veio depois do desenvolvimentismo e do experimentalismo democrático pujante com que convivemos no início dos anos 2000. Esta coletânea observa a substancialidade da democracia e denota a relevância da luta para que o Estado cumpra seu papel e garanta proteção social. Se a maior parte da população brasileira sofre discriminação de gênero e raça, enfrentando densas estruturas de desigualdade no mundo do trabalho e nas demais esferas sociais, ainda estamos longe de romper com essa trajetória histórica de violência e marginalização. Entre os alertas importantes desta obra, está a noção de que as conformações das classes sociais são mediadas por marcadores raciais e sexuais e, ainda, que o outro Estado desejado, igualitário e justo, exige procedimentos de democratização. A leitura convida a compreender como o ataque ao patrimônio participativo e as (contra) reformas trabalhista e previdenciária são emblemas da erosão de direitos sociais, por significarem a imposição de uma visão única de mundo que gera impactos materiais nas políticas públicas e na vida da população. Este livro denuncia o modo como opera o projeto político neoliberal vigente, que pretere vidas aos lucros, ataca trabalhadores e é operacionalizado durante a pandemia com efeitos devastadores. Os textos desta coletânea reconhecem esses desafios e mobilizam reflexões contundentes sobre os caminhos que estão sendo trilhados na crise civilizatória atual.', '["workers'' rights","democracy","social participation","social rights","gender discrimination","racial discrimination","social inequality","social class formation","participatory democracy","labor reform","pension reform","neoliberalism"]', '10.7476/9786558461654', '9786558461654', 'https://books.scielo.org/id/nzdvb', 'https://books.scielo.org/id/nzdvb/pdf/neves-9786558461654.pdf', NULL, 'https://books.scielo.org/id/nzdvb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p269q', 'p269q', 'A constituição da subjetividade feminina em Alfonsina Storni: uma voz gritante na América', NULL, '["Nildicéia Aparecida Rocha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As vozes literárias em prosa e verso e as atitudes “femininas/feministas” da escritora Alfonsina Storni (1892 – 1938), que nasceu na Suíça e passou a viver na Argentina a partir dos quatro anos, são consideradas referências na América Latina. Mas sua obra Poemas de amor (1926), foco deste estudo, constituída de poemas em prosa, tem sido praticamente ignorada pela crítica e pouco analisada. De acordo com Nildicéia Aparecida Rocha, a escritora revela posições aparentemente contraditórias em relação à mulher naquele livro, transitando entre a visão tradicionalista e/ou a visão contestatória a partir da condição de feminista. Sua identidade “feminina/feminista” seria construída, assim, em meio a certa contradição da representação da mulher no início do século 20, a qual aparece tanto na poeticidade dos textos quanto nos aspectos de narração e argumentação e nos jogos de diálogo entre o eu e o tu poéticos e o leitor. Nesta obra, a autora aborda ainda temas como a produção literária argentina das quatro décadas iniciais dos anos 1900 e o lugar da mulher na literatura hispano-americana da época, desenvolve uma breve biografia de Storni e mostra como foi a recepção crítica à sua obra. A segunda, mais teórico-analítica, Rocha discute, entre outras questões, conceitos como literatura e linguagem poética, diferenças e semelhanças entre poesia e prosa e sua relação com o poema em prosa e as marcas dialógicas que compõem os poemas de amor. Por fim, trata da construção da subjetividade “feminina/feminista” em Alfonsina Storni, percorre a formação histórica da crítica literária feminista e analisa seus poemas em prosa à luz dessa crítica.', '["Alfonsina Storni","female subjectivity","feminism","women writers","Argentine literature","Latin American literature","prose poetry","poetic language","representation of women","feminist literary criticism","early 20th century"]', '10.7476/9786557144879', '9786557144879', 'https://books.scielo.org/id/p269q', 'https://books.scielo.org/id/p269q/pdf/rocha-9786557144879.pdf', NULL, 'https://books.scielo.org/id/p269q/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p26q6', 'p26q6', 'Arquivos da loucura: Juliano Moreira e a descontinuidade histórica da psiquiatria', 'Juliano Moreira e a descontinuidade histórica da psiquiatria', '["Vera Portocarrero"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Vera Portocarrero propõe-se a refletir até que ponto o novo modelo psiquiátrico trazido por Juliano Moreira e seus contemporâneos se constitui como uma ruptura do saber e da prática psiquiátrica no Brasil. Dirigindo-se à análise de arquivos, a autora procede a uma análise de discursos e de documentos, especialmente arquivos brasileiros encontrados na Biblioteca Nacional do Rio de Janeiro, nas bibliotecas de medicina, do Instituto Histórico e Geográfico Brasileiro, do Instituto de Psiquiatria da Universidade Federal do Estado do Rio de Janeiro, dentre outros. Os discursos encontrados nesses arquivos são analisados dentro de uma perspectiva foucaultiana, ultrapassando, desse modo, a simples ordenação memorialística; deixando uma suspeita em relação ao discurso psiquiátrico dominante e apontando uma descontinuidade histórica no que diz respeito à articulação do saber com as práticas e seu caráter estratégico.', '["history of psychiatry","Juliano Moreira","psychiatric discourse","Michel Foucault","Brazilian psychiatry","institutional archives","history of mental illness"]', '10.7476/9788575413883', '9788575410196', 'https://books.scielo.org/id/p26q6', 'https://books.scielo.org/id/p26q6/pdf/portocarrero-9788575413883.pdf', NULL, 'https://books.scielo.org/id/p26q6/cover/cover_thumbnail.jpeg', NULL, 26, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p293s', 'p293s', 'Guimarães Rosa em tradução: o texto literário e a versão alemã de Tutaméia', NULL, '["Gilca Machado Seidinger"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Neste livro, Gilca Machado Seidinger estuda as relações entre enunciação, enunciado e história na obra Tutaméia, de João Guimarães Rosa, tratando também da versão alemã assinada por Curt Meyer-Clason. Pressupondo que o processo de tradução altera significações originais ou produz novas significações não previstas pelo autor, a autora recorre à narratologia genettiana, bem como à teoria das modalidades da tradução, de Francis Aubert, para examinar as quarenta narrativas do livro. Uma obra importante no campo dos estudos literários, vol­tada para a ficção de Guimarães Rosa, e que aborda, com muita competência, um dos livros mais complexos e menos estudados do autor, levantando, ao mesmo tempo, aspectos relevantes para a análise teórica e para a prática da tradução de textos literários, sobretudo os modernos, que proporiam ao tradutor desafios antes inimagináveis.', '["Guimarães Rosa","Tutaméia","German translation","literary translation","history of the text","narrative theory","Gérard Genette"]', '10.7476/9786557145289', '9786557145289', 'https://books.scielo.org/id/p293s', 'https://books.scielo.org/id/p293s/pdf/seidinger-9786557145289.pdf', NULL, 'https://books.scielo.org/id/p293s/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p29ph', 'p29ph', 'Notas de um naturalista do sul do Brasil: Fritz Müller: história da ciência e contribuições para a biologia', NULL, '["Flavia Pacheco Alves de Souza"]', 'Editora UFABC', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro realiza uma construção biográfica de Fritz Müller (1822-1897), naturalista alemão residente no Brasil durante o século XIX. Fritz Müller publicou ao longo de sua vida 264 trabalhos (estes eram originalmente enviados como cartas a diversos correspondentes e posteriormente publicados como artigos científicos), a maioria sobre assuntos relacionados à evolução, fauna, flora e ecologia. Müller adotou o Brasil como pátria e a colônia de Blumenau como seu lar. Após a sua vinda ao Brasil, nunca mais voltou à Europa e confidenciava aos amigos por cartas que não trocava sua vida no campo pela vida “civilizada” que poderia ter na Alemanha. Nem mesmo o Rio de Janeiro, capital do Império e reduto da ciência brasileira no período, foi visitado por ele. Quando em 1891, ainda funcionário do Museu Nacional do Rio de Janeiro, o regulamento passou a exigir que os naturalistas viajantes mudassem sua residência para a cidade, Müller não hesitou em pedir a sua exoneração do cargo. Seus trabalhos, realizados na província de Santa Catarina, Brasil, figuravam nas revistas científicas (alemãs e inglesas) da época e em comunicações realizadas por terceiros nas sociedades científicas da Inglaterra. Além de se corresponder com Charles Darwin (1809-1882), correspondia-se com outros pesquisadores conhecidos da ciência mundial: Ernst Haeckel (1834-1919), Alexander Agassiz (1835-1910), Max Schultze (1825-1874), Raphael Meldola (1849-1915), Hermann Hagen (1817-1893) etc. Darwin pedia a Müller que escrevesse sobre suas impressões e vida em Santa Catarina, algo como um livro de narrativas sobre a fauna e a flora do local. Chegou até mesmo a sugerir títulos, como: Jornal de um naturalista do Brasil ou Notas de um naturalista do Brasil. Apesar da insistência do amigo, Müller nunca realizou tal pedido. O título deste livro é uma homenagem à amizade entre estes dois naturalistas. Apesar destas Notas não terem sido escritas por Müller como Darwin o desejou, o objetivo é apresentar parte dos trabalhos de Müller realizados no Brasil, que tiveram como cenário e personagens os elementos da fauna e da flora catarinenses. Assim, buscando situar a importância desse conhecimento para a história da biologia na contemporaneidade. Por fim, este livro não tem a finalidade de esgotar o assunto. Antes, busca revisitar a obra de Müller como uma contribuição à história e à memória da ciência no Brasil.', '["Fritz Müller","naturalists","history of science","Charles Darwin","Blumenau","Santa Catarina","19th-century science","evolution","flora and fauna","ecology","Ernst Haeckel","Alexander Agassiz"]', '10.7476/9788568576809', '9788568576809', 'https://books.scielo.org/id/p29ph', 'https://books.scielo.org/id/p29ph/pdf/souza-9788568576809.pdf', NULL, 'https://books.scielo.org/id/p29ph/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p2qh6', 'p2qh6', 'Inferência causal em epidemiologia: o modelo de respostas potenciais', NULL, '["Ronir Raggio Luiz","Claudio José Struchiner"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2002, '2002-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Mathematics', 'Os autores apresentam uma das mais importantes contribuições da estatística para a discussão da causalidade, por meio do modelo de respostas potenciais proposto por Rubin, e sua interface com o método epidemiológico. De particular interesse são as soluções científica e estatística exploradas, além das premissas adjacentes de homogeneidade e estabilidade. A obra estabelece um diálogo com a epidemiologia em que são valorizadas e resguardadas as identidades de cada disciplina. O espírito interdisciplinar torna este trabalho importante não só para os epidemiologistas e bioestatísticos, mas também para outros profissionais da saúde coletiva que almejem ampliar sua visão sobre a questão da causalidade.', '["causal inference","potential outcomes","homogeneity assumption","stability assumption","epidemiological methods"]', '10.7476/9788575412688', '9788575412688', 'https://books.scielo.org/id/p2qh6', 'https://books.scielo.org/id/p2qh6/pdf/luiz-9788575412688.pdf', NULL, 'https://books.scielo.org/id/p2qh6/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p2r7v', 'p2r7v', 'Toxoplasmose &amp; Toxoplasma gondii', NULL, '["Wanderley de Souza","Rubens Belfort"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'en', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Salud Colectiva', 'A infecção por Toxoplasma gondii é hoje muito disseminada ao redor do mundo, especialmente no Brasil. A coletânea parte da história da descoberta desse parasita e da doença por ele causada, a toxoplasmose, e visita os diferentes aspectos relacionados ao tema. São apresentados o ciclo evolutivo, a epidemiologia, o diagnóstico, o quadro clínico e o tratamento, em uma ampla revisão sobre o assunto, provavelmente a mais completa já realizada. Somente nos anos 1970 desvendou-se o ciclo de vida desse protozoário, do qual o gato é hospedeiro definitivo. Outros animais de sangue quente, entre eles o ser humano, são hospedeiros intermediários. Muitos indivíduos infectados pelo T. gondii não apresentam sintomas, mas, quando a doença se manifesta, pode ter diferentes configurações, afetando gânglios, olhos, coração, pulmões, fígado, cérebro e meninges, ou articulações. Além de uma completa revisão, a obra também traz para o leitor o que há de mais atual no conhecimento científico acerca da toxoplasmose e do T. gondii. O livro cobre praticamente todos os campos do conhecimento sobre o agente etiológico e a doença, apresentando novos aspectos, particularmente em relação à bioquímica, à interação entre o parasita e a célula hospedeira e à resposta imunológica à infecção.', '["toxoplasmosis","Toxoplasma gondii","life cycle","epidemiology","diagnosis","clinical features","treatment","cats as definitive hosts","intermediate hosts","host-parasite interactions","host immune response","parasite biochemistry"]', '10.7476/9788575415719', '9788575415719', 'https://books.scielo.org/id/p2r7v', 'https://books.scielo.org/id/p2r7v/pdf/souza-9788575415719.pdf', NULL, 'https://books.scielo.org/id/p2r7v/cover/cover_thumbnail.jpeg', NULL, 22, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p33vq', 'p33vq', 'A Residência Pedagógica na UFFS: reflexões sobre a formação de professores (2020-2022)', NULL, '["Adriana María Andreis","Demétrio Alves Paz","Oto João Petry"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta obra, constituída de 11 capítulos, apresenta a experiência do Programa Residência Pedagógica (PRP) da Universidade Federal da Fronteira Sul, aprovado no Edital 1/CAPES/2020. O programa conta com oito subprojetos: quatro de áreas prioritárias – Alfabetização; Biologia, Física e Química; Língua Portuguesa; Matemática – e quatro de áreas gerais – Língua Espanhola; Licenciatura em Educação do Campo; Geografia; História, Sociologia e Filosofia. Foram 18 núcleos, vinculados aos cursos de licenciatura de cinco campi da UFFS: Cerro Largo e Erechim, no Rio Grande do Sul; Chapecó, em Santa Catarina; Laranjeiras do Sul e Realeza, no Paraná. No total, o PRP da UFFS teve, inicialmente, 336 residentes bolsistas e 80 alunos voluntários, 42 preceptores da Educação Básica, 14 professores orientadores bolsistas, 11 professores voluntários e um coordenador institucional.', '["pedagogical residency","teacher professional development","initial teacher education","Universidade Federal da Fronteira Sul","literacy education","science education","Portuguese language teaching","mathematics education","Spanish language teaching","rural education"]', '10.7476/9786550190583', '9786550190583', 'https://books.scielo.org/id/p33vq', 'https://books.scielo.org/id/p33vq/pdf/andreis-9786550190583.pdf', NULL, 'https://books.scielo.org/id/p33vq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p3fp8', 'p3fp8', 'Escritas libertárias', NULL, '["Vera Chalmers"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O livro estuda a literatura de cunho libertário ou a respeito do anarquismo nacional e internacional. O âmbito de análise dos textos breves abrange fins do século XIX até à Segunda Guerra Mundial e a contemporaneidade. Os escritos apresentados são frutos de pesquisa em bibliotecas e acervos públicos e particulares no país e no exterior. O estudo destes textos publicados nos jornais anarquistas de várias tendências e nacionalidades revela o interesse da pesquisa, desenvolvida há vários anos, pelos documentos originais e as fontes primárias. O livro espera alcançar seus objetivos de contribuir para a divulgação desta literatura na contemporaneidade.', '["anarchism","anarchist press","short text","19th century","early 20th century","contemporary anarchism","primary sources"]', '10.7476/9786580216154', '9786580216154', 'https://books.scielo.org/id/p3fp8', NULL, NULL, 'https://books.scielo.org/id/p3fp8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p452s', 'p452s', 'Biomassa: estrutura, propriedades e aplicações', NULL, '["Arlene G. Corrêa","Jean Marcel R. Gallo"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Energy', '[RETIRADO/WITHDRAWN] A utilização da biomassa vem crescendo mundialmente como fonte renovável para a produção de energia elétrica e de biocombustíveis (etanol, biodiesel, biogás etc.). Ademais, a biomassa se destaca como uma fonte de material de partida na produção de diversas substâncias orgânicas que servirão como insumos nos mais variados processos industriais. Neste livro são abordados os diversos aspectos da biomassa, desde a sua estrutura até sua valorização e emprego em biorrefinarias. Devido ao seu papel fundamental, os processos catalíticos para a produção de commodities e outros produtos de maior valor agregado a partir da biomassa são discutidos em detalhes, com exemplos recentes da literatura.', '["biomass","biomass structure","biomass properties","renewable energy","biofuels","biogas","ethanol","biodiesel","biomass valorization","biorefinery","catalytic processes","bio-based chemicals"]', '10.7476/9786586768442', '9786586768442', 'https://books.scielo.org/id/p452s', NULL, NULL, 'https://books.scielo.org/id/p452s/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p4dv3', 'p4dv3', 'Publique, apareça ou pereça: produtivismo acadêmico, pesquisa administrativa e plágio nos tempos da cultura digital', NULL, '["Lucídio Bianchetti","Antônio Álvaro Soares Zuin","Obdália Ferraz"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '(Menção Honrosa na categoria "Ciências Humanas" do 5º Prêmio ABEU, 2019) Evocando o mantra “publique, apareça ou pereça”, os autores buscam trazer a realidade da produção acadêmica nos tempos da “sociedade do espetáculo”, criticando a atual produção do conhecimento e as consequências de sua mudança para uma categoria de análise. Dentre essas consequências, os autores destacam o produtivismo acadêmico, assim como o controle da pesquisa, o plágio, a necessidade de aparecer pela quantidade de publicações em mídias determinadas, e a emergência de um novo tipo de conhecimento cujo processo e resultados são induzidos de fora da universidade.', '["publish or perish","academic productivity","administrative research","plagiarism","digital culture","spectacle society","knowledge production","publication metrics"]', '10.7476/9788523220181', '9788523216474', 'https://books.scielo.org/id/p4dv3', NULL, NULL, 'https://books.scielo.org/id/p4dv3/cover/cover_thumbnail.jpeg', 203, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p4qk8', 'p4qk8', 'A pesquisa científica na era do Big Data: cinco maneiras que mostram como o Big Data prejudica a ciência, e como podemos salvá-la', NULL, '["Sabina Leonelli"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-05-24', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Decision Sciences', 'A partir de anos de estudos, a pesquisadora italiana Sabina Leonelli percebeu muitos vieses e diversos problemas e desafios na transformação de dados em conhecimento. O livro reúne ideias e lições extraídas dessas pesquisas, refletindo sobre como cientistas podem utilizar os chamados Big Data para atender às necessidades da sociedade e promover a integridade em pesquisa, entre outras ações. A autora mostra que, apesar dos muitos desafios, a comunidade científica pode aproveitar as potencialidades dos dados, preservando princípios éticos. A professora de Filosofia e História da Ciência da Universidade de Exeter (Reino Unido) compila, nesta obra de tema fundamental para a ciência contemporânea, observações baseadas em mais de uma década de análises das maneiras pelas quais os pesquisadores produzem, gerenciam e interpretam os dados como fontes de conhecimento.', '["big data","scientific research","research integrity","data ethics","data interpretation","philosophy of science"]', '10.7476/9786557081600', '9786557081303', 'https://books.scielo.org/id/p4qk8', NULL, NULL, 'https://books.scielo.org/id/p4qk8/cover/cover_thumbnail.jpeg', 149, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p4s67', 'p4s67', 'Cidade(s), gênero e raça em contexto de pobreza urbana', NULL, '["Hita, Maria Gabriela"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro aborda temas de desigualdades e pobreza urbana que partem de análises cruzadas e recortes interseccionais entre raça e gênero nos quais se discutem algumas das mais urgentes e relevantes questões de sociedades na atualidade. Especial foco foi dado às dinâmicas e relações de diferentes grupos e estratos sociais de sociedades brasileiras e africanas em constante movimento.', '["urban poverty","intersectionality","race","gender","social inequality","cities","social strata","Brazilian society","African societies"]', '10.7476/9786556308869', '9786556304571', 'https://books.scielo.org/id/p4s67', NULL, NULL, 'https://books.scielo.org/id/p4s67/cover/cover_thumbnail.jpeg', 406, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p5', 'p5', 'O Português Afro-Brasileiro', NULL, '["Dante Lucchesi","Alan Norman Baxter","Ilza Maria de Oliveira Ribeiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Organizado pelos professores Dante Lucchesi e Ilza Ribeiro, da Universidade Federal da Bahia, e pelo professor Allan Baxter, da Universidade de Macau, teve a colaboração de vários autores, professores de outras universidades do mesmo Estado, além de mestres, doutores e pós-graduandos, em geral oriundos daquela mesma universidade, integrantes do grupo de pesquisa ali constituído, e que vêm se dedicando ao estudo da realidade lingüística brasileira. Baseado na análise de amostras da fala de algumas comunidades rurais afro-brasileiras isoladas, no caso, quatro comunidades do Estado da Bahia - Helvécia, Cinzento, Rio de Contas e Sapé -, o livro apresenta os resultados obtidos pela aplicação de modelos teóricos que transitam da gerativa, de princípios e parâmetros, à sociolingüística variacionista, dentro daquela linha fecunda inaugurada pelo Prof. Tarallo nos anos oitenta.Dividido em duas partes, são apresentados, na primeira, os fundamentos teóricos e metodológicos nos quais se baseou a pesquisa e também o contexto sócio histórico das comunidades analisadas. Na segunda parte, são isolados dezesseis ''pontos-diagnósticos'' (apropriando-me da expressão utilizada pelo Professor Aryon Rodrigues em sua análise comparativa das línguas tupi-guarani), pelos quais se pode tanto esboçar um retrato das variedades vernáculas das comunidades pesquisadas, quanto levantar hipóteses, já mais bem fundadas, sobre a história do contato do português com as línguas africanas em território brasileiro.', '["Afro-Brazilian Portuguese","isolated rural areas","Rio de Contas","sape","Bahia","sociolinguistic variation","generative linguistics","Principles and Parameters"]', '10.7476/9788523208752', '9788523208752', 'https://books.scielo.org/id/p5', 'https://books.scielo.org/id/p5/pdf/lucchesi-9788523208752.pdf', NULL, 'https://books.scielo.org/id/p5/cover/cover_thumbnail.jpeg', NULL, 154, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p5cwn', 'p5cwn', 'Um naturalista no Antropoceno: Um biólogo em busca do selvagem', NULL, '["Mauro Galetti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Mauro Galetti faz sua estreia com um livro que é um misto de autobiografia com reflexão sobre o futuro da vida na Era dos Humanos, o Antropoceno. Reunindo experiências de viagens a lugares inóspitos, como as ilhas de Galápagos, Bahamas e Bornéu, e a formação como cientista, Um naturalista no Antropoceno é um livro inspirador que irá transformar nossa visão da natureza. Com o olhar crítico e humorado, o autor nos leva a refletir sobre o papel do ser humano no planeta Terra e discute maneiras de como podemos sobreviver ao Antropoceno.', '["Anthropocene","naturalism","human role in nature","future of life","Galápagos Islands","Bahamas","Borneo","scientific training","human survival","human-nature relationship"]', '10.7476/9786557144541', '9786557144541', 'https://books.scielo.org/id/p5cwn', 'https://books.scielo.org/id/p5cwn/pdf/galetti-9786557144541.pdf', NULL, 'https://books.scielo.org/id/p5cwn/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p5mw5', 'p5mw5', 'História do pensamento geográfico e epistemologia em Geografia', NULL, '["Paulo Roberto Teixeira de Godoy"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A História do Pensamento Geográfico consiste em um campo de discussões teóricas, filosóficas, institucionais, epistemológicas e metodológicas.Embora sua relevância seja reconhecida entre os geógrafos, existem poucos estudos dedicados aos problemas enfrentados pela geografia em sua trajetória científica, histórica e social.O objetivo deste livro não é suprir as deficiências ou as lacunas da História do Pensamento Geográfico e, tampouco, adotar o escrúpulo historicista de compreensão de uma história petrificada em narrativas e pontos de vista acerca de problemas científicos que interessam a poucos.Nesse sentido, não se trata, fundamentalmente, da História do Pensamento Geográfico como tradicionalmente se concebe o conjunto de temas relacionados ao desenvolvimento científico da geografia.Se essa fosse a sua finalidade, sua deficiência seria manifesta e o desequilíbrio entre as partes retiraria todo o seu sentido.O seu propósito é o de reunir as contribuições de docentes e pósgraduandos em geografia em torno de dois grandes eixos temáticos: História do Pensamento Geográfico e epistemologia em geografia.', '["history of geographical thought","epistemology of geography","philosophy of geography","history of geography","historiography of geography","social history of science"]', '10.7476/9788579831270', '9788579831270', 'https://books.scielo.org/id/p5mw5', 'https://books.scielo.org/id/p5mw5/pdf/godoy-9788579831270.pdf', NULL, 'https://books.scielo.org/id/p5mw5/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p5z3b', 'p5z3b', 'Epidemiologia: contextos e pluralidade', NULL, '["Maurício L. Barreto","Naomar de Almeida Filho","Renato Peixoto Veras","Rita Barradas Barata"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'APRESENTAÇÃO O presente volume, que reúne importantes contribuiçőes apresentadas no III Congresso Brasileiro de Epidemiologia, II Congresso Ibero-Americano e I Congresso Latino-Americano, testemunha, de maneira ímpar, ainda quando comparado aos demais textos que integram esta série de coletâneas, a diversidade da produção na epidemiologia contemporânea e o vigor de suas inter-relaçőes com diversos campos do conhecimento humano.Propositadamente, os editores escapam aqui ŕs definiçőes temáticas em proveito da abertura do debate epidemiológico ŕ multidisciplinaridade, senão ŕ verdadeira interdisciplinaridade.O livro que o leitor tem em mãos cumpre plenamente as expectativas formuladas no Boletim Especial da ABRASCO, publicado em julho de 1995, logo após a realização do Congresso.Naquela ocasião, a Comissão de Epidemiologia da ABRASCO expressou o desejo de congregar todas as correntes de pensamento atuantes no campo da disciplina, desejo plenamente satisfeito por um congresso que primou pela abertura de novas perspectivas e pelo diálogo da epidemiologia com diversas cięncias e práticas.Além disso, a interação entre instituiçőes e grupos de pesquisadores brasileiros e colegas latino e ibero-americanos, também registrada neste volume, revelou-se muito fecunda e deu origem a parcerias de trabalho e debates que vęm atravessando esses anos transcorridos entre o Congresso de 1995 e a publicação dos trabalhos então apresentados.Seria impossível resumir aqui a variedade de temas que compőem o presente livro e optamos, antes, por tentar delinear alguns eixos que possibilitam encontrar certa unidade em meio ŕ vigorosa diversidade de perspectivas, métodos e propósitos.É possível divisar na epidemiologia contemporânea a abertura para um diálogo profícuo, tanto com as cięncias biológicas quanto com as humanas, além de um esforço sistemático de fundamentação epistemológica da disciplina.Nesse último sentido, é muito interessante a tentativa, aqui registrada, de reflexão sobre a interface entre epidemiologia, matemática e filosofia, e seus desdobramentos nas questőes metodológicas centrais ŕ evolução recente da epidemiologia.No âmbito do debate simultâneo com as interfaces biológicas e sociais, temos aqui exemplos de como abordar questőes contemporâneas complexas, como a pandemia pelo HIV/AIDS, a partir de perspectivas diferentes e complementares que, sem perder sua especificidade e densidade epistemológica própria, contribuem para a compreensão e enfrentamento do problema.Um campo em que estas diferentes perspectivas se imbricam de maneira clara e que constitui um desafio ŕ cięncia contemporânea como um todo é a possibilidade de desenvolver vacinas anti-HIV, que aqui comparece sob as óticas da diversidade biológica, da factibilidade de seu desenvolvimento e avaliação in loco dos paradigmas que presidem a dinâmica de investigação e desenvolvimento, assim como da sua interação com sistemas simbólicos de representação social.Muito estimulante, também, é o diálogo da epidemiologia com uma outra disciplina por si só interdisciplinar -a paleoparasitologia-, que combina um conjunto de estratégias de investigação biológica e histórica.Se antes, no caso da AIDS, falamos da contemporaneidade e de problemas que certamente nos acompanharão no futuro discernível, no caso da paleoparasitologia reconstruímos cenários do passado, estabelecendo, contudo, também um exercício prospectivo, pois como dizia um arguto observador da marcha dos tempos: "quando não conhecemos nosso passado estamos condenados a repeti-lo".Outra linha de inter-relação da epidemiologia, abordada neste livro, refere-se ŕ utilização de seus conceitos e métodos na implementação de açőes de saúde e políticas, tanto sob o ponto de vista macropolítico de um país europeu, como ao estudo de caso de uma aplicação específica da vigilância epidemiológica a ''cenas sociais'' que congregam oportunidades, pessoas e questőes de saúde: as regiőes auríferas.Desdobrando esta última perspectiva, vemos que se tem ampliado enormemente a participação de questőes ambientais no âmbito da epidemiologia contemporânea -temas abordados por outro texto que discute os riscos decorrentes da exposição a solventes orgânicos -, o que se vem fazendo acompanhar por um refinamento das técnicas de análise das questőes de saúde no espaço, aqui representadas pela análise de microáreas.Encontramos também tematizado nesta publicação o impacto dos meios de comunicação no desenvolvimento da epidemiologia e o da dinâmica da tecnologia médica no que é veiculado pela mídia.Tem-se aí uma rua de mão dupla: o impacto social das novas tecnologias de comunicação tornando disponíveis informaçőes que subsidiam as análises epidemiológicas e os modos como o progresso tecnológico no campo da saúde são retraduzidos para seus destinatários -os pacientes e os espectadores e leitores dos meios de comunicação.Entre os temas de grande relevância social para os países em desenvolvimento, a presente coletânea inclui artigos sobre as perspectivas de eliminação do sarampo no Brasil e as estratégias metodológicas relativas a um problema infelizmente ainda importante entre nós: a desnutrição dos adultos.Deixamos para o final, como que resumindo os desdobramentos de tudo que é discutido ao longo desta obra, duas questőes fundamentais a uma disciplina que vem ampliando consideravelmente seu escopo de atuação na sociedade e sua capacidade de intervenção preventiva -trata-se dos modos como a ''cięncia dos riscos'' traduz-se em uma ''cultura da enfermidade'' e a bioética.Se quisermos, de fato, fazer com que a epidemiologia constitua um eixo fundamental da saúde coletiva, temos que efetivamente traduzir nossos achados em informaçőes compreensíveis e culturalmente apropriadas; só assim poderemos fazer com que hábitos, comportamentos e mesmo estilos de vida possam ser transformados, de maneira consensual e não-autoritária, em alternativas mais saudáveis para as comunidades e os indivíduos.A questão ética perpassa todas as dimensőes abordadas anteriormente, ŕ medida que a disciplina amplia-se, complexifica-se e corre riscos de ''internalismo'' exacerbado, dando as costas a seu propósito básico de ser, a um só tempo, um conjunto sistemático de métodos e um instrumento para aprimorar as condiçőes de vida dos indivíduos e coletividades.', '["interdisciplinarity","multidisciplinarity","epistemology of epidemiology","philosophy of science","epidemiological methods","scientific careers"]', '10.7476/9788575412633', '9788575412633', 'https://books.scielo.org/id/p5z3b', 'https://books.scielo.org/id/p5z3b/pdf/veras-9788575412633.pdf', NULL, 'https://books.scielo.org/id/p5z3b/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p65hq', 'p65hq', 'Capoeira Regional: a escola de Mestre Bimba', NULL, '["Hellio Campos"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro é um convite e ao mesmo tempo uma rara oportunidade de viajar de volta ao passado. Não só aqueles que foram alunos do Mestre Bimba e privaram da sua intimidade podem reconhecer a importância do tema e a firmeza do seu conteúdo. Mestre Bimba, lenda da capoeiragem, é retratado como um vitorioso na medida em que conseguiu driblar uma corrente social dominante contrária à prática da capoeira.', '["social resistance","Afro-Brazilian culture","traditional dance and music"]', '10.7476/9788523217273', '9788523217273', 'https://books.scielo.org/id/p65hq', 'https://books.scielo.org/id/p65hq/pdf/campos-9788523217273.pdf', NULL, 'https://books.scielo.org/id/p65hq/cover/cover_thumbnail.jpeg', NULL, 37, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p6ztd', 'p6ztd', 'Terceirização da gestão na Saúde Pública', NULL, '["Stefania Becattini Vaccaro","Thaís dos Santos Gomes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-07-13', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro busca dar visibilidade às mudanças que vêm ocorrendo no âmbito do Sistema Único de Saúde (SUS). As autoras mostram como essas mudanças do SUS estão conectadas às bases de transformações socioeconômicas do país. Em quatro capítulos, Stefania Vaccaro e Thaís dos Santos explicam as atividades estatais e as características da estrutura organizacional no Brasil, passam pelo dever estatal de promoção de saúde e pela estrutura do SUS e abordam ainda o conceito e o histórico evolutivo do fenômeno da terceirização. Por fim, elas analisam a terceirização na saúde pública, realizada por meio da contratualização com as organizações sociais de saúde (OSS). A obra examina o processo histórico de construção do SUS numa análise interdisciplinar entre direito e saúde.', '["public health","health promotion","state responsibility for health","health system organization","history of outsourcing","law and health","socio-economic change"]', '10.7476/9786557081631', '9786557081266', 'https://books.scielo.org/id/p6ztd', NULL, NULL, 'https://books.scielo.org/id/p6ztd/cover/cover_thumbnail.jpeg', 128, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p7249', 'p7249', 'Tecnologias vestíveis: memória e intimidade sobre o corpo', NULL, '["Thatiane Mendes Duque"]', 'Editora UEMG', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro investiga as interações entre corpo, roupa e tecnologias vestíveis. Para tanto, a obra propõe tessituras sobre memória, autobiografia e intimidade. Ao discutir as tecnologias vestíveis, como relógios inteligentes e óculos de realidade virtual ou aumentada, o texto se propõe a pensar de que maneiras a tecnologia permite a ressignificação contínua do contato, do afeto e do desejo.', '["wearable devices","body","clothing","memory","intimacy","autobiographical memory","smartwatches","virtual reality glasses","augmented reality","affect","desire"]', '10.7476/9786586832426', '9786586832426', 'https://books.scielo.org/id/p7249', 'https://books.scielo.org/id/p7249/pdf/duque-9786586832426.pdf', NULL, 'https://books.scielo.org/id/p7249/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p77k3', 'p77k3', 'De Gregório a Raul: literatura baiana em curso, vol. 2', 'literatura baiana em curso, vol. 2', '["Jorge de Souza Araujo"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Revisão crítica da literatura baiana em seus confrontos sincrônicos e diacrônicos, reordenando a série histórica a partir de pressupostos estéticos e ideológicos, ultrapassando ou confirmando as rasuras estilísticas. O volume II compreende as variáveis estilísticas que se imbricam no Parnasianismo e suas derivações para o Simbolismo, e como deságuam na ambivalência que a modernidade estética implica em seus cultores, a ponto de fazer perdurar, muito além do tempo, a proposição de valência parnasiana, salvo a exceção consagradora alcançada pelos simbolistas Artur de Sales, Francisco Mangabeira, Pedro Kilkerry e Melo Barreto Filho.', '["Bahian literature","literary history","symbolism","literary stylistics","modernity","Raul Pompeia"]', '10.7476/9788574556475', '9788574555881', 'https://books.scielo.org/id/p77k3', NULL, NULL, 'https://books.scielo.org/id/p77k3/cover/cover_thumbnail.jpeg', 576, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p7jsg', 'p7jsg', 'Monografias de Plantas Medicinais Brasileiras e Aclimatadas: Volume II', NULL, '["B. Gilbert","Lúcio Ferreira Alves","Rita de Fátima Favoreto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-12-15', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Procurando Razões é um livro surpreendente. Partindo de um conjunto de temas clássicos da filosofia, como conhecimento, racionalidade, ceticismo e virtudes intelectuais, Waldomiro Silva Filho desenvolve um texto único no estilo e na abordagem ao narrar o percurso de uma investigação sobre a noção de reflexão. Escrito na forma ensaística, este livro cruza a própria experiência pessoal do autor com referências filosóficas e literárias. Em vez de avançar, como normalmente acontece com livros de filosofia, para uma conclusão ou na defesa de uma teoria, o texto mostra como uma interrogação inicial sobre qual o bem que podemos conquistar com a reflexão foi se transformando numa dúvida sobre por que algumas vezes a reflexão é importante e porque razões importam.', '["medicinal plants","Brazilian medicinal plants","acclimatized plants","botanical monograph","herbal medicine","primary care","Brazilian Pharmacopoeia","ethnobotany","reflection","reason","knowledge","rationality","skepticism","intellectual virtues","philosophy of reason"]', '10.7476/9786557081778', '9786557081778', 'https://books.scielo.org/id/p7jsg', 'https://books.scielo.org/id/p7jsg/pdf/gilbert-9786557081778.pdf', NULL, 'https://books.scielo.org/id/p7jsg/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p7wkm', 'p7wkm', 'Universidade e sociedade: projetos de extensão da FCLAr-Unesp e suas ações transformadoras', NULL, '["Cláudio César de Paiva"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A universidade pública brasileira tem por objetivo buscar a excelência no desempenho de três grandes norteadores: o ensino, a pesquisa e a extensão.Longe de serem atividades estanques, essas tarefas possuem uma relação intrínseca.Para que o ensino oferecido pelas universidades públicas brasileiras, na graduação e na pós--graduação, seja inovador, arrojado e de alta qualidade, é impos sível disso ciar sua prática da pesquisa que o alimenta e que por ele é alimentada.Contrariamente à ideia de que o pesquisador é um sujeito isolado, fechado em si mesmo, voltado para a construção de teorias abstratas ou preocupado em aprimorar as já existentes, os trabalhos de investigação que se desenvolvem na universidade pública devem ter as atividades de ensino como um de seus principais objetivos.No entanto, como a universidade pública deve agir em relação à extensão?Qual é seu papel?O documento elaborado durante o Fórum de Pró-Reitores de Extensão das Universidades Públicas Brasileiras (Forproex), em 2012, intitulado "Política Nacional de Extensão Universitária", apresenta as metas de uma política que visa tornar a extensão realizada pelas universidades públicas "um instrumento de mudança social em direção à justiça, à solidariedade e à democracia".Para tanto, reafirma os quinze objetivos que nortearam as discussões sobre o tema durante o Fórum.O que se pretende ressaltar neste livro, portanto, é a importância do papel da extensão, responsável pela ligação que a universidade deve estabelecer com a sociedade brasileira em geral, discutindo seus problemas e suas carências, no âmbito das atividades de ensino e de pesquisa.É por meio da extensão que tudo o que se cria e se ensina na universidade influencia e é influenciado pelas demandas sociais.Não é à toa que a epígrafe escolhida para encabeçar o documento produzido pelo Fórum citado anteriormente corresponde a um trecho da obra A universidade do século XXI, de Boaventura de Souza Santos. 1 Segundo o autor, a atividade de extensão deve ser a resposta da universidade ao capitalismo global, cuja finalidade consiste em participar ativamente "na construção da coesão social, no aprofundamento da democracia, na luta contra a exclusão social e a degradação ambiental, na defesa da diver sidade cultural".Assim, com o intuito de divulgar suas ações extensionistas e promover um debate em torno de suas propostas, a Universidade Estadual Paulista "Júlio de Mesquita Filho" (por meio do Edital n.005-2014-Proex) criou o Programa de Publicações Digitais Coleção Extensão Universitária -Selo Cultura Acadêmica.O objetivo dessa publicação consiste na disseminação digital da produção acadêmica na extensão uni versitária para a sociedade, desenvolvida pelos docentes e pesqui sadores em conjunto com graduandos, pós-graduandos, pós -graduados, ser vidores técnicos', '["university extension","university-society relationship","social change","university teaching and research","Boaventura de Sousa Santos","public universities","social justice","solidarity","university extension project","teaching-research-extension integration","São Paulo state"]', '10.7476/9788579837562', '9788579837562', 'https://books.scielo.org/id/p7wkm', 'https://books.scielo.org/id/p7wkm/pdf/paiva-9788579837562.pdf', NULL, 'https://books.scielo.org/id/p7wkm/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p7xnb', 'p7xnb', 'Ambiente, saúde, sustentabilidade: fundamentos, bases científicas e práticas', NULL, '["Franco Netto, Guilherme","Villardi, Juliana Wotzasek Rulli"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2024, '2024-10-31', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Este livro, na forma de coletânea, é uma publicação pioneira que tem por objetivo servir de base de referência na formação de graduandos e pós-graduandos, além de professores, pesquisadores, gestores públicos e formadores de opinião, visando contribuir para a produção, a disseminação e o compartilhamento de conhecimentos em saúde, ambiente e sustentabilidade (SAS), voltados para o fortalecimento e a consolidação do Sistema Único de Saúde (SUS) e a promoção da saúde e da qualidade de vida da população brasileira.', '["environmental health","sustainability","health promotion","quality of life","Unified Health System (SUS)","health education","knowledge dissemination"]', '10.7476/9786557082256', '9786557081884', 'https://books.scielo.org/id/p7xnb', NULL, NULL, 'https://books.scielo.org/id/p7xnb/cover/cover_thumbnail.jpeg', 602, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p7zhx', 'p7zhx', 'A trajetória da democracia socialista: da fundação ao PT', NULL, '["Vitor Amorim de Ângelo"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os partidos políticos frequentemente são objetos de estudo nas Ciências Sociais. Entretanto, o mesmo não se pode dizer de suas tendências internas, que pouca atenção têm recebido dos pesquisadores. O livro de Vitor Amorim de Angelo vem justamente cumprir este papel. Com base numa farta documentação, o autor reconstituiu a história da organização trotskista Democracia Socialista, uma das tendências do Partido dos Trabalhadores (PT). Com uma narrativa que não deixa escapar os detalhes dessa trajetória, o livro apresenta ao leitor o fecundo debate travado nos anos 1980 entre as principais correntes do partido, especialmente as trotskistas. Com uma postura sempre conciliatória, a Democracia Socialista não apenas se manteve na legenda, como também cresceu na estrutura partidária. Porém, sem conseguir hegemonizar seu programa dentro do PT, precisou justificar a permanência num partido que não seguiu pelo caminho da revolução.', '["Workers'' Party (PT)","Trotskyism","Brazilian left","party organization","revolutionary politics"]', '10.7476/9788576002932', '9788576002932', 'https://books.scielo.org/id/p7zhx', 'https://books.scielo.org/id/p7zhx/pdf/angelo-9788576002932.pdf', NULL, 'https://books.scielo.org/id/p7zhx/cover/cover_thumbnail.jpeg', NULL, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p87q7', 'p87q7', 'Genealogia de uma operação historiográfica: Edward Palmer Thomp-son, Michel Foucault e os historiadores brasileiros da década de 1980', NULL, '["Igor Guedes Ramos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Entre as décadas de 1960 e 1980 foram publicadas as principais pesquisas históricas de Edward Palmer Thompson e de Michel Foucault, cada uma a seu modo, impactou significativamente a produção historiográfica mundial estabelecendo problemas, polêmicas e transformando as formas de se fazer história. Neste livro, fundamentado em vasta pesquisa empírica, Igor Guedes Ramos analisa esse impacto na historiografia brasileira: na primeira parte, discuti, compara e contrasta os pensamentos de Thompson e de Foucault e, na segunda parte, as condições socioculturais e institucionais, as formas e os desdobramentos daapropriação desses pensamentos pelos historiadores brasileiros até o ano de 1990.', '["E. P. Thompson","Michel Foucault","Brazilian historiography","reception of Foucault"]', '10.7476/9788579837067', '9788579837067', 'https://books.scielo.org/id/p87q7', 'https://books.scielo.org/id/p87q7/pdf/ramos-9788579837067.pdf', NULL, 'https://books.scielo.org/id/p87q7/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p8bjv', 'p8bjv', 'Filosofia da educação matemática: fenomenologia, concepção, possibilidades didático-pedagógicas', NULL, '["María Aparecida Viggiani Bicudo"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro preenche uma lacuna no campo dos estudos fenomenológicos porque não é apenas uma reflexão sobre o significado da Matemática - primeiro nível da pesquisa-, mas uma operação mais complexa, que constitui o segundo nível da pesquisa e alcança uma das intenções profundas da Escola Fenomenológica, a de possibilitar uma fundamentação teórica para os especialistas das diferentes disciplinas.', '["philosophy of mathematics education","phenomenology","mathematical meaning"]', '10.7476/9788539304370', '9788571399990', 'https://books.scielo.org/id/p8bjv', NULL, NULL, 'https://books.scielo.org/id/p8bjv/cover/cover_thumbnail.jpeg', 243, 27, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p8hfz', 'p8hfz', 'As primeiras estórias de Guimarães Rosa', NULL, '["Castro, Gustavo de","Rowland, Clara","Bessa, Leandro"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em 2022, o livro Primeiras Estórias (1962), de João Guimarães Rosa, completou 60 anos. A Universidade de Brasília (UnB) realizou um evento internacional comemorativo, copatrocinado pela Universidade Nova de Lisboa (UNL) e Universidade Católica de Brasília (UCB), CNPq, Museu Casa Guimarães Rosa (MCGR), da Secretaria de Cultura e Turismo do Estado de Minas Gerais e financiado pela Fundação de Apoio à Pesquisa do Distrito Federal (FAP-DF). Foram programadas vinte e uma aulas cada qual com o nome de um dos respectivos contos do livro. As aulas (conferências) ficaram sob a responsabilidade de um professor convidado ou especialista na temática tratada. O livro proposto para a Editora da UnB, portanto, espelha a sequência dessas aulas e terá apresentação geral de Clara Rowland (UNL). Trata-se de obra de peso acadêmico considerável e único no gênero nos estudos rosianos. Deve-se destacar o valor simbólico de a Editora da UnB se associar ao nome de Guimarães Rosa, numa obra com potencial de se tornar obra de referência nos estudos rosianos, de penetração entre professores e estudantes de graduação e pós-graduação e de vendas. Destaca-se o conjunto de contribuições teóricas inéditas, a excelência dos autores reunidos e a reunião de grupos de pesquisa nacionais e internacionais.', '["Guimarães Rosa","Primeiras Estórias","short stories","Brazilian literature","literary criticism","Universidade de Brasília"]', '10.7476/9786558462743', '9786558460756', 'https://books.scielo.org/id/p8hfz', NULL, NULL, 'https://books.scielo.org/id/p8hfz/cover/cover_thumbnail.jpeg', 454, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p8n9x', 'p8n9x', 'Fantasmas modernos: montagem de uma outra herança v. 1', NULL, '["Paola Berenstein Jacques"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'O livro é uma contribuição à história do pensamento urbanístico e suas tradições. A obra se constrói por meio da montagem, operação que permite criar oposições, fricções e incongruências, na qual a impureza é o grande libelo conceitual, ao lado da busca incessante da alteridade. Nesse labirinto, tensiona-se pensamento e argumento, instigando suas possibilidades e limites. Trata-se de um livro dedicado aos vários outros deserdados da história oficial do movimento moderno em arquitetura e urbanismo, evidenciando que uma herança, qualquer herança, é sempre uma montagem, uma construção, e que essa herança que a autora buscou montar é apenas uma entre várias outras possíveis.', '["urban planning history","modern architecture","architectural heritage","montage","otherness","impurities","Modern Movement"]', '10.7476/9786556301969', '9786556301969', 'https://books.scielo.org/id/p8n9x', 'https://books.scielo.org/id/p8n9x/pdf/jacques-9786556301969.pdf', NULL, 'https://books.scielo.org/id/p8n9x/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p8pr7', 'p8pr7', 'Capitalismo autoritário e campesinato: um estudo comparativo a partir da fronteira em movimento', NULL, '["Otávio Guilherme Otávio Guilherme"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A preocupação temática inicial – a ocupação de áreas novas ou, na expressão anglo-saxã consagrada, a fronteira em movimento – e que serviu como ponto de entrada para uma discussão mais ampla, prende-se a um interesse de pesquisa despertado sob a influência do Dr. Roberto Cardoso de Oliveira e que desenvolvi durante vários anos no âmbito do Programa de Pós-Graduação em Antropologia Social (doravante referido como PPGAS) do Museu Nacional da Universidade Federal do Rio de Janeiro (Velho, 1967 e Velho, 1972). [trecho retirado do Prefácio do livro]', '["authoritarian capitalism","peasants","land occupation","agricultural history","comparative analysis","Roberto Cardoso de Oliveira"]', '10.7476/9788599662922', '9788599662922', 'https://books.scielo.org/id/p8pr7', 'https://books.scielo.org/id/p8pr7/pdf/velho-9788599662922.pdf', NULL, 'https://books.scielo.org/id/p8pr7/cover/cover_thumbnail.jpeg', NULL, 36, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p9949', 'p9949', 'O corpo na história', NULL, '["José Carlos Rodrigues"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Resultado de estudo que o autor vem desenvolvendo há alguns anos, tendo inicialmente por objeto as representações sociais do corpo e da morte. O ponto de partida histórico arbitrado pelo autor - "porque qualquer recorte é arbitrário" - é a Idade Média, por vários motivos, entre os quais: por ser uma etapa histórica contra a qual as mentalidades e sensibilidades capitalistas se definem; por ser o ''outro específico'' da civilização moderna e contemporânea, oferecendo, portanto, excelente material para pensar, indagar sobre, rever, contrastar e relativizar concepções e supostas verdades sobre o corpo.', '["body","social representations of the body","representation of death","Middle Ages","capitalism","modernity","otherness","history of the body"]', '10.7476/9788575415559', '9788575415559', 'https://books.scielo.org/id/p9949', 'https://books.scielo.org/id/p9949/pdf/rodrigues-9788575415559.pdf', NULL, 'https://books.scielo.org/id/p9949/cover/cover_thumbnail.jpeg', NULL, 31, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-p9jv6', 'p9jv6', 'Impactos da Violência na Saúde', NULL, '["Njaine, Kathie","Assis, Simone Gonçalves de","Constantino, Patricia","Joviana Quintes Avanci"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Originalmente organizado para dar suporte a um curso a distância, o livro extrapola seus objetivos iniciais e compartilha com estudantes, profissionais e gestores de saúde ideias e reflexões para reconhecer e enfrentar a violência como grave problema de saúde pública. A obra contextualiza a violência na realidade brasileira, aborda a história da incorporação do tema na agenda do setor saúde e discute a importância de uma política para a área. Destaca como a família, a escola, a comunidade e a mídia podem e devem ser alvos de medidas de prevenção à violência. De modo didático, descreve cenas e casos de violência que chegam aos serviços de saúde e, em seguida, oferece textos para reflexão e outras sugestões de leitura, de modo que os profissionais possam se preparar para lidar com situações semelhantes. Dessa forma, são estudados e discutidos temas como crianças e adolescentes em situações de violência; formas de institucionalização tradicionalmente reconhecidas pelas relações de violência; violência no trabalho; e violência contra pessoas portadoras de deficiência, mulheres e idosos. Completam a obra um passo a passo para um diagnóstico situacional da violência; uma proposta para a elaboração de um plano local de promoção, prevenção e atenção às situações de violências e acidentes; e exemplos de avaliação de programas e ações nesse campo.', '["violence prevention","violence against children and adolescents","workplace violence","violence against people with disabilities","violence against women","elder abuse","school violence","media and violence","violence policy","program evaluation","Brazil"]', '10.7476/9786557080948', '9786557080948', 'https://books.scielo.org/id/p9jv6', 'https://books.scielo.org/id/p9jv6/pdf/njaine-9786557080948.pdf', NULL, 'https://books.scielo.org/id/p9jv6/cover/cover_thumbnail.jpeg', NULL, 59, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pbkhj', 'pbkhj', 'Diálogos entre feminilidade e maternidade: um estudo sob o olhar da mitologia e da psicanálise', NULL, '["Thássia Souza Emídio"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro tem como objeto de pesquisa os conceitos de feminilidade e maternidade, e o foco de interesse centra-se na discussão e na reflexão das figurações e configurações do feminino e da maternidade no mundo contemporâneo. Com o auxílio dos mitos e da história de Narciso, Édipo e Eros e Psiquê, a autora procura se aprofundar no entendimento de como se dá a relação da mulher com a maternidade e a da figura materna com seu filho. A presente obra apresenta-se no entrecruzamento de várias áreas com as quais a psicanálise faz fronteira, como os estudos de gênero, a psicologia e a sociologia das relações familiares. Além disso, recoloca a questão da psicanálise nos estudos dos mitos e das produções literárias e culturais em geral, fazendo, assim, a ligação psicanálise-cultura, o olhar da apropriação que o sujeito faz dos componentes culturais a sua disposição.', '["femininity","motherhood","mother-child relationship","myth","psychoanalysis","Narcissus myth","Oedipus myth","gender studies","family relationships","psychoanalysis and culture"]', '10.7476/9786557145210', '9786557145210', 'https://books.scielo.org/id/pbkhj', 'https://books.scielo.org/id/pbkhj/pdf/emidio-9786557145210.pdf', NULL, 'https://books.scielo.org/id/pbkhj/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pbqp3', 'pbqp3', 'Escravos da desigualdade: um estudo sobre o uso repressivo da força de trabalho hoje', NULL, '["Neide Esterci"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A preocupação que orienta este trabalho é sobretudo a necessidade de compreender as atitudes das pessoas contra as quais são praticadas formas extremas de exploração e dominação, baseadas na violência física e/ou simbólica e referidas como formas atuais de escravidão.[trecho retirado da apresentação do livro]', '["modern slavery","forced labor","labor exploitation","physical violence","symbolic violence","inequality","domination"]', '10.7476/9788599662618', '9788599662618', 'https://books.scielo.org/id/pbqp3', 'https://books.scielo.org/id/pbqp3/pdf/esterci-9788599662618.pdf', NULL, 'https://books.scielo.org/id/pbqp3/cover/cover_thumbnail.jpeg', NULL, 17, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pcd44', 'pcd44', 'Ensaios sobre fenomenologia: Husserl, Heidegger e Merleau-Ponty', NULL, '["Lima, Antonio Balbino Marçal"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Conjunto de textos de pesquisadores que discutem alguns dos temas mais importantes da fenomenologia, a partir dos fundamentos de Husserl e sua influência em diversas correntes da filosofia contemporânea, principalmente a ontologia de Martin Heidegger e a fenomenologia da existência de Maurice Merleau-Ponty.', '["phenomenology","Edmund Husserl","Martin Heidegger","Merleau-Ponty","ontology","phenomenology of existence"]', '10.7476/9788574554440', '9788574554440', 'https://books.scielo.org/id/pcd44', 'https://books.scielo.org/id/pcd44/pdf/lima-9788574554440.pdf', NULL, 'https://books.scielo.org/id/pcd44/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pchmj', 'pchmj', 'Antropologías: múltiples perspectivas para el estudio del ser humano', NULL, '["Luis Fernando Garcés Velásquez","Luis Miguel Carranza Peco"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Las contribuciones de esta publicación pretenden ejemplificar los diferentes caminos disponibles y la posible colaboración entre campos del saber antropológico que en ocasiones podemos considerar como totalmente ajenos a su campo. Dicho de otro modo, se trata convocar conocimientos con bases científicas sobre el ser humano, ya sea con el punto de mira en el pasado, presente, o con pretensiones predictivas. El libro se organiza alternando los textos de investigadores cuya actividad se desarrolla en los continentes americano y europeo respectivamente. Esta estructura resulta independiente de los casos de estudio desarrollados puesto que algunos buscan resolver problemáticas fuera de las propias fronteras de sus instituciones de residencia, otros abordan situaciones de su más directa cotidianeidad, o directamente resultan de aplicación amplia, independientemente del objeto de estudio al cual se apliquen. En otras palabras, los diferentes temas desarrollados por los autores, en los que son especialistas, suponen una excusa con la cual justificar la heterogeneidad de metodologías en la investigación antropológica.', '["anthropology of the human being","human evolution","human behavior","everyday life"]', '10.7476/9789978106761', '9789978106761', 'https://books.scielo.org/id/pchmj', 'https://books.scielo.org/id/pchmj/pdf/garces-9789978106761.pdf', NULL, 'https://books.scielo.org/id/pchmj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pcjtq', 'pcjtq', 'Cidade do índio: transformações e cotidiano em Iauaretê', NULL, '["Geraldo Andrello"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O autor apresenta um estudo etnográfico de povos de Iaueretê (Tariano e Tukano), no Alto Rio Negro, detendo-se nas transformações sociais que vêm sofrendo em função do contato com o homem branco. O trabalho inicia-se com um levantamento histórico da ocupação da região, passa por temas como demarcação de terras e, finalmente, apresenta uma análise detida sobre os dois povos, evidenciando seus mitos e a relação com os brancos.', '["Tukano people","Alto Rio Negro","indigenous peoples","social change","land demarcation","indigenous myths","everyday life"]', '10.7476/9788539302895', '9788571396593', 'https://books.scielo.org/id/pcjtq', NULL, NULL, 'https://books.scielo.org/id/pcjtq/cover/cover_thumbnail.jpeg', 448, 70, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pckh6', 'pckh6', 'Saúde coletiva como compromisso: a trajetória da Abrasco', NULL, '["Nísia Trindade Lima","José Francisco Nogueira Paranaguá de Santana"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2001, '2001-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O termo ‘saúde coletiva’ é uma invenção brasileira que hoje está presente na agenda acadêmica e política de países da América Latina, do Caribe e da África e trata, acima de tudo, de uma forma de abordar as relações entre conhecimentos, práticas e direitos referentes à qualidade de vida. A Abrasco – Associação Brasileira de Pós-Graduação em Saúde Coletiva – nasceu em 1979 impregnada por esse sentido de inovação. Na sua carta de identidade, o termo emblemático ‘saúde coletiva’ aparece para romper barreiras e instigar a confluência de conhecimentos e práticas que integram o compromisso com o cuidado da saúde como valor fundamental da condição humana e seu reconhecimento como um direito universal. Este livro comemora a passagem dos seus 25 anos e interessa aos estudiosos e militantes da Reforma Sanitária e àqueles que desejam conhecer um estudo de caso de uma associação profissional que conseguiu manter a integridade acadêmica e torná-la instrumento decisivo de mudança social.', '["collective health","ABRASCO","professional associations","right to health","social change","academic integrity","history of health sciences","Latin America"]', '10.7476/9786557081563', '9786557081563', 'https://books.scielo.org/id/pckh6', 'https://books.scielo.org/id/pckh6/pdf/lima-9786557081563.pdf', NULL, 'https://books.scielo.org/id/pckh6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pcn2d', 'pcn2d', 'John Ruskin e o ensino do desenho no Brasil', NULL, '["Cláudio Silveira Amaral"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O tema principal da obra do crítico de arte inglês John Ruskin foi uma teoria da percepção, cujo objetivo era o ensino do desenho considerado como parte da política industrial lon­drina do século XIX. No Brasil, podemos encontrar a influência do trabalho de Ruskin no Liceu de Artes e Ofícios do Rio de Janeiro (fundado em 1886 pelo arquiteto Joaquim Béthencourt da Silva), que tinha como sócio honorário o escritor Rui Barbosa, leitor de Ruskin. Muitas das ideias ruskinianas influenciaram o método de ensino do desenho no Liceu, que pretendia transformar a cidade do Rio de Janeiro em uma obra de arte. Neste livro, Claudio Silveira do Amaral abre a possibilidade para a revisão das experiências arquitetônicas brasileiras baseadas na concepção da estética ruskiniana, procurando problematizar e rediscutir os alicerces teóricos de nossa sociedade industrial.', '["John Ruskin","drawing instruction","theory of perception","Rui Barbosa","industrial arts","urban aesthetics","Rio de Janeiro","19th-century art criticism"]', '10.7476/9786557145296', '9786557145296', 'https://books.scielo.org/id/pcn2d', 'https://books.scielo.org/id/pcn2d/pdf/amaral-9786557145296.pdf', NULL, 'https://books.scielo.org/id/pcn2d/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pcxf3', 'pcxf3', 'Entre as fronteiras do ensino, da pesquisa e da extensão: estudos na área de Letras', NULL, '["Aline Cassol Daga Cavalheiro","Ani Carla Marchesan","Ângela Derlise Stübe","Cristiane Horst","Luciano Melo de Paula","Mary Neiva Surdi da Luz"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Entre as Fronteiras do Ensino, da Pesquisa e da Extensão: estudos na área de Letras abrange vários estudos no campo da Linguística, da Literatura e do Ensino, os quais resultam de projetos de ensino, pesquisa e/ou extensão desenvolvidos na graduação e na pós-graduação. Trata-se de textos que revelam sobreposições e/ou aproximações entre duas ou mais fronteiras, demonstrando um pouco da diversa rede de trabalhos que constitui o campo dos estudos linguísticos e literários atualmente. A obra demonstra a qualidade e a diversidade de pesquisas e projetos desenvolvidos na região sul do Brasil, reunindo estudos que ampliam as fronteiras do ensino, da pesquisa e da extensão nas diferentes áreas de Letras tanto da graduação quanto da pós-graduação. Seus textos revelam possibilidades de afastamentos, de toques e de aproximações, demonstrando um pouco da diversa rede de estudos que compõe o campo dos estudos linguísticos e literários atualmente. O livro destina-se a profissionais da área de Letras, bem como a pessoas que se interessem por estudos da área.', '["linguistics","literature","teaching, research and extension","southern Brazil","literary studies"]', '10.7476/9786586545258', '9786586545289', 'https://books.scielo.org/id/pcxf3', 'https://books.scielo.org/id/pcxf3/pdf/cavalheiro-9786586545258.pdf', 'https://books.scielo.org/id/pcxf3/epub/cavalheiro-9786586545258.epub', 'https://books.scielo.org/id/pcxf3/cover/cover_thumbnail.jpeg', 152, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pd6q9', 'pd6q9', 'Vacina Antivariólica: ciência, técnica e o poder dos homens, 1808- 1920', NULL, '["Tania Maria Fernandes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta segunda edição revista do livro traz importantes atualizações para a pesquisa no tema. A primeira edição discutia as relações entre ciência, técnica e produção, tendo como referência a descoberta de Jenner e as reflexões de Pasteur sobre a vacina antivariólica. Aborda a organização institucional implementada durante o Império com o objetivo de possibilitar a prática da vacinação por intermédio da Junta Vacínica e do Instituto Vacínico do Império, introduzindo as primeiras experiências com a vacinação animal no Brasil realizadas na Santa Casa da Misericórdia. Trata, finalmente, da sobrevivência do Instituto Vacínico Municipal em outro contexto institucional, polarizado entre propostas de centralização e descentralização dos poderes públicos para a organização dos serviços de saúde. Destaca o surgimento de um conflito entre o barão de Pedro Affonso e Oswaldo Cruz, que representou uma das polêmicas da época em torno da centralização dos serviços de saúde e que contribuiu para os diferentes alinhamentos que redundaram em posições antagônicas assumidas por médicos e políticos. Este novo volume apresenta ainda novas contribuições bem mais recentes de estudiosos do assunto, além das diretrizes atualizadas pela Opas e OMS no âmbito das campanhas de erradicação desenvolvidas em diversos países.', '["smallpox vaccination","history of vaccination","science and technology","science and production","Jenner","Louis Pasteur","animal vaccination","Santa Casa da Misericórdia","Oswaldo Cruz","decentralization","public health policy","health care organization"]', '10.7476/9786557080955', '9786557080955', 'https://books.scielo.org/id/pd6q9', 'https://books.scielo.org/id/pd6q9/pdf/fernandes-9786557080955.pdf', NULL, 'https://books.scielo.org/id/pd6q9/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pdfcb', 'pdfcb', 'A crítica e o campo do jornalismo: ruptura e continuidade', NULL, '["Mauro de Souza Ventura"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'NOTA PRÉVIAA pesquisa que está na origem deste livro tem por finalidade compreender as relações de ruptura e continuidade, e os conflitos daí decorrentes, que se estabelecem entre a instância da crítica e o campo do jornalismo.Partindo das contribuições teóricas de autores como Pierre Bourdieu, Zygmunt Bauman, Beatriz Sarlo, Frank Kermode e George Steiner, são estudados os processos de configuração da crítica, seja ela de linhagem literária, acadêmica ou jornalística, operados pelas e nas mídias.A partir deste quadro teórico de referência, buscou-se estudar os vínculos socioculturais e interpretativos existentes entre jornalismo, crítica literária e crítica cultural, por meio da análise da produção textual de jornalistas e críticos contemporâneos ou do passado recente, como Otto Maria Carpeaux e José Castello.Em outras palavras, busca-se trazer para o campo da comunicação (e do jornalismo em sentido estrito) a discussão da função da crítica, em sua relação com produtores e público.Este livro está estruturado em cinco capítulos.Enquanto o primeiro busca realizar uma análise contextual das relações entre crítica e jornalismo, os quatro posteriores efetuam análises tópicas, conforme indicadas a seguir. MAURO SOUZA VENTURAA análise inicia com um caso clássico de controvérsia crítica envolvendo um escritor e um crítico.O contexto é o Brasil do final do século XIX, época em que o exercício da crítica (seja de literatura, teatro ou música clássica) era feito nas páginas de jornal.Nesse momento, ainda não se verifica a figura do especialista, problema abordado no capítulo seguinte, que se ocupa das relações existentes entre processos de legitimação e criticabilidade.Tais relações são estudadas a partir das reflexões de Pierre Bourdieu acerca das posições ocupadas pelos agentes (jornalistas, críticos e especialistas) no interior dos campos da produção, reprodução, consagração e difusão de bens simbólicos.Assim, visando a uma aplicação do problema da relação entre a posição dos agentes e suas respectivas tomadas de posição, são examinados três exemplos de posicionamentos críticos veiculados recentemente na mídia.Foram escolhidos três textos críticos: um artigo que contesta a consagração dada à obra de Marcel Duchamp; um texto que formula uma crítica veemente à 28ª Bienal de Arte de São Paulo; e uma análise dos processos de validação e de legitimação de determinadas obras literárias instituídos pelo modernismo brasileiro, no contexto de sua consagração como campo de estudos legítimo.Os três posicionamentos críticos têm em comum o fato de seus autores -Affonso Romano de Sant''Anna, Aracy Amaral e Luís Augusto Fischer, respectivamente -estarem situados fora ou, no mínimo, à margem dos campos artístico e literário aos quais pertencem os objetos e eventos que criticam.O objetivo desta análise é mostrar a existência de uma relação de interdependência entre julgamento crítico e a posição ocupada pelo crítico no campo a partir de exemplos recentes da crítica cultural.', '["literary criticism","journalism","cultural criticism","literary journalism","Pierre Bourdieu","legitimation","cultural field","Otto Maria Carpeaux","Brazilian journalism history","19th-century Brazilian press","media and culture"]', '10.7476/9788579836862', '9788579836862', 'https://books.scielo.org/id/pdfcb', 'https://books.scielo.org/id/pdfcb/pdf/ventura-9788579836862.pdf', NULL, 'https://books.scielo.org/id/pdfcb/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pdj2h', 'pdj2h', 'Doença: um estudo filosófico', NULL, '["Leônidas Hegenberg"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Trata-se de um conjunto de artigos - cada qual com identidade própria, mas com unidade entre si - de iatrofilosofia (filosofia da medicina). Nele, a problemática complexa do adoecer é abordada a partir da estatística, da lógica, da filosofia analítica de língua inglesa e da hermenêutica de tradição alemã. O resultado é uma espécie de ''genealogia'', graças ao recorte original dado pelo autor. É, enfim, uma rica fonte de orientação para os interessados em se aventurar no campo multifacetado das ciências da saúde.', '["disease","philosophy of medicine","genealogy","statistics","logic","analytic philosophy","health sciences"]', '10.7476/9788575412589', '9788575412589', 'https://books.scielo.org/id/pdj2h', 'https://books.scielo.org/id/pdj2h/pdf/hegenberg-9788575412589.pdf', NULL, 'https://books.scielo.org/id/pdj2h/cover/cover_thumbnail.jpeg', NULL, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pdkdq', 'pdkdq', 'Deuses em poéticas: estudos de literatura e teologia', NULL, '["Salma Ferraz"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Studies in Theology and Literature is to systematize these works, presenting their points of convergence and divergence', '["God","poetry","theology and literature","religious poetry","literary theology"]', '10.7476/9788578791186', '9788578791186', 'https://books.scielo.org/id/pdkdq', 'https://books.scielo.org/id/pdkdq/pdf/ferraz-9788578791186.pdf', NULL, 'https://books.scielo.org/id/pdkdq/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pfgkb', 'pfgkb', 'A Cidade barroca na Europa e América Ibérica', NULL, '["Rodrigo Espinha Baeta"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Existem ou existiram cidades barrocas? Essa é questão basilar que o presente livro pretende responder. Para isso, o autor desenvolve uma investigação que tem como fundamento a averiguação da hipótese que assegura que o mesmo espírito que tomaria de assalto o mundo ocidental em todo o século XVII e na maior parte do século XVIII, contaminando a arte, a arquitetura, a literatura, a música, o teatro, teria igualmente alcançado a configuração visiva das cidades. Apontando para a atualidade do estudo crítico da História da Arquitetura, constrói-se a narrativa passando pelo sentido da “Urbanística Barroca”, na França e em Roma, e, posteriormente, frente às grandes contribuições dos mestres do Barroco italiano, discutindo o fenômeno da cidade barroca através da leitura do espaço e suas relações com os monumentos que compõem o drama barroco. O trabalho também aborda de maneira diferenciada como o fenômeno da cidade barroca se manifestou na produção da cidade brasileira setecentista, analisando particularmente Ouro Preto e, na América Hispânica, a cidade de Cusco, com todas as suas similaridades e diversidades.', '["Baroque city","Baroque urbanism","Baroque architecture","Baroque Rome","Baroque drama","Ouro Preto","Cusco","Spanish America","Ibero-America","17th century","18th century"]', '10.7476/9788523219970', '9788523219970', 'https://books.scielo.org/id/pfgkb', 'https://books.scielo.org/id/pfgkb/pdf/baeta-9788523219970.pdf', NULL, 'https://books.scielo.org/id/pfgkb/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pg3b2', 'pg3b2', 'Matérias-primas regionais do sul do Brasil: seleção de frutas, sementes, folhas, rizomas e raízes com potencial tecnológico e comercial', 'seleção de frutas, sementes, folhas, rizomas e raízes com potencial tecnológico e comercial', '["Vânia Zanella Pinto","Eduarda Molardi Bainy","Cláudia Simone Madruga Lima"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'Este livro tem como intuito contribuir para o estado da arte, mas também incentivar o uso dos recursos naturais produzidos no Sul do Brasil, apresentando frutos, plantas, rizomas e sementes nativas, comerciais ou adaptadas a esta região, a partir da pesquisa científica de diversos professores a respeito da composição química e das suas propriedades funcionais, bem como da produção, das formas de consumo e comercialização, do processamento, do desenvolvimento de produtos e das possibilidades para agregação de valor. "Matérias-primas regionais do Sul do Brasil: seleção de frutas, sementes, folhas, rizomas e raízes com potencial tecnológico e comercial", organizado em dez capítulos, reúne mais de uma década de trabalho desenvolvido por professores da UFFS, mais especificamente do curso de graduação em Engenharia de Alimentos e do Programa de Pós-Graduação Stricto sensu em Ciência e Tecnologia de Alimentos, assim como professores de outras instituições, dedicados à popularização da ciência e ao incentivo para agregação de valor a alimentos de origem vegetal.', '["regional raw materials","southern Brazil","native fruits","native seeds","rhizome","roots","chemical composition","functional properties","food processing","value addition","commercialization","plant-based foods"]', '10.7476/9786550191139', '9786550191146', 'https://books.scielo.org/id/pg3b2', 'https://books.scielo.org/id/pg3b2/pdf/pinto-9786550191139.pdf', NULL, 'https://books.scielo.org/id/pg3b2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pgknz', 'pgknz', 'Bases anticoloniais para o ensino histórico-crítico de química: primeiras incinerações', 'primeiras incinerações', '["Pedro Magalhães"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como devem proceder professores que pretendem estabelecer relação entre história e cultura negra, como propõe a Lei nº 11.645/2008, com química na sala de aula? Mesmo o com os mais de 20 anos de existência da obrigatoriedade do conteúdo na Lei de Diretrizes e Bases da Educação Nacional os professores não foram ensinados o que considerar num planejamento, quais conteúdos ensinar, onde estudar, quais fontes buscar para fazer essa relação entre história e cultura negra com química porque esses elementos são fundantes para realizar qualquer trabalho na sala de aula. Em seu primeiro livro, Pedro Magalhães propõe os fundamentos teóricos para que o ensino de história e cultura africana e afro-brasileira nas aulas de química deixe de ser quase impossível para se tornar sistemático e viável. Longe de uma receita, o pesquisador explora a teoria na prática em exemplos práticos para auxiliar outros docentes no objetivo de colocar a ciência a serviço do proletariado negro.', '["Black history","Afro-Brazilian culture","Law 11.645/2008","chemistry curriculum","teacher professional development"]', '10.7476/9786556309095', '9786556307657', 'https://books.scielo.org/id/pgknz', 'https://books.scielo.org/id/pgknz/pdf/magalhaes-9786556309095.pdf', NULL, 'https://books.scielo.org/id/pgknz/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pgmcz', 'pgmcz', 'A música no candomblé: etnomusicologia no Ilê Axé Opô Aganjú, Bahia', NULL, '["Lühning Angela"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro de Angela Lühning é um testemunho de uma época que apresenta importantes aspectos relativos ao funcionamento do candomblé da nação nagô-ketu, religião presente nas diversas regiões do país. Ponto principal são as intrínsecas relações entre o repertório cantado nas cerimônias públicas e suas funções rituais. Realizadas no final dos anos 1980, as análises de cunho etnomusicológico constituem uma base para novas investigações que se proponham a entender os processos percorridos pelo candomblé ao longo destes 30 anos, incluindo possíveis mudanças. Uma religião em mudança pode revelar muito de um país que também se transforma, o que atesta a um livro como este sua contribuição para uma interpretação do Brasil.', '["Candomblé","Afro-Brazilian religions","ritual music","public ceremonies","religious change","Bahia"]', '10.7476/9786556305028', '9786556303390', 'https://books.scielo.org/id/pgmcz', NULL, NULL, 'https://books.scielo.org/id/pgmcz/cover/cover_thumbnail.jpeg', 385, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pgwpg', 'pgwpg', 'Residências terapêuticas: pesquisa e prática nos processos de desinstitucionalização', NULL, '["Maria de Fátima Araújo Silveira","Hudson Pires de Oliveira Santos Junior"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A obra reúne reflexões sobre o Serviço Residencial Terapêutico, um dos mais importantes programas da Reforma Psiquiátrica para o processo de desinstitucionalização, que surgiu do reconhecimento pelo Estado brasileiro do direito à saúde de pessoas que ficavam trancafiadas sob pretexto de tratamento.', '["therapeutic residential services","deinstitutionalization","psychiatric reform","right to health","psychiatric patients","institutionalization","mental health services","Brazil"]', '10.7476/9788578791230', '9788578791230', 'https://books.scielo.org/id/pgwpg', 'https://books.scielo.org/id/pgwpg/pdf/silveira-9788578791230.pdf', NULL, 'https://books.scielo.org/id/pgwpg/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ph4mf', 'ph4mf', 'La reparación directa como recurso efectivo y adecuado para la reparación de violaciones de derechos humanos', NULL, '["Ana María Navarrete-Frías"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'La obra La reparación directa como recurso efectivo y adecuado para la reparación de violaciones de derechos humanos se desarrolló con base a una metodología descriptiva y de análisis documental, de tratados internacionales de derechos humanos del Sistema Universal de Protección de Derechos Humanos y del Sistema Interamericano de Derechos Humanos y de sentencias de la Corte Interamericana de Derechos Humanos, a partir de los cuales se analizan los acápites relacionados a las reparaciones y a los recursos de jurisdicción interna contenidos en los mismos, con el fin de identificar los elementos constitutivos y requisitos que debe tener un recurso judicial interno para ser considerado efectivo y adecuado para reparar violaciones de derechos humanos. Se hace un análisis documental, con tendencia cualitativa, de las sentencias proferidas por la Corte Interamericana de Derechos Humanos contra Colombia y de las sentencias del Consejo de Estado proferidas en procesos de reparación directa en los que se analice la responsabilidad extracontractual del Estado por violaciones de derechos humanos a partir de la nueva tendencia adoptada desde el año 2007; con el fin de analizar dichos pronunciamientos judiciales en lo referente (i) al concepto que adopta la CrIDH respecto de la reparación directa en cada caso; (ii) las reparaciones que son impuestas por la CrIDH en cada caso; y (iii) las reparaciones que son impuestas por el Consejo de Estado. Por último, se recurre a una metodología jurídico propositiva, la cual se utilizará para establecer recomendaciones con relación a la reparación directa, a partir del análisis realizado durante la investigación.', '["human rights violations","Inter-American Court of Human Rights","Inter-American human rights system","Council of State","reparations","Colombia"]', '10.7476/9789587386462', '9789587386455', 'https://books.scielo.org/id/ph4mf', NULL, NULL, 'https://books.scielo.org/id/ph4mf/cover/cover_thumbnail.jpeg', 262, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ph6g6', 'ph6g6', 'Tecnologias sociais e de comunicação como recursos educacionais em alimentação', NULL, '["Maria Cláudia da Veiga Soares Carvalho","Flávia Milagres Campos","Fabiana Bom Kraemer"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Reunindo pesquisadores(as) de várias áreas, a obra propõe discutir sobre Tecnologias Sociais na temática de Soberania e Segurança Alimentar e Nutricional (SSAN) e Direito Humano à Alimentação Adequada (DHAA) com articulação entre prática e teoria. A coletânea dá visibilidade a perspectivas éticas e pedagógicas que possam promover a inclusão social por meio de processo democrático e participativo. O escopo prevê abordagens problematizadoras e questionadoras de discursos e de produção de verdades que excluem a polifonia de significados intrínseca ao pensar e que impede um maior conhecimento dos impasses e desafios nela presente', '["social technology","communication technology","teaching materials","food sovereignty","food and nutrition security","right to food","social inclusion","participatory democracy","food ethics"]', '10.7476/9786556301983', '9786556301983', 'https://books.scielo.org/id/ph6g6', 'https://books.scielo.org/id/ph6g6/pdf/carvalho-9786556301983.pdf', NULL, 'https://books.scielo.org/id/ph6g6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-phkp3', 'phkp3', 'Improvisação como espetáculo: processo de criação e metodologias de treinamento do ator-improvisador', NULL, '["Mariana Lima Muniz"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A improvisação como espetáculo é um estilo teatral no qual atores criam cenas no instante, junto ao público e no calor da ação. Este livro apresenta uma proposta metodológica de ensino-aprendizagem da improvisação, contextualizada nas principais experiências artísticas e técnicas da improvisação como espetáculo a partir da segunda metade do século XX. É resultado de dez anos de pesquisas praticas e teóricas sobre o tema e pretende contribuir para o desenvolvimento técnico e artístico da improvisação tanto como espetáculo quanto nos processos de formação em teatro com adultos e crianças.', '["actor training","improvisation pedagogy","theatre education","scene creation"]', '10.7476/9786558580805', '9788542301014', 'https://books.scielo.org/id/phkp3', NULL, NULL, 'https://books.scielo.org/id/phkp3/cover/cover_thumbnail.jpeg', 248, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-phpfv', 'phpfv', 'Saúde, ambiente e sustentabilidade', NULL, '["Carlos Machado de Freitas","Marcelo Firpo Porto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Este livro, de caráter introdutório e informativo, apresenta aos leitores de distintas áreas do conhecimento, em especial aos que atuam mais diretamente nos campos ambiental e da saúde, uma visão abrangente dos problemas de saúde e ambiente que vêm marcando cada vez mais as sociedades modernas. Os autores deste livro vêm desenvolvendo um trabalho em conjunto desde a década de 90, investigando as interfaces entre questões de saúde e ambiente com o intuito de identificar e apontar futuros propícios para a promoção da vida.', '["health and environment","sustainability","environmental health","health promotion","environmental problems"]', '10.7476/9788575413692', '9788575413692', 'https://books.scielo.org/id/phpfv', 'https://books.scielo.org/id/phpfv/pdf/freitas-9788575413692.pdf', NULL, 'https://books.scielo.org/id/phpfv/cover/cover_thumbnail.jpeg', NULL, 21, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-phzf3', 'phzf3', 'Misticismo y filosofía', NULL, '["Ángela Uribe Botero","Carlos Miguel Gómez Rincón"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'La pretensión de los místicos de acceder a la realidad de forma directa ha sido una fuente de interrogantes filosóficos. ¿Cómo podemos comprender la pretensión epistémica de los místicos? ¿Qué tipo de conocimiento es este que claman alcanzar? ¿En qué sentido se afirma que la experiencia mística es inefable y cómo determina esto el lenguaje de los místicos? ¿Es posible reconciliar la pretensión epistémica de los místicos, el hecho de que afirmen haber estado en contacto con la realidad suprema, con la desconcertante variedad de descripciones de tal experiencia que se encuentran en diversas tradiciones y que en algunos casos se contradicen mutuamente? ¿Tienen algo en común la experiencia mística con la estética?', '["mysticism","mystical experience","ineffability","mystical language","ultimate reality","religious experience","aesthetics","philosophy of religion"]', '10.7476/9789587386561', '9789587386554', 'https://books.scielo.org/id/phzf3', NULL, NULL, 'https://books.scielo.org/id/phzf3/cover/cover_thumbnail.jpeg', 122, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pk55d', 'pk55d', 'Os donos do direito: a biografia coletiva dos ministros do STF (1988 – 2013)', NULL, '["Fernando de Castro Fontainha","Rafael Mafei Rabelo Queiroz","Angela Moreira Domingues da Silva","Marco Aurélio Vannucchi Leme de Mattos"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro tem o objetivo de analisar as características dos ministros do Supremo Tribunal Federal (STF ) entre 1988 e 2013, utilizando o método prosopográfico ou a biografia coletiva. Apesar de os capítulos serem assinados por autores diferentes, não se trata de uma coletânea de artigos de origens distintas, mas sim do resultado de um trabalho coletivo que foi realizado por uma equipe de pesquisadores.', '["Supreme Federal Court","prosopography","judicial careers","Brazilian judiciary"]', '10.7476/9788575115817', '9788575115756', 'https://books.scielo.org/id/pk55d', NULL, NULL, 'https://books.scielo.org/id/pk55d/cover/cover_thumbnail.jpeg', 320, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pkb78', 'pkb78', 'Nossas árvores: conservação, uso e manejo de árvores nativas no sul da Bahia', NULL, '["Regina Helena Rosa Sambuichi"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'agricultural-sciences', 'Ciencias Agrícolas y Veterinaria', 'Agricultural and Biological Sciences', 'São apresentadas informações sobre a implantação e o atual estado de conservação da Mata Atlântica do sul da Bahia, discorrendo-se sobre as principais interações ecológicas entre árvores e florestas tropicais, os princípios genéticos associados ao manejo e conservação das árvores, o uso das espécies nativas em programas de restauração florestal e sistemas agroflorestais, a coleta e produção de sementes, marcação e seleção de matrizes, além da produção de mudas em viveiros e o seu plantio no campo.', '["native tree species","Atlantic Forest conservation","southern Bahia","tree genetic resources","forest restoration","agroforestry systems","seed collection","seed production","tree planting","tropical forest ecology"]', '10.7476/9788574555157', '9788574555157', 'https://books.scielo.org/id/pkb78', 'https://books.scielo.org/id/pkb78/pdf/sambuichi-9788574555157.pdf', NULL, 'https://books.scielo.org/id/pkb78/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pm8y6', 'pm8y6', 'Dermatologia &amp; doenças infecciosas: fundamentos e condutas', NULL, '["Maria Clara Gutierrez Galhardo","Fabio Francesconi Valle","Antonio Carlos Francesconi Valle"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-12-08', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este livro sobre as manifestações dermatológicas humanas decorrentes de infecções, infestações e outros agravos biológicos abrange um campo muito amplo de abordagens clínicas, que podem se entrelaçar como diagnósticos diferenciais, na dependência da relação orgânica entre os agentes diretamente causais e as condições concomitantes da pessoa atingida: sua faixa etária, seu modo de vida, os espaços geográficos em que habita ou mais recentemente percorridos, além de atividades especificamente associáveis ao agravo. Tais afecções, bem documentadas por imagens que ilustram aspectos clínicos e sistematizadas em achados laboratoriais seja para confirmação etiológica, seja para diagnóstico das alterações orgânicas funcionais, têm apresentadas sua dimensão epidemiológica no contexto evolutivo e atual, as opções terapêuticas com seus esquemas em uso e perspectivas, e as medidas de prevenção ou controle indicadas.', '["skin infections","infestation","biological agents","differential diagnosis","etiological diagnosis","epidemiology","treatment options","prevention and control","clinical photographs"]', '10.7476/9786557081761', '9786557081396', 'https://books.scielo.org/id/pm8y6', NULL, NULL, 'https://books.scielo.org/id/pm8y6/cover/cover_thumbnail.jpeg', 368, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pmcfg', 'pmcfg', 'Tecnologia para a indústria a história do Instituto Nacional de Tecnologia', NULL, '["Maria Helena Magalhães Castro","Simón Schwartzman"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os investimentos feitos no Brasil na área de ciência e tecnologia nos últimos 15 anos alteraram de maneira profunda o quadro institucional e humano deste tipo de atividade no país. Grandes programas científicos, tecnológicos e de educação pós-graduada foram lançados - na área energética, agrícola, de saúde, engenharia e várias outras - pela criação de novas instituições ou pela transformação freqüentemente radical de outras, que eram adaptadas para desempenhar os novos objetivos que iam sendo definidos.', '["science and technology policy","research institutions","industrial technology","science and technology investment","Brazil"]', '10.7476/9788599662540', '9788599662540', 'https://books.scielo.org/id/pmcfg', 'https://books.scielo.org/id/pmcfg/pdf/castro-9788599662540.pdf', NULL, 'https://books.scielo.org/id/pmcfg/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pmpkw', 'pmpkw', 'Adolpho Lutz - Febre amarela, Malária e Protozoologia - v.2, Livro 1', NULL, '["Jaime Larry Benchimol","Magali Romero Sá"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Integra a coleção: BENCHIMOL, Jaime Larry; SÁ, Magali Romero (Org.) Adolpho Lutz: obra completa. Rio de Janeiro: Fiocruz, [2004-200-?]. 4 v.', '["yellow fever","malaria","protozoology","Adolpho Lutz","history of medicine","tropical diseases","protozoa"]', '10.7476/9788575414071', '9788575414071', 'https://books.scielo.org/id/pmpkw', 'https://books.scielo.org/id/pmpkw/pdf/benchimol-9788575414071.pdf', NULL, 'https://books.scielo.org/id/pmpkw/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pmyrm', 'pmyrm', 'Atividade política judicial: ensaio de fundamentação', NULL, '["Ana Lucia Pretto Pereira"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2023, '2023-07-07', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste ensaio, pressupõe-se que o atuar político é comum a todos aqueles que se envolvam em discussões sobre questões de interesse público, por diferentes mediações. Trata-se de um agir político, de uma atitude dirigida a fins, orientada por critérios, valores e princípios, que, em um ambiente complexo, como é o sistema jurídico, molda-se dentro de limites consensualmente construídos. A tese sobre a atividade política judicial que se desenvolveu no presente estudo dialoga com essa percepção e, sem pretensão de definitividade, justifica-se sobre a prática jurídico-constitucional brasileira.', '["judicial politics","political action","public interest","legal system","constitutional law","judicial behavior"]', '10.7476/9786558461685', '9786558461685', 'https://books.scielo.org/id/pmyrm', NULL, NULL, 'https://books.scielo.org/id/pmyrm/cover/cover_thumbnail.jpeg', 264, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pp8b9', 'pp8b9', 'Medidas de segurança no Direito Penal brasileiro: a desinternação progressiva sob uma perspectiva político-criminal', NULL, '["Michele Cia"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Nesta obra, Michele Cia concentra sua análise na desinterna­ção progressiva como medida alternativa a ser aplicada aos inim­putáveis que realizam ilícito penal. Para desenvolver essa ideia central, a autora realizou um trabalho minucioso de pesquisa multidisciplinar, por meio do estudo da criminologia, da política criminal, da dogmática jurídico-penal, além da pesquisa de campo realizada no Hospital de Custódia e Tratamento Psiquiátrico II de Franco da Rocha, instituição que mantém um programa de desinternação progressiva. A autora mantém uma postura crítica durante a análise dos pontos polêmicos do tema e oferece exemplos reais, extraídos especialmente da pesquisa de campo e da análise da jurispru­dência. Um livro que interessará os estudiosos do Direito Penal, do Direito Processual Penal, dos Direitos Humanos, da Criminologia, da Medicina, da Psicologia e da Sociologia, bem como profissionais da área do Direito.', '["unimputability","criminal liability","criminal policy","psychiatric hospitals","forensic psychiatry","Brazilian criminal law","human rights","criminology"]', '10.7476/9786557145302', '9786557145302', 'https://books.scielo.org/id/pp8b9', 'https://books.scielo.org/id/pp8b9/pdf/cia-9786557145302.pdf', NULL, 'https://books.scielo.org/id/pp8b9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pp8kv', 'pp8kv', 'Federalismo e políticas públicas no Brasil', NULL, '["Gilberto Hochman","Carlos Aurélio Pimenta de Faria"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Democracia, eleições, descentralização, participação, financiamento, repartição, cooperação, pactuação: palavras que, cada vez mais, ocupam o espaço público e revelam a importância de estudos sobre o Estado brasileiro. Conhecê-lo é fundamental para que se desenhem e implementem políticas mais eficazes, justas e apropriadas aos nossos problemas. Variadas contribuições para que se cumpram tais objetivos estão reunidas nesta coletânea, cujos capítulos exploram e analisam de diversas maneiras as relações entre o sistema federativo e as políticas públicas. Com a devida espessura teórica, os artigos abordam a estrutura e o funcionamento do Estado brasileiro, assim como suas conexões com o sistema e as instituições políticas, e as consequências para a consolidação da democracia e da cidadania. Em um contexto de revalorização do planejamento governamental no Brasil e de ampliação da esfera pública no país, o livro se dirige tanto aos estudiosos da área quanto aos profissionais diretamente envolvidos com as ações do Estado.', '["federalism","public policy","Brazilian states","federal systems","decentralization","democracy","citizenship","political participation","elections","public finance","intergovernmental relations","state planning"]', '10.7476/9788575415504', '9788575414293', 'https://books.scielo.org/id/pp8kv', NULL, NULL, 'https://books.scielo.org/id/pp8kv/cover/cover_thumbnail.jpeg', 388, 20, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ppvz3', 'ppvz3', 'Entre o corpo e a consciência: ensaios de interpretação da metapsicologia freudiana', NULL, '["Fátima Siqueira Caropreso","Richard Theisen Simanke"]', 'EdUFSCar', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Os ensaios reunidos neste livro abordam aspectos particulares e questões específicas da metapsicologia freudiana. Esses aspectos dizem respeito, sobretudo, aos principais problemas com os quais ela se defronta: a natureza do mental; sua relação com os processos cerebrais; a justificativa da hipótese do inconsciente; as questões envolvidas na elaboração de uma teoria da consciência e de suas relações com a mente inconsciente; o problema mais amplo das relações entre a mente e o corpo, onde entra em cena a dimensão pulsional do psiquismo.', '["Freudian metapsychology","unconscious","nature of mind","mind-brain relationship","theory of consciousness","mind-body problem","psychoanalysis"]', '10.7476/9788576003670', '9788576003670', 'https://books.scielo.org/id/ppvz3', 'https://books.scielo.org/id/ppvz3/pdf/caropreso-9788576003670.pdf', NULL, 'https://books.scielo.org/id/ppvz3/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pr3pz', 'pr3pz', 'Consumo alimentar e obesidade: teorias e evidências', NULL, '["Rosely Sichieri","Rosângela Alves Pereira"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2022, '2022-07-20', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'O livro discute aspectos que ajudam a entender por que comemos o que comemos e a produção biológica e social da obesidade, além de analisar políticas públicas de alimentação e nutrição. As autoras apresentam, em três capítulos, uma combinação de análises de condicionantes fisiológicos e biológicos sobre o que comemos, assim como o inegável papel da propaganda na forma como consumimos. A obra reúne ainda contribuições e debates sobre recomendações alimentares, conflitos de interesse entre a ciência e a indústria de alimentos, políticas públicas que possam propiciar condições mais favoráveis para escolhas alimentares, além do advocacy (defesa e reivindicação de direitos em torno de uma determinada causa), tema que engloba o ativismo em prol da alimentação saudável e ética.', '["dietary intake","obesity","food advertising","food recommendation","conflicts of interest","food industry","public health policy","nutrition policy","food activism","healthy eating","food ethics"]', '10.7476/9786557081648', '9786557081273', 'https://books.scielo.org/id/pr3pz', NULL, NULL, 'https://books.scielo.org/id/pr3pz/cover/cover_thumbnail.jpeg', 152, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pr4v9', 'pr4v9', 'O percurso dos gêneros do discurso publicitário: uma análise das propagandas da Coca-Cola', NULL, '["Ana Lúcia Furquim Campos-Toscano"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'discurso.2. Coca-Cola Company. 3. Publicidade.4. Comunicação de massa e linguagem.I. Título.II.Título: Uma análise das propagandas da Coca-Cola.', '["advertising discourse","Coca-Cola","advertising language","mass communication","discursive genres"]', '10.7476/9788579830112', '9788579830112', 'https://books.scielo.org/id/pr4v9', 'https://books.scielo.org/id/pr4v9/pdf/campos-9788579830112.pdf', NULL, 'https://books.scielo.org/id/pr4v9/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pr84k', 'pr84k', 'Humanização do parto: política pública, comportamento organizacional e ethos profissional', NULL, '["Mônica Bara Maia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', '"Parir e nascer, definitivamente, não são processos ‘naturais’ nem meramente fisiológicos. São eventos sociais e culturais complexos, que envolvem interações entre indivíduos, grupos sociais e organizações (hospitais e maternidades), com poderes e legitimidades diferenciados". A partir desta constatação, a autora faz uma investigação sistemática sobre como disputas em torno do modelo de assistência ao parto tornam-se obstáculos para a implementação de uma política que considere mais o papel da mulher e minimize os impactos negativos de uma excessiva hospitalização do processo. Com base no caso da rede hospitalar de Belo Horizonte – pública, filantrópica, privada contratada e privada não contratada pelo SUS –, verifica em que medida as políticas nacionais de humanização do parto se operacionalizaram, como se portaram profissionais obstetras (médicos e enfermeiras) e quais foram as dificuldades institucionais enfrentadas para colocar em prática essas políticas. Fornece, assim, valiosos indicadores para todos aqueles empenhados na efetiva humanização do parto no Brasil.', '["humanized childbirth","childbirth care","public policy implementation","organizational behavior","professional ethos","obstetricians","hospital networks","Belo Horizonte","obstetric care","policy implementation barriers"]', '10.7476/9788575413289', '9788575413289', 'https://books.scielo.org/id/pr84k', 'https://books.scielo.org/id/pr84k/pdf/maia-9788575413289.pdf', NULL, 'https://books.scielo.org/id/pr84k/cover/cover_thumbnail.jpeg', NULL, 19, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-prbfj', 'prbfj', 'Docência e formação humana', NULL, '["Odair Neitzel"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro tem como foco central a abordagem da docência sob a perspectiva da formação humana. Os ensaios, fundamentados na filosofia da educação, oferecem reflexões provenientes de diversas pesquisas acadêmicas, enriquecendo a formação docente com elementos que valorizam o aspecto humanizador. Esses textos baseiam-se em pensadores clássicos da educação, diversos comentaristas e exploram a interseção entre arte, literatura, música, política e cultura, buscando iluminar a complexa missão do ensino. A coletânea destaca que a tarefa de proporcionar uma formação humana não pode ser realizada ignorando ou evitando o enfrentamento da precarização e mercantilização da educação sob a lógica da racionalidade neoliberal. Em outras palavras, os ensaios propostos concentram-se na seguinte indagação: quais elementos e conhecimentos compõem ou poderiam contribuir para uma prática docente voltada à formação humana? Todos os trabalhos foram discutidos e aprimorados pelo grupo, enriquecidos pelo debate coletivo, e agora são apresentados aos leitores.', '["teaching","human formation","teacher professional development","humanization of education","philosophy of education","precarization of education","commodification of education","neoliberal rationality","music in education"]', '10.7476/9786550191092', '9786550191108', 'https://books.scielo.org/id/prbfj', 'https://books.scielo.org/id/prbfj/pdf/neitzel-9786550191092.pdf', NULL, 'https://books.scielo.org/id/prbfj/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-prc5k', 'prc5k', 'Actividades Integradoras del Aprendizaje por Sistemas, AIAS. Manual para la facilitación en el aula de pequeños grupos', NULL, '["Gustavo A. Quintero"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Las Actividades Integradoras del Aprendizaje por Sistemas –AIAS–, son una estrategia educativa fundamentada en el Aprendizaje Basado en Problemas –ABP–. Esta técnica se centra en el aprendiz, promueve el trabajo en pequeños grupos, utiliza casos clínicos como “detonadores” (triggers), con el propósito de promover en los estudiantes habilidades para la resolución de problemas, mediante la aplicación de conocimientos. Tiene su principal diferencia con la técnica de ABP en que en las AIAS los resultados del aprendizaje son proporcionados desde el inicio del proceso; no se convienen con el estudiante. Las AIAS son un espacio generador de sentido, de reflexión y del manejo de la incertidumbre. El rol del facilitador favorece el ‘andamiaje’, un concepto muy utilizado en educación, con base en la visión constructivista de Vygotsky y el concepto de Zona de Desarrollo Próximo –ZDP–, que se conoce como la distancia que existe entre lo que el estudiante puede resolver por sí solo, y lo que podría realizar con ayuda o guía de un adulto o persona más capacitada, para encontrar su nivel de desarrollo potencial.', '["AIA","problem-based learning","small group work","clinical case","facilitation techniques","scaffolding","zone of proximal development","Vygotsky","constructivism","problem-solving skills","uncertainty management"]', '10.7476/9789587385267', '9789587385250', 'https://books.scielo.org/id/prc5k', NULL, NULL, 'https://books.scielo.org/id/prc5k/cover/cover_thumbnail.jpeg', 108, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-prgd6', 'prgd6', 'Química e literatura: princípios teóricos e metodológicos e os contributos para o ensino e a formação de professores de química', 'princípios teóricos e metodológicos e os contributos para o ensino e a formação de professores de química', '["Marcelo Pimentel da Silveira","Fábio Peres Gonçalves"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro conta com a participação de quatorze autores(as) brasileiros(as) e portugueses(as) que investigam as articulações entre o ensino de Química e Literatura. Organiza-se em três seções. A primeira – Química e Literatura: princípios teóricos e metodológicos – contempla trabalhos que abordam conhecimentos teóricos sobre as relações entre ensino de Química e Literatura e/ou percursos metodológicos que balizem a análise de textos literários à luz da Ciência. A segunda – Literatura e Química: contributos para o ensino de Química – constitui-se de estudos a respeito da potencialidade de obras literárias para articulação com o ensino de Química e da análise de experiências educativas nessa perspectiva, na educação formal e não formal. A terceira – Literatura e Química: contributos à formação de professores de Química – contempla trabalhos que tratam da articulação entre ensino de Química e Literatura no âmbito da formação de professores, como análise de experiências educativas com obras literárias nesse âmbito. Trata-se do quinto volume da Coleção Ensino de Ciências, coordenada pelos pesquisadores Roque Ismael da Costa Güllich, Rosangela Inês Matos Uhmann e Rosemar Ayres dos Santos, docentes da UFFS – Campus Cerro Largo.', '["chemistry and literature","literature in science education","chemistry education","teacher professional development","literary analysis","non-formal education","educational experience"]', '10.7476/9786550190828', '9786550190811', 'https://books.scielo.org/id/prgd6', 'https://books.scielo.org/id/prgd6/pdf/silveira-9786550190828.pdf', NULL, 'https://books.scielo.org/id/prgd6/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-prgp2', 'prgp2', 'O nascimento da metapsicologia: representação e consciência na obra inicial de Freud', NULL, '["Fátima Siqueira Caropreso"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O resultado do trabalho aqui apresentado não poderia ser melhor: Fátima Caropreso faz nascer, aos nossos olhos, a Metapsicologia, ciência fundamental no entender do próprio Freud. Nessa aliança, até agora pouco estudada, entre a Concepção das afasias e o "Projeto", ela vê o nascimento da metapsicologia quando insere, num "golpe de mestre", as associações linguísticas da Concepção no âmago da teoria do "Projeto", revelando assim o imbricamento entre as duas obras-chave do fundador da psicanálise. Junção por meio da qual Freud tornou possível desenvolver o projeto de uma metapsicologia. Alia-se a isso o fato de que nossa autora se distingue na leitura de numerosos textos relativos à "História da Psicanálise" (frequentemente uma história de bastidores e que alinha textos sem relacioná-los), porque ela não só trata dos textos centrais, mas também estabelece uma verdadeira análise conceitual - fazendo ver como brotaram os conceitos centrais da Teoria Psicanalítica. Enfim, um livro que vem preencher uma lacuna na história das ideias.', '["metapsychology","Sigmund Freud","aphasia","Project for a Scientific Psychology","linguistic associations","representation","consciousness","history of psychoanalysis","conceptual analysis"]', '10.7476/9788576002956', '9788576002956', 'https://books.scielo.org/id/prgp2', 'https://books.scielo.org/id/prgp2/pdf/caropreso-9788576002956.pdf', NULL, 'https://books.scielo.org/id/prgp2/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-prmpv', 'prmpv', 'O homem e a serpente: outras histórias para a loucura e a psiquiatria', NULL, '["Paulo Amarante"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'humanidade ganhou uma casa de orates) .................', '["madness","psychiatry","history of psychiatry","madness in literature","madness in art","philosophy of madness"]', '10.7476/9788575413272', '9788575413272', 'https://books.scielo.org/id/prmpv', 'https://books.scielo.org/id/prmpv/pdf/amarante-9788575413272.pdf', NULL, 'https://books.scielo.org/id/prmpv/cover/cover_thumbnail.jpeg', NULL, 100, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-prz7m', 'prz7m', 'Psicose e drogas: estado mental de risco e primeiro episódio psicótico em usuários de maconha', NULL, '["Esdras Cabus Moreira"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A obra aborda quatro temas centrais da psiquiatria atual. O primeiro deles é a possibilidade de utilizar, para os transtornos mentais, o modelo de estadiamento clínico, comumente usado em outras áreas da medicina. O segundo diz respeito à concepção de estados mentais de risco que antecedem o primeiro episódio de psicose e a possibilidade de prevenção e intervenção precoce na esquizofrenia. O terceiro aborda a relação entre o uso de maconha e quadros psicóticos. O quarto e último analisa a especificidade da atenção clínica ao indivíduo com psicose e uso de maconha.', '["psychosis","cannabis use","first-episode psychosis","schizophrenia prevention","early intervention","clinical staging model","mental illness"]', '10.7476/9786556305059', '9786556304311', 'https://books.scielo.org/id/prz7m', NULL, NULL, 'https://books.scielo.org/id/prz7m/cover/cover_thumbnail.jpeg', 193, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ps2mx', 'ps2mx', 'Michel de Certeau e as pesquisas nos/dos/com os cotidianos em educação', NULL, '["Carlos Eduardo Ferraço","Maria da Conceição Silva Soares","Nilda Alves"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'CDU 37Nossas ciências surgiram com o gesto histórico "moderno" que despolitizou a pesquisa ao instaurar campos "desinteressados" e "neutros", apoiados por instituições científicas.Esse gesto continua organizando, frequentemente, a ideologia exibida por alguns círculos científicos.Mas o desenvolvimento do que se tornou possível por esse gesto acabou por inverter seu alcance.[...] Atualmente, convém, portanto, "politizar de novo" as ciências.Michel de Certeau (apud Ferraço, 2011, p. 63) Sumário INTRODUÇÃO 9Viajantes em busca da alteridade e da compreensão das dinâmicas de criação da vida e do conhecimento CAPÍTULO 1 19 História-ficção-narrativa de vida em Certeau CAPÍTULO 2 33 A crítica à epistemologia da ciência e a aposta na atitude ético-estética em pesquisa CAPÍTULO 3 55 A potência das práticas e as artes de fazer com CAPÍTULO 4 71 Cotidiano, cultura, alteridade e a criação permanente de diferença CAPÍTULO 5 89 A pesquisa nos/dos/com os cotidianos em educação REFERÊNCIAS 105 SOBRE OS AUTORES 109 ção intelectual segue caminhos estranhos à lógica das instituições, quer estas se achem ligadas à Universidade, à Igreja ou ao Estado".Estava sempre em movimento e nunca se identificava a um lugar.Ele era ainda adolescente quando a Segunda Grande Guerra eclodiu na Europa e atuou, por um breve período, em um grupo de resistência ao nazismo.Estava em Paris em maio de 1968, quando se propôs a pensar as manifestações e as mudanças sociais que estavam em curso em meio ao clamor dos acontecimentos.Em suas andanças pelo mundo, conheceu a desigualdade social, o autoritarismo, a exploração econômica, a miscigenação, o preconceito, a exclusão e a pobreza; mas também foi capaz de enxergar, acima de tudo, o poder de resistência, de negociação, de hibridização e de invenção engendrados com as práticas culturais cotidianas.Esteve no Brasil pela primeira vez em 1966, período da ditadura militar, sensibilizado com a situação política do país.O conhecimento sobre o Brasil, contudo, de acordo com Vidal (2005), antecedia às viagens e vinha de leituras, entre elas, trabalhos de Paulo Freire.Apoiado no educador brasileiro, Michel de Certeau, em um artigo que escreveu para a revista Pédagogie, concebeu a relação pedagógica como um diálogo entre gerações e a aula como um lugar onde se deve exercitar a liberdade.Em A cultura no plural, tocado por maio de 1968, Certeau refletiu sobre as escolas, as universidades e as mudanças culturais, mas foi a obra A invenção do cotidiano que obteve melhor recepção e que foi mais apropriada no Brasil, produzindo ressonâncias nas Ciências Humanas e Sociais.Nessa perspectiva, defendemos que a contribuição de Certeau ao campo da Educação é inestimável e, além de sua atitude política e em pesquisa, se substancializa na crítica à epistemologia das Ciências Socais e Humanas e, principalmente, Introdução  17 em sua empreitada teórica para construir uma epistemologia das práticas cotidianas, as quais estão, segundo ele, no cerne da constituição e transformação do social, do cultural, do político, do científico e do educativo, mobilizando procedimentos metodológicos e criando conceitos para apreendê-las e analisá-las.', '["Michel de Certeau","everyday life","everyday research","educational research","politicization of science","epistemology of science","otherness","difference","life history (social science method)","resistance","social change","Michel Foucault"]', '10.7476/9788575115176', '9788575115176', 'https://books.scielo.org/id/ps2mx', 'https://books.scielo.org/id/ps2mx/pdf/ferraco-9788575115176.pdf', NULL, 'https://books.scielo.org/id/ps2mx/cover/cover_thumbnail.jpeg', NULL, 18, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ps39s', 'ps39s', 'Uma ciência moderna e imperial: a fisiologia brasileira no final do século XIX (1880-1889)', NULL, '["Ana Carolina Vimieiro Gomes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é uma história sobre a inserção da fisiologia experimental na agenda científica do Brasil de fins do século XIX, a partir de uma instituição científica considerada como pioneira nessa disciplina no país, o "Laboratório de Physiologia Experimental do Museu Nacional". Trata-se de uma análise sobre a iniciação de um campo de saber, a partir da idealização, instalação, funcionamento, consolidação e declínio desse Laboratório em específico. É uma história que explora os sentidos e significados das práticas lá ocorridas e o processo de produção e validação dos conhecimentos científicos, realizado pelos diversos atores envolvidos no referido Laboratório. É um livro que nos ajuda a compreender as tentativas para se consolidar um ideal de ciência para o Brasil no final do Império.', '["experimental physiology","Museu Nacional","Brazilian Empire","history of science","research institutions","scientific knowledge production","imperial science","19th century"]', '10.7476/9788575414446', '9788575414286', 'https://books.scielo.org/id/ps39s', 'https://books.scielo.org/id/ps39s/pdf/gomes-9788575414446.pdf', NULL, 'https://books.scielo.org/id/ps39s/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ps555', 'ps555', 'Burocracia e implementação de políticas de saúde: os agentes comunitários na Estratégia Saúde da Família', NULL, '["Gabriela Lotta"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', '"Traz uma análise inovadora do campo das políticas públicas e da saúde coletiva. Investiga um viés pouco explorado dessa questão: a implementação das políticas e programas de saúde no Brasil com um olhar para a atuação dos burocratas, mais especificamente dos ‘burocratas de nível de rua’, como são chamados no livro os agentes comunitários de saúde. Estes profissionais da Estratégia Saúde da Família, responsáveis por implementar grande parte do programa nos domicílios dos usuários, têm a particularidade de ser recrutados na comunidade onde devem atuar e têm, portanto, uma dupla vinculação: ao Estado e à comunidade. Eles estão na ponta do serviço público, em contato direto e constante com os cidadãos. Ao analisar a dinâmica de interações entre os agentes e os usuários, a autora mostra como valores, crenças e ideias contribuem para mudar as políticas públicas tais como foram concebidas originalmente. A tese que deu origem ao livro recebeu menção honrosa na edição 2011 do concurso de melhores teses da Associação Nacional de Pós-Graduação e Pesquisa em Ciências Sociais (Anpocs) e é vencedora do Prêmio Sérgio Arouca – Gestão Participativa no SUS 2009, do Ministério da Saúde."', '["health policy implementation","community health workers","Family Health Strategy","bureaucracy","public policy","primary care","Unified Health System (SUS)","participatory management"]', '10.7476/9788575415481', '9788575414682', 'https://books.scielo.org/id/ps555', NULL, NULL, 'https://books.scielo.org/id/ps555/cover/cover_thumbnail.jpeg', 322, 39, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pt88n', 'pt88n', 'Os diários de Langsdorff Vol. 3', NULL, '["Danuzio Gil Bernardino da Silva","Комиссаров Борис Николаевич","Hans Becher","Paulo Masuti Levy","Marcos P. Braga"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O zoólogo, botânico e médico alemão Langsdorff foi o mentor dessa grandiosa aventura naturalista: entre 1821 e 1829, conduziu um grupo de pesquisadores e desenhistas por uma viagem de 17 mil quilômetros, estudando a fauna, a flora e o modo de vida do interior do Brasil. Os registros, em textos e ilustrações, dessas cenas até então inéditas da natureza brasileira estão contidos nesses três primeiros volumes. Um quarto e último volume - contendo mapas e reproduções fac-similares de documentos originais - está em fase de preparo.', '["natural history expedition","Brazilian flora","scientific illustration","19th-century natural history"]', '10.7476/9788575412466', '9788575412466', 'https://books.scielo.org/id/pt88n', 'https://books.scielo.org/id/pt88n/pdf/silva-9788575412466.pdf', NULL, 'https://books.scielo.org/id/pt88n/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ptg88', 'ptg88', 'A vontade de expor: arte, gênero e sexualidade', NULL, '["Leandro Colling"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Dirigido a qualquer pessoa interessada nas relações entre arte, gênero e sexualidade, o livro explica como grandes museus espanhóis foram ocupados por uma série de obras e exposições que tratam das dissidências sexuais e de gênero. O autor analisa a vontade de expor, classificar e pensar essas dissidências nas artes e oferece uma rica narrativa sobre o processo de construção da pesquisa, que leva o pesquisador a ser afetado por uma série de obras, situações e encontros dentro e fora dos museus. É um exercício etnocartográfico processual que resulta em críticas e pessoas artistas, curadoras, pesquisadoras e uma instigante proposta analítica. A obra foi produzida durante o período (2019-2020) em que o autor foi professor visitante na Universidade de Sevilha.', '["gender and art","sexuality in art","sexual dissidence","gender dissidence","Spanish museums","museum exhibitions","classification of artworks","ethnographic cartography","art criticism","curators","artists"]', '10.7476/9786556301815', '9786556301815', 'https://books.scielo.org/id/ptg88', 'https://books.scielo.org/id/ptg88/pdf/colling-9786556301815.pdf', NULL, 'https://books.scielo.org/id/ptg88/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ptky6', 'ptky6', 'Desafios para a saúde coletiva no século XXI', NULL, '["Jairnilson Silva Paim"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2006, '2006-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea reúne textos que discutem políticas públicas e movimentos ideológicos que têm influenciado o campo social da saúde. Nesta perspectiva, a saúde coletiva representa uma aposta em novos pressupostos, métodos e práticas sociais que podem compor movimentos capazes de constituir sujeitos públicos comprometidos com novos modos de vida.', '["public health","public health policy","social movements","health ideology","lifestyle","21st century"]', '10.7476/9788523211776', '9788523211776', 'https://books.scielo.org/id/ptky6', 'https://books.scielo.org/id/ptky6/pdf/paim-9788523211776.pdf', NULL, 'https://books.scielo.org/id/ptky6/cover/cover_thumbnail.jpeg', NULL, 43, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-ptm2d', 'ptm2d', 'A cultura dos memes: aspectos sociológicos e dimensões políticas de um fenômeno do mundo digital', NULL, '["Viktor Henrique Carneiro de Souza Chagas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A coletânea reúne uma série de textos inéditos e originais, associados a republicações de artigos que ajudaram a fundar o campo dos estudos sobre memes. A obra reflete a diversidade de abordagens e interesses que atravessam o desenvolvimento recente do campo. É, portanto, um livro voltado àqueles que desejam explorar o universo da pesquisa sobre memes de internet, entender o que há de importante nesse debate e perceber que papéis o meme desempenha na comunicação cotidiana.', '["internet memes","digital culture","everyday communication","online communication"]', '10.7476/9786556301785', '9788523219796', 'https://books.scielo.org/id/ptm2d', NULL, NULL, 'https://books.scielo.org/id/ptm2d/cover/cover_thumbnail.jpeg', 544, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pv62d', 'pv62d', 'Eu venho de longe: mestre Irineu e seus companheiros', NULL, '["Paulo Moreira","Edward MacRae"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro revela a importância do Daime na formação da identidade acreana. Destaca detalhes do caminho percorrido por Mestre Irineu e seus companheiros; aborda questões como sua relação com espíritas, esotéricos, militares e políticos e as estratégias de defesa utilizadas por este líder para proteger sua comunidade das perseguições. Todo o texto é ilustrado com fotos e mapas, além de reunir depoimentos dos primeiros participantes deste movimento religioso, muitos já falecidos ou com idades avançadas.', '["Afro-Brazilian religions","Acre","religious identity","spiritualism","esotericism","religious persecution","oral testimony"]', '10.7476/9788523211905', '9788523211905', 'https://books.scielo.org/id/pv62d', 'https://books.scielo.org/id/pv62d/pdf/moreira-9788523211905.pdf', NULL, 'https://books.scielo.org/id/pv62d/cover/cover_thumbnail.jpeg', NULL, 70, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pv7sd', 'pv7sd', 'Extensão e desenvolvimento regional: relatos de experiências', 'relatos de experiências', '["Deponti, Cidonea Machado","Brose, Markus Erwin"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea resulta de uma parceria entre os Programas de Pós-Graduação em Desenvolvimento Regional da Universidade Estadual da Paraíba e da Universidade de Santa Cruz do Sul. Os textos para esse projeto de gestão de conhecimento tomaram forma durante a pandemia da Covid-19, entre 2021 e 2022, a partir do convite para que os pesquisadores atuantes em extensão universitária participassem da reflexão quanto às contribuições de universidades, essencialmente localizadas fora de regiões metropolitanas, ao desenvolvimento regional. Os espaços de pertencimento estão em constante construção e desconstrução e a localização tem relevância. A extensão implica em proximidade, em relações sociais e de confiança, que frente à vastidão do continente depende de uma rede de instituições de ensino superior atuando de forma descentralizada nos territórios. A diversidade de enfoques metodológicos e de conhecimentos gerados, registrados nesses capítulos, sublinha a relevância do interesse continuado pela temática. Apesar da diversidade entre os capítulos, desponta de forma comum um conceito em constante disputa no campo da pós-graduação em Planejamento Urbano e Regional, qual seja a interpretação do conceito de desenvolvimento. O espectro das interpretações, inerentes ou explícitas, nos textos vai desde o clássico enquadramento da geração de oportunidades e de crescimento econômico pela localização estratégica da universidade, até a preocupação com a crise demográfica pela perda de jovens no meio rural. Há necessidade de construção de laços de confiança e de comunicação em duas vias com os atores sociais, a inserção da pesquisa e do conhecimento científico junto aos gestores públicos e privados. A difusão científica representa elemento central do esforço continuado pelos pesquisadores aqui representados.', '["university extension","regional development","knowledge management","concept of development","rural depopulation","knowledge diffusion","university-community relations","regional planning","urban planning","COVID-19 pandemic"]', '10.7476/9786526803066', '9788578798628', 'https://books.scielo.org/id/pv7sd', 'https://books.scielo.org/id/pv7sd/pdf/deponti-9786526803066.pdf', NULL, 'https://books.scielo.org/id/pv7sd/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pvm8g', 'pvm8g', 'Mestres e capoeiras famosos da Bahia', NULL, '["Pedro Rodolpho Jungers Abib"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Sem a lembrança dos antepassados, a capoeira não tem encanto. Nessa obra estão os nomes daqueles que merecem ficar grafitados na linha da nossa memória, pela importância que tiveram na história da capoeira baiana, a capoeira que conseguiu se espalhar pelo mundo. Este livro propõe-se a contar histórias e casos da capoeira da Bahia. Histórias e casos de gente que carrega consigo a ancestralidade, que faz andar de cabeça erguida e peito estufado todo aquele que se entende herdeiro de uma cultura que nunca se deixou subjugar.', '["capoeira","capoeira masters","cultural heritage","ancestral memory","Afro-Brazilian culture","popular culture"]', '10.7476/9788523208745', '9788523205621', 'https://books.scielo.org/id/pvm8g', NULL, NULL, 'https://books.scielo.org/id/pvm8g/cover/cover_thumbnail.jpeg', 188, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pw7rx', 'pw7rx', 'Do socialismo à democracia', 'tática e estratégia na Reforma Sanitária Brasileira', '["André Vianna Dantas"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Estava faltando uma obra que analisasse com profundidade teórico-política, e fundamentada na crítica da economia política, o projeto da Reforma Sanitária desde a sua constituição, em meados dos anos 1970, até a atualidade. Como bem caracteriza o autor, a Reforma Sanitária é processo, é movimento, e não pode contentar-se com o Sistema Único de Saúde (SUS), mesmo que pleno. A defesa é de uma reforma que pretende um projeto civilizatório pautado na emancipação dos trabalhadores: o socialismo. O livro de André Dantas nos dá um alento: mostra que há vida crítica na esquerda brasileira e que há esperança, pois temos muita luta pela frente. A onda conservadora passará." (Maria Inês Souza Bravo, doutora em serviço social, professora associada da Faculdade de Serviço Social da Universidade do Estado do Rio de Janeiro)', '["Brazilian health reform","Unified Health System (SUS)","socialism","democracy","critique of political economy","Brazilian left","worker emancipation","health policy"]', '10.7476/9786557082966', '9788575415030', 'https://books.scielo.org/id/pw7rx', 'https://books.scielo.org/id/pw7rx/pdf/dantas-9786557082966.pdf', NULL, 'https://books.scielo.org/id/pw7rx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pwfz9', 'pwfz9', 'La biblioteca de Fray Cristóbal de Torres a partir de los libros que conserva la Biblioteca Antigua del Colegio Mayor de Nuestra Señora del Rosario', NULL, '["Jaime Restrepo Zapata"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Fray Cristóbal de Torres y Motones (Burgos, 1573 – Santafé de Bogotá, 1654). Predicador de sus majestades Felipe III y Felipe IV, al ser designado por este último en 1634 como arzobispo del Nuevo Reino de Granada, no llegó solo a Santafé de Bogotá, 2600 metros más cerca de las estrellas pero muchísimos kilómetros lejos del mar; a sus sesenta años de edad, trajo consigo a este apartado rincón de la América española su recio carácter, que le había ganado la amistad del gran Francisco de Quevedo y Villegas, a quien el fraile dominico había dado el pase para la impresión de la obra Política de Dios, gobierno de Cristo y tiranía de Satanás, hecho que Quevedo agradeció dedicándole a fray Cristóbal su tratado La cuna y la sepultura, para el conocimiento propio y desengaños de las cosas ajenas. Lo acompañaron, además, su empatía por los indígenas, su pasión por la educación, algunos miembros de su familia y, como corresponde a un protagonista del Siglo de Oro, la rica biblioteca que, atravesando el mar, remontando el río Grande de la Magdalena y las altas montañas andinas, se encuentra hoy en la Librería de su Colegio Mayor de Nuestra Señora del Rosario, el cual fue fundado por Real Cédula de Felipe IV expedida en Madrid el 31 de diciembre de 1651.', '["private libraries","book provenance","Colegio Mayor de Nuestra Señora del Rosario","New Kingdom of Granada","Francisco de Quevedo","17th-century book trade","colonial education"]', '10.7476/9789587386523', '9789587386516', 'https://books.scielo.org/id/pwfz9', NULL, NULL, 'https://books.scielo.org/id/pwfz9/cover/cover_thumbnail.jpeg', 228, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-px29p', 'px29p', 'Linguagem, educação e virtualidade', NULL, '["Ucy Soto","Mônica Ferreira Mayrink","Isadora Valencise Gregolin"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '1. Ensino auxiliado por computador.2. Educação -Recursos de redes de computadores.3. Internet na educação.4. Ensino à distância.5. Comunicação e tecnologia.6. Linguagem e línguas -Ensino auxiliado por computador.7.', '["language and education","virtuality","computer-assisted instruction","computer networks in education","internet in education","distance education","communication and technology","language teaching"]', '10.7476/9788579830174', '9788579830174', 'https://books.scielo.org/id/px29p', 'https://books.scielo.org/id/px29p/pdf/soto-9788579830174.pdf', NULL, 'https://books.scielo.org/id/px29p/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-py5s2', 'py5s2', 'A música da fala dos trovadores: desvendando a pro-sódia medieval', NULL, '["Gládis Massini-Cagliari"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra tem como o objetivo central a investigação de fenômenos prosódicos do Português Arcaico, a partir de uma comparação das características linguísticas das cantigas medievais profanas com as das cantigas religiosas. Para a análise fonológica, será usado o aparato fornecido pela Teoria da Otimalidade.Durante a análise, são colocados lado a lado fenômenos fonológicos segmentais e fenômenos prosódicos (tais como acento, ritmo, estruturação silábica e processos fonológicos que façam referência direta a esses fenômenos), em um período passado, do qual não se tem registros orais.', '["prosody","Old Portuguese","troubadour songs","accent","rhythm","syllable structure","Optimality Theory","phonological processes","historical phonology"]', '10.7476/9788568334584', '9788568334584', 'https://books.scielo.org/id/py5s2', 'https://books.scielo.org/id/py5s2/pdf/massini-9788568334584.pdf', NULL, 'https://books.scielo.org/id/py5s2/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pybxp', 'pybxp', 'A sociedade de educação de São Paulo: embates no campo educacional (1922-1931)', NULL, '["Ana Clara Bortoleto Nery"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Na década de 1920, algumas instituições organizaram-se com o intuito de legitimar a atuação de seus associados no campo educacional que estava se estruturando, como ocorreu com a Sociedade de Educação de São Paulo, que foi fundada com a finalidade de congregar membros do magistério em seus vários níveis, dos setores público e privado, com ideias e interesses comuns, tendo uma intensa atuação no cenário educacional do período. A obra pretende recuperar aspectos da criação e do funcionamento da Sociedade de Educação, seu papel e posição na estruturação do campo educacional. A partir deste estudo, veremos quais são as principais questões discutidas no âmbito da entidade e ainda quem eram seus membros.', '["teachers'' associations","educational field","1920s education","public and private education","education policy","São Paulo"]', '10.7476/9788539304509', '9788571399464', 'https://books.scielo.org/id/pybxp', NULL, NULL, 'https://books.scielo.org/id/pybxp/cover/cover_thumbnail.jpeg', 251, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pyy6f', 'pyy6f', 'Machado e a lâmina discursiva da ironia', NULL, '["Igor Bimkowski Rossoni"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Muitos estudos tomam como objeto de análise as obras de Machado de Assis. Trata-se, talvez, de autor nacional com maior fortuna crítica produzida ao longo dos anos. Entretanto, a despeito de certo pensamento de que muito já se fez, a cada período, novos ou diversos aspectos vem à tona, conferindo a certeza de que em relação aos grandes textos, o caráter de plurissignificância do tecido literário oferece campo para ilimitada reflexão. Ao que parece, estudar a produção de Machado de Assis ainda é iniciativa sempre atual por incentivar atividades de busca ao singular, ao enigmático, ao desconcertante. Por isso mesmo, culmina por eleger estado que instiga e estimula o pensamento criativo de investigadores e leitores.', '["Machado de Assis","irony","Brazilian literature","literary criticism"]', '10.7476/9788585813727', '9788585813536', 'https://books.scielo.org/id/pyy6f', 'https://books.scielo.org/id/pyy6f/pdf/rossoni-9788585813727.pdf', 'https://books.scielo.org/id/pyy6f/epub/rossoni-9788585813727.epub', 'https://books.scielo.org/id/pyy6f/cover/cover_thumbnail.jpeg', 326, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pz254', 'pz254', 'Experiência de doença e narrativa', NULL, '["Miriam C. M. Rabelo","Paulo César Alves","Iara Maria de Almeida Souza"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'ApresentaçãoA presente coletβnea reúne trabalhos que buscam refletir sobre questυes relativas ŕ compreensão da doença (particularmente da doença mental) como experiência, vivida e significada em contextos de ação e interação.Apesar de independentes, os capítulos encontram-se ligados por uma linha teóricometodológica comum.Fundamentam-se, todos, em (re)leituras das teorias so ciais de base fenomenológica (principalmente a existencial e etnometodológica), da hermenêutica e do pragmatismo.Contudo, é importante observar que não se teve preocupação de seguir ŕ risca os processos discursivos e os quadros de referência dessas ''escolas''.Ι sempre problemático delimitar, com simples ró tulos, a natureza e pressupostos de um certo conjunto de idéias.Entretanto, a diretriz fenomenológica, se assim podemos dizer, é, sem dúvida, preponderante na análise das questυes levantadas.Com exceção parcial de um deles, os artigos desta coletβnea são inéditos.Apresentaram-se versυes ou partes desses artigos, contudo, em congressos nacio nais ou internacionais de ciências sociais ou de saúde coletiva.Os debates e dis cussυes realizados em tais congressos ajudaram substancialmente os autores a questionar e desenvolver alguns aspectos significativos sobre o tratamento dos dados e a elaboração conceitual das temáticas analisadas.Cabe mencionar a parti cipação nos Grupos de Trabalho (GTs) Corpo, Pessoa e Doença da Associação Nacional de Pós-Graduação e Pesquisa em Ciências Sociais (Anpocs) e Associa ção Brasileira de Antropologia (ABA): a interlocução com os colegas destes GTs, particularmente com Luís Fernando Duarte e Ondina Fachel Leal, foi bastante enriquecedora.Também nos beneficiamos do olhar crítico de Carlos Coimbra, Marcos Queiroz, Jean Langdon, Cecília Minayo, Ana Canesqui e Luis Castiel, com quem se discutiram algumas das idéias aqui apresentadas.Os cursos minis trados em cursos de pós-graduação e graduação da Faculdade de Filosofia e Ciên cias Humanas da Universidade Federal da Bahia (Ufba) serviram de forma particu lar ŕ sistematização dos autores e teorias discutidos nos artigos.Embora tenham por objetivo refletir sobre aspectos teóricos ou conceituais das ciências sociais em saúde, os artigos se fundamentam em dados empíricos, produzidos em pesquisas desenvolvidas no βmbito do Núcleo de Estudos em Ciências Sociais e Saúde (ECSAS) da Universidade Federal da Bahia, criado em 1993.Juntamente com outros pesquisadores nacionais, os integrantes do núcleo participaram da coordenação do I Encontro Nacional de Antropologia Médica (1993).Desde então, têm-se engajado em pesquisas sob os auspícios de diferen tes agências financiadoras, em organizaçυes de seminários, em ensino e orienta ção na graduação e pós-graduação.Assim, podemos dizer que esta coletβnea é fruto de um trabalho conjunto, envolvendo, além de nós, autores, toda a equipe de pesquisadores e bolsistas do ECSAS.Entre os primeiros cabe mencionar e agra decer a contribuição inestimável de Maria Gabriela Hita, colega do ECSAS e do Departamento de Sociologia, primeira leitora e crítica de praticamente todos os capítulos, além de parceira em muitas de nossas discussυes e projetos.A colabo ração dos estudantes que compυem a equipe do ECSAS, por sua vez, não se resume ŕ atuação na produção de dados: sua participação nos seminários semanais de discussão teórica enriqueceu e ampliou nossa visão.Estes seminários têm re velado grande importβncia na sedimentação de nossa posição intelectual.', '["illness experience","mental illness","illness narratives","phenomenology","existentialism","ethnography of communication","hermeneutics","pragmatism"]', '10.7476/9788575412664', '9788575412664', 'https://books.scielo.org/id/pz254', 'https://books.scielo.org/id/pz254/pdf/rabelo-9788575412664.pdf', NULL, 'https://books.scielo.org/id/pz254/cover/cover_thumbnail.jpeg', NULL, 63, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pz4r6', 'pz4r6', '“Tu garante?”: aprendizagem às margens do Tapajós', NULL, '["Chantal Medaets"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Como é comum em outros contextos nos quais os novatos têm acesso à maior parte das atividades das pessoas mais experientes, no Tapajós aprende-se participando progressivamente dessas atividades. O livro apresenta uma revisão de literatura sobre essa modalidade de “aprendizagem por participação”, explicitando seus princípios gerais e as idiossincrasias da região estudada. Ali, adultos e pessoas mais experientes de maneira geral mostram-se particularmente pouco pacientes com os novatos. Nada mais distante da realidade local que a ideia de que é “errando que se aprende”. A aprendizagem acaba, então, sendo percebida como um desafio: e tu, afinal, “tu garante?”', '["informal learning","intergenerational knowledge transmission","adult learning"]', '10.7476/9786557250402', '9786557250402', 'https://books.scielo.org/id/pz4r6', 'https://books.scielo.org/id/pz4r6/pdf/medaets-9786557250402.pdf', NULL, 'https://books.scielo.org/id/pz4r6/cover/cover_thumbnail.jpeg', NULL, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-pz9f6', 'pz9f6', 'Educação e modernidade: contribuições dos clássicos para a Sociologia da Educação', NULL, '["João Valdir Alves de Souza","Inês Assunção de Castro Teixeira"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Produto de uma disciplina ministrada no Programa de Pós-Graduação em Educação da UFMG, este livro põe no centro do debate as contribuições dos clássicos da Sociologia para a Sociologia da Educação. Sendo a Sociologia uma ciência das sociedades modernas, a contribuição fundamental dos autores foi trazer as principais chaves de leitura para se pensar educação e escola no contexto da modernidade. Temática inesgotável, o que se tenta compreender aqui é como a escola se constitui simultaneamente como pr oduto do mundo moderno e promessa de modernização sociocultural.', '["sociology of education","modernity","classical sociology","schools","modern society","sociocultural modernization","history of sociology"]', '10.7476/9786588592106', '9786588592021', 'https://books.scielo.org/id/pz9f6', NULL, NULL, 'https://books.scielo.org/id/pz9f6/cover/cover_thumbnail.jpeg', 171, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q25q2', 'q25q2', 'África: entretecendo perspectivas', 'entretecendo perspectivas', '["Luís Nicolau Parés","Fábio Baqueiro Figueiredo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta coletânea reúne uma pequena amostra da produção acadêmica recente da linha de pesquisa Estudos Africanos do Programa de Pós-Graduação em Estudos Étnicos e Africanos da Universidade Federal da Bahia (Pós-Afro/UFBA). Concentrando-se em uma ampla gama de realidades africanas, do passado recente e da atualidade, e mobilizando temas como "mitos, oralidades e literaturas", "deslocamentos", "mulheres, agência e representações" e "instituições e nacionalismos", este livro é uma oportunidade de conhecer mais a fundo uma parcela das pesquisas recentes sobre a África feitas no Brasil, tanto para estudantes e professores universitários interessados em temas africanos quanto para o público em geral.', '["African studies","African mythology","oral literature","oral tradition","displacement","women","agency","representation of Africans","institutions","nationalism","African diaspora"]', '10.7476/9786556308968', '9786556306520', 'https://books.scielo.org/id/q25q2', 'https://books.scielo.org/id/q25q2/pdf/pares-9786556308968.pdf', NULL, 'https://books.scielo.org/id/q25q2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q3jyf', 'q3jyf', 'Mãos à obra: experimentos de física econômicos e descomplicados', 'experimentos de física econômicos e descomplicados', '["Claudio Clauderson Xavier","Daniele Guerra da Silva","Bruna Lange Martins"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro, estruturado em seis capítulos, apresenta uma abordagem prática para o ensino de Física usando experimentos e modelos construídos com materiais de baixo custo e facilmente acessíveis. O objetivo é permitir que estudantes, educadores e interessados explorem conceitos complexos de Física, como Mecânica, Óptica, Termodinâmica e Eletromagnetismo, sem a necessidade de equipamentos sofisticados. Baseado em um projeto de iniciação científica, com instruções detalhadas e explicações teóricas, o livro oferece uma maneira econômica e eficaz de aprender e ensinar Física, estimulando o interesse pela Ciência e promovendo o pensamento crítico. Visa, portanto, facilitar o processo de ensino e aprendizagem e tornar a Física acessível a todos.', '["physics education","low-cost experiments","hands-on experiments","mechanics","optics","thermodynamics","electromagnetism","critical thinking"]', '10.7476/9786550191016', '9786550191023', 'https://books.scielo.org/id/q3jyf', 'https://books.scielo.org/id/q3jyf/pdf/menezes-9786550191016.pdf', NULL, 'https://books.scielo.org/id/q3jyf/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q3z6b', 'q3z6b', 'O ritmo como fenômeno multidimensional nas baterias de escola de samba e no candomblé', 'pontos de convergência a partir da diáspora africana', '["Castro, Rafael y"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2023, NULL, 'pt', 'book', 'humanities', 'Humanidades y Artes', NULL, 'Esta pesquisa identifica, a partir da diáspora africana, pontos de convergência entre o candomblé e as baterias das escolas de samba. Utilizamos conceitos expostos por Béhague (1994), Graeff (2015), Hall (2003), Hesse (1971) e Kubik (1979), referentes a características que foram trazidas por diversas etnias e aqui foram apropriadas, mantidas e transformadas, aspectos estes caracterizados pela transculturação, etnicidade e pela compreensão do ritmo como fenômeno multidimensional. As transcrições e análises foram desenvolvidas com base em aspectos musicais (técnicos e interpretativos) observados in loco, através de pesquisa participativa como membro atuante em alguns terreiros de candomblé e em baterias das escolas de samba, mais especificamente no Ilê de Oxalufã (Ketu), na Casa de Angola Kyloatala e na bateria do Grêmio Recreativo Cultural e Social Escola de Samba (GRCSES) Império de Casa Verde, todos localizados na região metropolitana da cidade de São Paulo. Observamos que muitas das estratégias adotadas pelos atores responsáveis pela transformação e manutenção desses padrões resultam em diversas ambiguidades e são realizadas muitas vezes de forma inconsciente. Identificamos que a produção musical e a identificação cultural, apesar de diversas dubiedades interpretativas ou por influências do meio, continuam sendo desenvolvidas a partir de estruturas rítmicas e por conceitos mais amplos de ritmo, herdados via diáspora africana e norteadores de processos coletivos nos terreiros de candomblé e nas baterias das escolas de samba – instituições responsáveis pela divulgação destes saberes diaspóricos.', '[]', '10.7476/9786559543779', '9786559543779', 'https://books.scielo.org/id/q3z6b', 'https://books.scielo.org/id/q3z6b/pdf/castro-9786559543779.pdf', 'https://books.scielo.org/id/q3z6b/epub/castro-9786559543779.epub', 'https://books.scielo.org/id/q3z6b/cover/cover_thumbnail.jpeg', 278, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q3zt8', 'q3zt8', 'Conflitos, eficiência e democracia na gestão pública', NULL, '["Douglas Gerson Braga"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1998, '1998-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'É possível ter serviços públicos com mais qualidade? Como gerenciar as relações no setor de modo que todos saiam ganhando? A população dispõe de meios para garantir sua cidadania, ampliando, assim, sua participação na esfera pública? Como? Em Conflitos, Eficiência e Democracia na Gestâo Pública, há respostas a estas e outras perguntas. De maneira simples, o autor discute a negociação coletiva e suas táticas. Mostra exemplos de documentos que podem ser úteis no processo.', '["public sector management","collective bargaining","public sector labor relations","public service quality","efficiency","democracy","citizen participation"]', '10.7476/9788575412527', '9788585676537', 'https://books.scielo.org/id/q3zt8', 'https://books.scielo.org/id/q3zt8/pdf/braga-9788575412527.pdf', NULL, 'https://books.scielo.org/id/q3zt8/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q43wq', 'q43wq', 'Camponeses e agroindústria: transformação social e representação política na avicultura brasileira', NULL, '["Bernardo Sorj","Malori J. Pompermayer","Odair Luis Coradini"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este trabalho se divide em três partes. Na primeira, mostramos os componentes do complexo agroindustrial, com exceção dos produtores avícolas rurais. A análise mostra a articulação entre a instalação do complexo avícola com a importação de tecnologia dos países capitalistas avançados e a importância das multinacionais instaladas no país. Na segunda parte, analisamos as formas de relacionamento dos produtores rurais com as grandes empresas e setores do complexo agroindustrial. Finalmente, na terceira parte, estudamos as formas de representação política que caracterizam os diferentes setores integrantes do complexo avícola. [trecho retirado da introdução do livro]', '["poultry farming","agro-industrial complex","rural farmers","peasants","multinational corporations","technology transfer","social change","political representation","Brazilian poultry industry","urban-rural relations"]', '10.7476/9788599662526', '9788599662526', 'https://books.scielo.org/id/q43wq', 'https://books.scielo.org/id/q43wq/pdf/sorj-9788599662526.pdf', NULL, 'https://books.scielo.org/id/q43wq/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q46dt', 'q46dt', 'Imaginario social desde las expresiones gráficas en ambientes público-privados del centro de Bogotá', NULL, '["Omar Alonso García Martínez","Yubar Deibi Portilla Benítez"]', 'Editorial Fundación Universitaria San Mateo', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Imaginario social desde las expresiones gráficas en ambientes público-privados del centro de Bogotá, es una serie de especulaciones ornamentales de tres lugares públicos y privados del centro de Bogotá, Colombia. Es un documento mediado por la historia y las relaciones estéticas que se presentan en el Café Pasaje, la Cervecería Luna Park y el bar de Doña Ceci; lugares que por décadas se han establecido como espacios culturales, sociales e intelectuales de la ciudad.', '["social imaginary","graphic design","ornamentation","public and private space","urban history","cultural space"]', '10.7476/9786289558289', '9786289558289', 'https://books.scielo.org/id/q46dt', 'https://books.scielo.org/id/q46dt/pdf/garcia-9786289558289.pdf', NULL, 'https://books.scielo.org/id/q46dt/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q4gzb', 'q4gzb', 'Saúde coletiva: a Abrasco em 35 anos de história', NULL, '["Nísia Trindade Lima","José Francisco Nogueira Paranaguá de Santana","Carlos Henrique Assunção Paiva"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Comemorativo dos 35 anos de atuação da Associação Brasileira de Saúde Coletiva, este livro traz 11 capítulos de pesquisadores e estudiosos que fazem parte dessa história. A coletânea privilegia os grandes eixos da política da Abrasco sem deixar de lado as diferentes áreas temáticas em que atuam seus associados. Trata-se de um registro fundamental do caminho trilhado desde o início da sua atuação, num período político bastante complicado no Brasil, até os dias de hoje, quando ainda há tantos desafios a serem vencidos na área da saúde coletiva. A história da Associação é contada também através de ícones: recuperam-se documentos preciosos como fotografias de personagens e de momentos marcantes, além de materiais de divulgação que pontuam a trajetória da Abrasco.', '["ABRASCO","collective health","health policy","35th anniversary"]', '10.7476/9788575415900', '9788575415900', 'https://books.scielo.org/id/q4gzb', 'https://books.scielo.org/id/q4gzb/pdf/lima-9788575415900.pdf', NULL, 'https://books.scielo.org/id/q4gzb/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q5', 'q5', 'Risco, radiodiagnóstico e vigilância sanitária', NULL, '["Marcus Vinícius Teixeira Navarro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Poucas descobertas causaram tamanho impacto na medicina. Por mais de um século, o radiodiagnóstico vem sendo de fundamental importância para a atenção à saúde humana. Contudo, essa nova tecnologia não trouxe consigo apenas benefícios. Tão rápidos quanto a sua utilização foram os danos causados em pesquisadores, médicos, pacientes e outros indivíduos expostos a esse tipo de radiação. Os danos possíveis não estão relacionados apenas aos efeitos nocivos das radiações ionizantes, mas também aos possíveis erros em diagnóstico. Visando contribuir para o desenvolvimento da área de controle de riscos em radiodiagnóstico, nos campos de conhecimento da saúde coletiva e vigilância sanitária, tão importantes para a saúde individual e coletiva, publica-se, neste livro, a análise do controle de riscos em radiodiagnóstico e seus condicionantes, considerando o marco regulatório vigente e a identificação dos diversos atores implicados nessas práticas.', '["radiodiagnosis","risk control","ionizing radiation","radiation protection","health surveillance","diagnostic errors","radiation exposure","regulatory framework","collective health","stakeholders"]', '10.7476/9788523209247', '9788523209247', 'https://books.scielo.org/id/q5', 'https://books.scielo.org/id/q5/pdf/navarro-9788523209247.pdf', NULL, 'https://books.scielo.org/id/q5/cover/cover_thumbnail.jpeg', NULL, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q569x', 'q569x', 'Comensalidades em trânsito', NULL, '["Carvalho, Maria Claudia da Veiga Soares de","Kraemer, Fabiana Bom","Ferreira, Francisco Romão","Prado, Shirley Donizete"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Consumir uma ou outra comida, em grupo ou sozinho(a), postando ou não nas redes sociais, faz parte de um modo inerente ao espírito humano de armar e de negar sentidos sempre em fluxo. Diante dessas perspectivas relativas ao consumo, a obra reúne estudos sobre comida, identidades sociais e subjetividades cu. Ao mesmo tempo, conformam perspectivas inovadoras dirigidas aos processos de construçãjo olhar está voltado para o caráter provisório dos códigos culturais que são assumidos em função de determinados contextos históricos. São abordagens que investem na desnaturalização da alimentação e do corpo, reorientando o foco dos debates para tensões presentes nas relações sociais cotidianas marcadas por moralizações e jogos de podero das identidades sociais e de subjetividades, conferindo visibilidade aos nexos entre essas temáticas complexas e a comensalidade em diferentes cenas contemporâneas.', '["commensality","dietary intake","social identity","subjectivity","social morality","power relations","cultural codes","food and the body","social media","everyday life"]', '10.7476/9786556301778', '9786556301778', 'https://books.scielo.org/id/q569x', 'https://books.scielo.org/id/q569x/pdf/carvalho-9786556301778.pdf', NULL, 'https://books.scielo.org/id/q569x/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q58k5', 'q58k5', 'Impactos da violência na escola: um diálogo com professores', NULL, '["Simone Gonçalves de Assis","Patrícia Constantino","Joviana Quintes Avanci","Kathie Njaine"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-06-20', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A obra apresenta os fundamentos teóricos e conceituais da violência na escola, de modo a propiciar a análise e a ampliação das possibilidades de intervenção no cotidiano escolar brasileiro. Organizado por pesquisadores do Departamento de Estudos sobre Violência e Saúde Jorge Careli da Escola Nacional de Saúde Pública Sergio Arouca da Fundação Oswaldo Cruz (Claves/ENSP/Fiocruz) e publicado pela Editora Fiocruz em parceria com a ENSP, o livro foi agraciado em 2011 com o 1º lugar do Prêmio Jabuti, na categoria educação. Na coletânea, variados autores compartilham reflexões, a partir da ótica dos direitos humanos, sobre os tipos de violência que acometem a comunidade escolar e seu entorno. Também aborda os efeitos da violência na escola, da escola e contra a escola, sobre a saúde de todos. Esta segunda edição, revista e ampliada, chega em um momento de triste recrudescimento dos atos violentos em sua forma mais extrema: a ocorrência de assassinatos múltiplos em ambiente escolar – evento trágico e traumático, sintoma de fenômenos mais complexos, relacionados à intensificação de variadas formas de violência na sociedade. É na direção dessa imbricada realidade que os autores dirigem seus esforços analíticos e propositivos.', '["school violence","teacher perceptions","school community","human rights","school shootings","health consequences of violence","school violence prevention","Brazilian schools"]', '10.7476/9786557082126', '9786557082126', 'https://books.scielo.org/id/q58k5', 'https://books.scielo.org/id/q58k5/pdf/assis-9786557082126.pdf', NULL, 'https://books.scielo.org/id/q58k5/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q5cc4', 'q5cc4', 'Os diários de Langsdorff Vol. 1', NULL, '["Danuzio Gil Bernardino da Silva","Комиссаров Борис Николаевич","Hans Becher","Paulo Masuti Levy","Marcos P. Braga"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1997, '1997-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O zoólogo, botânico e médico alemão Langsdorff foi o mentor dessa grandiosa aventura naturalista: entre 1821 e 1829, conduziu um grupo de pesquisadores e desenhistas por uma viagem de 17 mil quilômetros, estudando a fauna, a flora e o modo de vida do interior do Brasil. Os registros, em textos e ilustrações, dessas cenas até então inéditas da natureza brasileira estão contidos nesses três primeiros volumes. Um quarto e último volume - contendo mapas e reproduções fac-similares de documentos originais - está em fase de preparo.', '["natural history expedition","Brazilian flora","scientific illustration","19th-century naturalists"]', '10.7476/9788575412442', '9788575412442', 'https://books.scielo.org/id/q5cc4', 'https://books.scielo.org/id/q5cc4/pdf/silva-9788575412442.pdf', NULL, 'https://books.scielo.org/id/q5cc4/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q5fn4', 'q5fn4', 'Alimentação e nutrição na atenção básica: reflexões cotidianas e contribuições para prática do cuidado', NULL, '["Ana Carolina Feldenheimer da Silva","Ana Laura Brandão Motta","Juliana Pereira Casemiro"]', 'EDUERJ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', 'Os textos deste livro se propõem a qualificar o debate acerca das ações de alimentação e nutrição na Atenção Básica. Os autores refletem sobre o conjunto de práticas de cuidados essenciais ao campo da alimentação e nutrição nas atividades diárias das Unidades Básicas de Saúde (UBS) das equipes de Saúde da Família. Espera-se, assim, contribuir para processos de trabalho coerentes com os princípios da integralidade do cuidado. A questão do cuidado é o fio condutor das análises, com base em reflexões da prática dos autores, dialogando com referências do campo teórico. São abordados temas como os avanços e desafios da promoção da alimentação adequada e saudável na Atenção Básica; a atuação do nutricionista nas equipes dos Núcleos Ampliados de Saúde da Família (NASF); a Educação Alimentar e o tratamento da obesidade; e carências nutricionais, agenda tradicional e inconclusa na pauta das ações de alimentação e nutrição no Brasil e no mundo; entre outros.', '["Family Health Strategy","Expanded Family Health Strategy","nutritionist role","food education","obesity treatment","nutritional deficiency","comprehensive care","primary health care units"]', '10.7476/9786587949116', '9786587949116', 'https://books.scielo.org/id/q5fn4', 'https://books.scielo.org/id/q5fn4/pdf/silva-9786587949116.pdf', NULL, 'https://books.scielo.org/id/q5fn4/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q5srn', 'q5srn', 'Política de Saúde: o público e o privado', NULL, '["Catalina Eibenschutz"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Instigante coletânea de ensaios - ora em português, ora em espanhol - sobre a articulação público/privado nos sistemas de saúde da América Latina, elaborados por renomados especialistas do Brasil, Argentina, México, Venezuela e Chile. A orientação dos trabalhos é diversa: uns são fundamentalmente teóricos, outros têm um enfoque macrossocial, alguns técnicos, outros filosóficos; contudo, todos expressam a preocupação com questões tais como: falta de eqüidade, cidadania, participação popular, poder, trabalho médico, seguros privados. A problemática da maioria dos textos contempla o modelo neoliberal latino-americano e seu impacto sobre a realidade da atenção à saúde em vários países.', '["public-private health system","health policy","Latin America","health equity","citizenship","citizen participation","medical work","private health insurance","neoliberalism","health care access"]', '10.7476/9788575412732', '9788575412732', 'https://books.scielo.org/id/q5srn', 'https://books.scielo.org/id/q5srn/pdf/eibenschutz-9788575412732.pdf', NULL, 'https://books.scielo.org/id/q5srn/cover/cover_thumbnail.jpeg', NULL, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q5sxw', 'q5sxw', 'Trabalho Infantil: desafios e abordagens em saúde pública', NULL, '["Valdinei Santos de Aguiar","Luiz Carlos Fadel de Vasconcellos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2021, '2021-11-30', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Neste livro, busca-se oferecer a profissionais do SUS, estudantes e pesquisadores do campo da saúde coletiva/saúde pública considerações sobre aspectos sócio-históricos, teórico-conceituais, jurídicos e práticos que, numa perspectiva crítico-reflexiva, ampliem e aprofundem as discussões e a abordagem do tema do trabalho infantil e da atenção à saúde das crianças e adolescentes trabalhadores.', '["child labor","child and adolescent health","public health","Unified Health System (SUS)","critical reflection"]', '10.7476/9786557081532', '9786557080481', 'https://books.scielo.org/id/q5sxw', NULL, NULL, 'https://books.scielo.org/id/q5sxw/cover/cover_thumbnail.jpeg', 157, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q657t', 'q657t', 'Adoção do partido na arquitetura', NULL, '["Laert P. Neves"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Engineering', 'Nova edição, revista e com novo projeto gráfico. Nesta obra, Laert Neves ensina como adotar a ideia preliminar do edifício. Direcionado aos iniciantes na prática de planejamento arquitetônico, o livro traz um método simples e bastante didático, contendo todos os passos a serem seguidos até a finalização do projeto. Exemplos práticos, imagens e exercícios também estão presentes, facilitando a compreensão dos textos e consolidando o processo de aprendizagem.', '["architectural design process","architectural planning","architectural education","design methodology"]', '10.7476/9788523211554', '9788523207632', 'https://books.scielo.org/id/q657t', NULL, NULL, 'https://books.scielo.org/id/q657t/cover/cover_thumbnail.jpeg', 232, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q65gt', 'q65gt', 'Da estátua à pedra: percursos figurativos de José Saramago', NULL, '["Sandra Ferreira"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O propósito deste ensaio é desenvolver uma leitura comparativa, por aproximação e contraste, de quatro romances de José Saramago. Recorte no amplo universo do romancista português, o trabalho levanta questões que possibilitam um ordenamento das leituras sobre sua obra a partir de um exame detido de um romance de sua fase mais nacional: A jangada de Pedra, em contraposição à trilogia constituída por Ensaio sobre a cegueira, Todos os nomes e A caverna.A obra busca explicitar espelhamentos e refrações entre A Jangada de Pedra e Ensaio sobre a cegueira, bem como as muitas ressonâncias entre Ensaio sobre a cegueira, Todos os nomes e A caverna, e assim delinear um horizonte de convergências estruturais e/ou temáticas perceptível no confronto das obras.Tal estratégia possibilita à autora depreender e apontar a marca narrativa que articula a variedade ficcional de cada romance, os quais agrega sob uma rubrica comum, mostrando que temas, figuras, mitos, símbolos, procedimentos narrativos e outros recursos que deles emergem configuram Saramago como romancista que “sendo a cada vez outro, é sempre o mesmo”.', '["José Saramago","A Jangada de Pedra","Ensaio sobre a cegueira","A Caverna","comparative literary analysis","Portuguese novel","narrative structure","literary motifs","symbols","myth","narrative technique"]', '10.7476/9788568334492', '9788568334492', 'https://books.scielo.org/id/q65gt', 'https://books.scielo.org/id/q65gt/pdf/ferreira-9788568334492.pdf', NULL, 'https://books.scielo.org/id/q65gt/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q6cqx', 'q6cqx', 'Selecionar, controlar e distribuir: o Instituto Nacional de Imigração e Colonização e a política imigratória brasileira (1952-1955)', NULL, '["Amanda Pereira dos Santos"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O tema migratório ganhou destaque nas políticas públicas brasileiras durante o primeiro governo de Getúlio Vargas (1930-1945). Não obstante, em seu segundo governo (1951-1954), Vargas ainda se mostrava preocupado com a política imigratória que deveria ser implementada no Brasil. Com o objetivo de controlar e dirigir o movimento imigratório após a Segunda Guerra, o presidente propôs a criação do Instituto Nacional de Imigração e Colonização (INIC). Assim, o presente trabalho se propõe a analisar a configuração da política imigratória brasileira a partir da fundação desse Instituto, bem como as atividades e os debates ocorridos no primeiro ano de seu funcionamento.', '["immigration policy","Brazilian immigration policy","Getúlio Vargas","post-World War II immigration","immigration control","immigration selection","colonial policy","public policy history"]', '10.7476/9786559542444', '9786559542444', 'https://books.scielo.org/id/q6cqx', 'https://books.scielo.org/id/q6cqx/pdf/santos-9786559542444.pdf', NULL, 'https://books.scielo.org/id/q6cqx/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q6ggp', 'q6ggp', 'Educação e gestão neoliberal: a escola cooperativa de Maringá – uma experiência de Charter School?', NULL, '["Mário Luiz Neves de Azevedo"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Elegemos como objeto central deste livro a relação entre educação e neoliberalismo. Nosso objetivo principal é de conhecer suas origens, descobrir a que veio, discutir sobre as causas da sua aceitação geral e identificar as suas propostas para a educação. O mercado é o instrumento de (des)regulação da economia nomeado pelo neoliberalismo. Os doutrinadores neoliberais imaginam um mercado perfeito. Desejam que ele evite as crises, equilibre a oferta e a procura e aloque eficientemente os recursos. Pode-se analisar esse movimento de diferentes perspectivas. Por uma delas, o neoliberalismo é visto como mais uma representação da falsa consciência expressa pelas classes dominantes ou por frações destas classes. Desse ponto de vista, considera-se que essa falsa interpretação é imposta ao complexo social como se fosse uma leitura verdadeira da realidade. Por outro lado, entretanto, pode-se considerar que há uma “razão real” que justifica e respalda o neoliberalismo. Isto é, devido às deficiências do Estado “realmente existente” no atendimento ao público e em virtude da essência estatal já estar privatizada, as reformas propostas pelos neoliberais são aceitas sem maiores resistências pela população. Não obstante o discurso feito pelos neoliberais de que a educação é das poucas áreas onde o Estado que continuar sendo atendida pelo Estado, na realidade, esse patrocínio estatal, também, passa pelo mercado. As propostas para a educação elaboradas por Milton Friedman, referência inconteste do neoliberalismo, e a experiência privatizante do ensino de primeiro grau ocorrida no Município de Maringá são objetos de análise no presente trabalho.', '["neoliberalism","education policy","charter schools","cooperative schools","school privatization","primary education","marketization of education","state failure","Milton Friedman","Maringá","false consciousness","school finance"]', '10.7476/9786587626062', '9786587626062', 'https://books.scielo.org/id/q6ggp', 'https://books.scielo.org/id/q6ggp/pdf/azevedo-9786587626062.pdf', NULL, 'https://books.scielo.org/id/q6ggp/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q6mxk', 'q6mxk', 'O monstro contemporâneo: a construção social da pedofilia em múltiplos planos', NULL, '["Laura Lowenkron"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Baseado em uma etnografia da CPI da Pedofilia no Senado Federal e das investigações da Polícia Federal no combate à pornografia infantil, o livro se aprofunda na construção histórica das categorias criminais que remetem, hoje, à violência sexual envolvendo menores. Sob um viés antropológico, procura debater as dinâmicas sociais, culturais e morais que moldam a configuração do problema da violência sexual contra crianças e adolescentes, a partir da categoria pedofilia.', '["pedophilia","child sexual abuse","social construction of crime","child pornography","Federal Police investigation","sexual violence against children and adolescents"]', '10.7476/9788575114711', '9788575113714', 'https://books.scielo.org/id/q6mxk', NULL, NULL, 'https://books.scielo.org/id/q6mxk/cover/cover_thumbnail.jpeg', 456, 16, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q6qbq', 'q6qbq', 'Tributo a Vênus: a luta contra a sífilis no Brasil, da passagem do século aos anos 40', NULL, '["Sérgio Carrara"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1996, '1996-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'As Mil Máscaras da SífilisDo Mal Venéreo à Sífilis C omo reconhecia, em meados do século passado, o futuro professor de higiene da Faculdade de Medicina da Bahia, Claudemiro Caldas, a reflexão médica sobre a sífilis passava então por uma verdadeira "revolução científica" (Caldas, 1866:56).Iniciada na primeira metade do século XIX, tal "revolução" apenas se consolidaria no começo do século XX, quando se estabilizam as linhas gerais de um modelo de compreensão da doença, que se manteria praticamente inalterado até meados da década de 40.Envolvendo a própria definição da doença -seu agente causal, sua sintomatologia, os meios de transmissão, suas conseqüências orgânicas e sociais, sua evolução epidemiológica e os meios terapêuticos e profiláticos para abordá-la -, este modelo configurou o discurso e, em larga medida, justificou as ações que, em seu conjunto, formavam a luta antivenérea.É em seu âmbito que a sífilis se transformou no problema venéreo, ou seja, em uma das mais graves doenças humanas e em uma das mais sérias ameaças à saúde pública.Aos olhos dos médicos da passagem do século XIX, o conceito de sífilis tinha sido até então um conjunto de sintomas a um só tempo confusos e inespecíficos, cuja etiologia estivera envolta em metafísica, precon-1 2 3 4 1 26 -Tributo a Vênus: a Luta Contra a Sífilis no Brasil Dos poucos trabalhos disponíveis sobre a história da sífilis, dois me pareceram relevantes para reconstruir em largos traços o que ela teria sido até a chamada "revolução" do século XIX.O trabalho recente do historiador francês Claude Quétel (Quétel, 1986) tem como virtude trazer uma minuciosa descrição das diversas teorias vigentes até aquele momento.Muito mais antigo e menos abrangente, o de Ludwki Fleck (Fleck, 1986(Fleck, [1935]]) oferece, entretanto, uma visão mais sistemática, acompanhada de uma abordagem singular, caracterizada por uma imparcialidade impressionante para quem era, ao mesmo tempo, um cientista envolv ido c om o tema (ele era sifilógrafo) e um pensador original, pioneiro na reflexão sociológica sobre a prática científica.As Mil Máscaras da Sífilis -31 destemidos, esforçados e valorosos" (Almeida, 1902:116).Para ele, a excitação sexual constante, sem ejaculação, ativaria sobretudo as faculdades intelectuais.Vinte anos mais tarde, o obscuro médico Otávio Félix Pedroso ia mais longe na mesma direção, afirmando que, se os eunucos são mentirosos e ladrões, é porque "as mais altas e nobilitantes faculdades intelectuais e morais são obra exclusiva dos testículos" (Pedroso, 1921b:4).Isso não quer dizer, como se verá, que defendessem a abstinência sexual completa como prática saudável.Temos algumas descrições muito vívidas do destino que aguardava o excessivo sexual, o libertino, que por uma escolha impensada, às vezes uma fraqueza de caráter, ou pela inter veniência de uma outra doença qualquer, acabava sendo arrastado a uma alienação progressiva, a uma submissão total ao mal, aos instintos, à loucura e à morte.Em tese apresentada à Faculdade de Medicina do Rio de Janeiro em 1849, José Thomas de Lima, futuro professor de Matéria Médica e Terapêutica, dizia ser, naquele momento, "muito circunscrito" o número dos autores que ainda não haviam refletido sobre os "funestos resultados que seguem de perto os prazeres do amor", dos quais nos oferece uma longa, aterradora, mas interessante descrição: "O indivíduo que se entrega aos excessos do coito, ou porque não tenha chegado ainda a seu completo desenvolvimento, ou porque inteiramente desenvolto solicite a seus órgãos as mais extraordinárias excitações, ou porque tenha passado a idade desses prazeres, ou, porque, finalmente, a fraqueza de sua constituição lhe proíba tais gozos, não tarda a manifestar as seguintes alterações provenientes dos prolongados e contínuos espasmos que acompanham a terminação do ato venéreo, da grande quantidade de sangue que nessa ocasião aflue ao pulmão, coração e cérebro, ou das enormes perdas que sofre o organismo: respiração dificultosa, sufocações amiudadas, palpitações freqüentes, aneurismas, rupturas do coração, hemoptisias, apoplexias fulminantes, digestão laboriosa, alimentos mal elaborados e lançados pela defecação quase no mesmo estado em que foram ingestos, apetite nulo, a absorção intestinal muito fraca, a intersticial mui ativa, profunda magreza, dores na parte posterior do externo, no dorso e entre as espáduas, exalação cutânea aumentada, face pálida, olhos fundos e ternos, deixando escapar lágrimas involuntárias, as frontes e as faces cavadas, as asas do nariz e as orelhas secas e frias, vista enfraquecida, nuvens parecem envolver os olhos diante dos quais volteiam mil objetos imaginários, ouvido pouco apto a seu exercício funcional e atormentado por zoadas e tinidos incômodos; tato, gosto e olfato perdidos ou per vertidos, falta de memória, idiotismo adquirido, mania, hipocondria, tremor dos membros, espasmos, convulsões, catalepsia, alterações, cujas terminações são mui comumente fatais" (Lima, 1849:16).Desde já, gostaria de ressaltar uma característica do discurso médico, claramente explicitada no texto de Lima, cujas conseqüências serão importantes para a luta antivenérea.Refiro-me ao fato de, antes de mais nada, ele especificar claramente em que circunstâncias precisas o excesso sexual poderia ser fisiologicamente danoso.Assim, segundo parece pensar o médico, desde que as solicitações sexuais não fossem "extraordinárias", estando o indivíduo organicamente maduro e tendo uma constituição forte, um exercício sexual regular, ou mesmo ligeiramente excessivo, não poderia implicar danos maiores.De todo modo o abuso tinha conseqüências tão amplas e variadas que, diante delas, alguns médicos não hesitavam e, como retoricamente se perguntava Lima, raciocinavam: "se o abuso dos atos venéreos ocasiona graves desarranjos, que razão haverá para não admitir-se que um agente morbífico tão poderoso seja uma das causas da sífilis?" (Idem).Efetivamente, apoiando-se nas teorias fisiológicas de Broussais e de seus discípulos, vários médicos irão apontar o "abuso dos atos sexuais" como causa imediata e suficiente dos males venéreos.Alguns, como o brasileiro Azambuja, combinavam o tema do contágio ao da irritação, na classificação desses tipos de males.Para ele, seria fundamental, por exemplo, a distinção entre a blenorragia maligna ou sifilítica, adquirida através do contágio, e a blenorragia benigna, produzida apenas pela irritação dos órgãos sexuais, geralmente oriunda do "abuso dos prazeres venéreos", quer fossem solitários ou não.6 Assim, para muitos médicos, até meados do século, eram exclusivamente a "libertinagem, a paixão muito ardente ou a voluptuosidade sem moderação, as únicas verdadeiras fontes das afecções sifilíticas" (Idem, 13).Como se vê, fruto direto de um exercício sexual imoderado, mesmo sem qualquer inter venção divina, a sífilis operava ainda como sinal visível, símbolo natural da conduta moral.O seu caráter de estigma da imoralidade de um indivíduo, de uma sociedade, ou de uma época, por algum tempo parece ter encontrado sua fundamentação científica nos fenômenos da irritação e da inflamação, que, simbolicamente, não deixavam de materializar, no organismo, o ardor em que se consumia a alma: o descontrole e o excesso, percebidos na conduta sexual.Porém, já na segunda metade do século XIX, se há uma relação "mecânica" entre sífilis e sexo, é porque as relações sexuais transformaram-se no meio de transmissão por excelência da doença.Encerrava-se Além da irritação das mucosas produzida durante o ato sexual, também o abuso de substâncias alimentares excitantes e de bebidas espirituosas, de alguns medicamentos, a introdução de matérias acres e irritantes no canal da uretra, a presença de alguma pedra na bexiga, a falta de asseio no "aparelho genital" e principalmente a cópula com mulheres menstruadas seriam causas suficientes para o aparecimento de certos "acidentes venéreos".altura da presente época onde (...) empolga ainda as atenções gerai', '["syphilis","history of syphilis","sexually transmitted infections","history of public health","medical discourse","etiology of syphilis","Brazil","19th century","20th century","public health campaigns","venereal disease clinics"]', '10.7476/9788575412817', '9788575412817', 'https://books.scielo.org/id/q6qbq', 'https://books.scielo.org/id/q6qbq/pdf/carrara-9788575412817.pdf', NULL, 'https://books.scielo.org/id/q6qbq/cover/cover_thumbnail.jpeg', NULL, 65, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q6yyv', 'q6yyv', 'Educação superior e os desafios no novo século: contextos e diálogos Brasil-Portugal', NULL, '["Carlos Benedito Martins","Maria Manuel Vieira"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Apesar de terem chegado tardiamente à modernidade educativa, Brasil e Portugal têm conhecido um acelerado processo de massificação do ensino superior nas últimas três décadas. Embora com ritmos, tempos e contornos específicos, a verdade é que, desde meados dos anos 1970, quando se dá o primeiro impulso massificador em Portugal, até o começo desta década, o número de estudantes inscritos em instituições de ensino superior sextuplicou nos dois países. Não deixa de ser um paradoxo que, em pleno regime ditatorial, na década de 1960, ambos os países tenham assistido à implantação das bases de um modelo moderno de ensino superior. Inspiradas nas teses da teoria do capital humano, popularizadas à época, e nas reformas postas em marcha em vários países ocidentais, tanto a reforma brasileira da universidade de 1968 quanto a reforma portuguesa do ensino, iniciada no final de 1969 e instituída em 1973, tiveram como ambição promover a modernização tendencialmente democratizadora desse nível de ensino no interior de regimes políticos não democráticos. Hoje, os dois sistemas apresentam alguns contornos comuns e enfrentam desafios semelhantes. Por um lado, a sua estrutura expandiu-se e pulverizou-se pelo conjunto do território. Por outro lado, ambos os sistemas diversificaram-se e complexificaram-se grandemente, acrescentando novos subsistemas (centros universitários, faculdades, institutos tecnológicos federais, no caso brasileiro; institutos politécnicos, ensino superior militar e policial, no caso português) ao tradicional ensino universitário e abrindo as portas ao setor privado. Nesse sentido, pode-se sem dúvida afirmar que a paisagem educativa do ensino superior tornou-se mais opaca, uma vez que a enorme diversidade de instituições que hoje a compõem comporta ofertas muito variadas — em qualidade científica, técnica e pedagógica; e em modo de organização e funcionamento —, o que torna particularmente complexa a navegação no seu interior.', '["higher education","massification of higher education","Brazil-Portugal comparison","human capital theory","university reform","democratization of higher education","non-democratic regimes","private higher education","higher education diversification","educational modernization"]', '10.7476/9788523013417', '9788523012137', 'https://books.scielo.org/id/q6yyv', NULL, NULL, 'https://books.scielo.org/id/q6yyv/cover/cover_thumbnail.jpeg', 498, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q77dz', 'q77dz', 'O teatro que corre nas vias', NULL, '["Marcelo Sousa Brito"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A partir de uma metodologia experimental, construída junto ao grupo Espaço Livre de Pesquisa-Ação do Programa de Pós-Graduação em Geografia da Universidade Federal da Bahia (POSGEO/UFBA), e suas experiências como ator e diretor de teatro, o autor faz misturar temáticas ligadas à geografia humana e cultural, à arquitetura e ao urbanismo e à fenomenologia. Seu foco é pensar como o teatro poderia fazer os artistas se relacionarem com o lugar, sendo este um espaço de negociação, de pertencimento, de troca, de afeição e mediação, sobretudo com quem vive o lugar. A intervenção viária como essência do corpo-lugar e do lugar-cênico traz aos estudiosos da arte urbana uma alternativa à categoria “teatralidade”, pois a noção de que o artista, ao deslocar seu corpo-lugar, apropriando-se do espaço urbano através de intervenções viárias, pode produzir lugares-cênicos na cidade.', '["street theatre","urban intervention","place and belonging","theatricality","urban art","phenomenology","architecture and urbanism","urban space appropriation"]', '10.7476/9788523220013', '9788523220013', 'https://books.scielo.org/id/q77dz', 'https://books.scielo.org/id/q77dz/pdf/brito-9788523220013.pdf', NULL, 'https://books.scielo.org/id/q77dz/cover/cover_thumbnail.jpeg', NULL, 9, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q7gtd', 'q7gtd', 'O dilema preventivista: contribuição para a compreensão e crítica da medicina preventiva', NULL, '["Sérgio Arouca"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2003, '2003-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Orientador : Miguel Ignacio Tobar Acosta', '["preventive medicine","public health","health policy"]', '10.7476/9788575416105', '9788575416105', 'https://books.scielo.org/id/q7gtd', 'https://books.scielo.org/id/q7gtd/pdf/arouca-9788575416105.pdf', NULL, 'https://books.scielo.org/id/q7gtd/cover/cover_thumbnail.jpeg', NULL, 114, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q7h4k', 'q7h4k', 'Violência de gênero contra mulheres: suas diferentes faces e estratégias de enfrentamento e monitoramento', NULL, '["Cecília Maria Bacellar Sardenberg","Tavares, Márcia S."]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Com um olhar feminista, as autoras dos artigos que compõem este livro tratam de temas relativos à violência contra as mulheres, isto é, a violência que se manifesta através de ações ou condutas que, com base no gênero, podem resultar em morte, dano, sofrimento físico, sexual ou psicológico às mulheres. A obra traz reflexões acerca da aplicação da Lei Maria da Penha, da segurança pública no atendimento às mulheres e das decisões do Superior Tribunal de Justiça (STJ) nos últimos anos nos casos de violência contra as mulheres.', '["gender-based violence","violence against women","Maria da Penha Law","public security","women''s protection","feminist perspectives","psychological violence","sexual violence"]', '10.7476/9788523220167', '9788523220167', 'https://books.scielo.org/id/q7h4k', 'https://books.scielo.org/id/q7h4k/pdf/sardenberg-9788523220167.pdf', NULL, 'https://books.scielo.org/id/q7h4k/cover/cover_thumbnail.jpeg', NULL, 42, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q7j9j', 'q7j9j', 'Programe-se: uma proposta de experimentação transmídia', NULL, '["Tcharly Magalhães Briglia","Dilson Alves de Souza Reis Júnior","Tainan Maria Barbosa de Souza Piantavinha","Betânia Maria Vilas Bôas Barreto"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra apresenta o processo de produção e a pesquisa teórica do projeto PROGRAME-SE, proposta de experimentação transmídia desdobrada em um documentário, uma websérie e um e-book. O projeto centra-se na análise dos impactos da convergência midiática na linguagem e na produção de conteúdos para a televisão brasileira, bem como no comportamento do público contemporâneo. As discussões traçam um panorama acerca das tendências e perspectivas para o futuro da televisão em meio à ascensão de outras mídias.', '["transmedia storytelling","media convergence","Brazilian television","television content production","documentary film","web series","e-books","audience behavior","future of television","media language"]', '10.7476/9788574555317', '9788574555317', 'https://books.scielo.org/id/q7j9j', 'https://books.scielo.org/id/q7j9j/pdf/briglia-9788574555317.pdf', NULL, 'https://books.scielo.org/id/q7j9j/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q7ryh', 'q7ryh', 'Traços da periferia: política e performance em produções literárias marginais-periféricas contemporâneas', NULL, '["Karina Lima Sales"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é fruto de uma pesquisa de doutorado (SALES, 2019). No título do livro, Traços da periferia: política e performance em produções literárias marginais-periféricas contemporâneas, o uso da expressão “traços da periferia” relaciona-se ao fato de esses traços retratarem os espaços periféricos diversos, representados, (re)criados, transcriados pelos autores em suas produções literárias, que redesenham essas margens, reconfigurando-as performaticamente. A publicação apresenta um estudo sobre a articulação entre políticas da escrita e performance em produções literárias marginais-periféricas contemporâneas do Brasil, a fim de investigar em que medida esses conceitos regem a escrita dos textos, sua circulação e consumo, e quais estratégias de agenciamento político-cultural são produzidas pelos autores delimitados neste estudo, em suas atividades de caráter coletivo.', '["periphery","marginal literature","contemporary Brazilian literature","writing policy","performance","politics of literature","collective authorship","space in literature"]', '10.7476/9786588211571', '9786588211465', 'https://books.scielo.org/id/q7ryh', 'https://books.scielo.org/id/q7ryh/pdf/sales-9786588211571.pdf', 'https://books.scielo.org/id/q7ryh/epub/sales-9786588211571.epub', 'https://books.scielo.org/id/q7ryh/cover/cover_thumbnail.jpeg', 234, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q7vqn', 'q7vqn', 'Catálogo dos estágios iniciais de desenvolvimento dos peixes da bacia de Campos', NULL, '["Ana Cristina Teixeira Bonecker"]', 'Sociedade Brasileira de Zoologia', 'Brasil', 'SciELO Books', 'books', 2014, '2014-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Foram identificados 4.490 indivíduos incluindo 17 ordens, 68 famílias e 160 espécies de peixes nos estágios de larvas e juvenis. Foram elaborados textos com informações gerais das ordens e famílias, descrição das principais características das espécies, fotografias dos diferentes estágios de desenvolvimento, georeferrenciamento, habitat da espécie, nome vulgar e as referências utilizadas para a identificação.', '["fish larvae","juvenile fish","early developmental stages","fish identification","ichthyofauna","species distribution","freshwater fish"]', '10.7476/9788598203102', '9788598203102', 'https://books.scielo.org/id/q7vqn', 'https://books.scielo.org/id/q7vqn/pdf/bonecker-9788598203102.pdf', NULL, 'https://books.scielo.org/id/q7vqn/cover/cover_thumbnail.jpeg', NULL, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q7zxz', 'q7zxz', 'Política de educação no campo: para além da alfabetização (1952-1963)', NULL, '["Iraíde Marques de Freitas Barreiro"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2010, '2010-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro resgata o processo de elaboração, percurso e desenvolvimento da Campanha Nacional de Educação Rural (CNER), criada em 1952 e extinta em 1963, no contexto histórico que a ensejou, articulada às ideias hegemônicas do período, determinantes da ação do Estado e de setores da sociedade civil. Movimentos de organizações internacionais e a política nacional pela expansão do desenvolvimento econômico e modernização rural, aliam a educação a essas finalidades. A Campanha adota orientações pedagógicas da Educação de Base e do Desenvolvimento de Comunidade, pressupostos do funcionalismo e do neotomismo, com respaldo da Igreja Católica. Conhecimentos teóricos e técnicos pretendiam ofertar vida compatível com a dignidade humana e com os ideais democráticos para a cidadania. A pesquisa investiga os processos de conquista da cidadania, na perspectiva da contradição, ao explicitar avanços e retrocessos na relação educativa do programa. A análise considerou o conjunto de fontes documentais produzidas para e pela Campanha, como periódicos e acervo iconográfico, localizados em bibliotecas e arquivos. As categorias de análises contemplam temas emergentes para atender às demandas do campo, como: educação, habitação, saúde, lazer e promoção da educação política, para educação dos costumes, para além da alfabetização. O desenvolvimento da cidadania e da democracia pretendidas fundou-se em situações educativas pontuais e na resolução de conflitos sociais mais voltados para os indivíduos e os grupos, e menos como processos decorrentes do interior das práticas sociais. Contudo, a política foi relevante naquele contexto, pois, se não fosse a nossa cultura de descontinuidades e articulação das políticas sociais, as condições de vida e trabalho no campo poderiam ser outras.', '["rural education policy","rural development","citizenship","democracy","functionalism","neotomism","Catholic Church","community development","political education","literacy","social policy"]', '10.7476/9788579831300', '9788579831300', 'https://books.scielo.org/id/q7zxz', 'https://books.scielo.org/id/q7zxz/pdf/barreiro-9788579831300.pdf', NULL, 'https://books.scielo.org/id/q7zxz/cover/cover_thumbnail.jpeg', NULL, 13, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
