ract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q8z2k', 'q8z2k', 'Comunicação (inter)cultural em interação', NULL, '["Ulrike Agathe Schröder","Mariana Carneiro Mendes"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O que de fato acontece em encontros interculturais reais ou nos que ocorrem entre participantes de uma mesma cultura quando interagem em ou falam sobre outra cultura in situ? Utilizando uma perspectiva empírica, microanalítica e comunicativa, os estudos que compõem este livro – desenvolvidos por pesquisadores do Núcleo de Estudos de Comunicação (Inter)Cultural em Interação da UFMG e de universidades conveniadas no exterior – analisam os padrões linguísticos e reflexivos desenvolvidos e realizados por indivíduos no decorrer de um encontro intercultural.', '["intercultural communication","intercultural interaction","intercultural encounter","linguistic patterns","reflective practice","microanalysis of interaction"]', '10.7476/9786558580102', '9788542302615', 'https://books.scielo.org/id/q8z2k', NULL, NULL, 'https://books.scielo.org/id/q8z2k/cover/cover_thumbnail.jpeg', 270, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q9629', 'q9629', 'A História da educação na formação do Estado republicano: entre ditaduras e resistências democráticas', 'entre ditaduras e resistências democráticas', '["Luz, José Augusto Ramos da","Miguel, Antonieta"]', 'UEFS Editora', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os artigos reunidos nessa coletânea apresenta um panorama abrangente de diversos aspectos da história da educação na república com recortes temáticos que abrange desde o final do século XIX até o final da década de 1980. São análises que abordam diversos aspectos das culturas escolares que se entrecruzam como com questões econômicas, políticas, sociais e culturais e podem ajudar a elucidar permanências e rupturas nos sistemas educacionais presentes na sociedades estudadas.', '["history of education","military dictatorship","democratic resistance","school culture","education system","19th-20th century education"]', '10.7476/9788555921735', '9786589524465', 'https://books.scielo.org/id/q9629', NULL, NULL, 'https://books.scielo.org/id/q9629/cover/cover_thumbnail.jpeg', 381, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-q9t73', 'q9t73', 'Teoria contemporânea da restauração', NULL, '["Salvador Muñoz Viñas"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-07-19', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O livro Teoria contemporânea da Restauração é reconhecido internacionalmente por representar o mais ambicioso esforço teórico em sua área de conhecimento dos últimos 25 anos e por trazer o tema da conservação ao século XXI. Tendo sido publicado em diferentes línguas, é citado amplamente em trabalhos científicos que versam sobre a questão da teoria da restauração e correlatos, tornando-se um clássico no campo do patrimônio cultural. Inicialmente concebida com a motivação de realizar uma compilação dos pensamentos e tendências de acadêmicos e profissionais de diversas áreas do campo da restauração de bens culturais – identificando consistências, contradições e desvios –, esta obra, tão bem realizada e sistematizada, tornou-se uma das principais fontes de estudo e inspiração para a virada epistemológica que hoje se observa nessa área.', '["restoration theory","cultural heritage preservation","cultural heritage"]', '10.7476/9786558580492', '9786558580270', 'https://books.scielo.org/id/q9t73', NULL, NULL, 'https://books.scielo.org/id/q9t73/cover/cover_thumbnail.jpeg', 215, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
