ESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qbh4w', 'qbh4w', 'Formação (bildung), educação e experimentação em Nietzsche', NULL, '["José Fernandes Weber"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', '[RETIRADO/WITHDRAWN] Esta tese busca explicitar a especificidade dos temas da Bildung (formação, cultivo), da educação (Erziehung) e da experimentação [Experimentieren - Erlebnis (vivência)] no pensamento de Nietzsche. Para tanto, sustenta que o movimento de abandono do conceito de formação em favor da noção de educação, e a posterior substituição da educação pelo tema da experimentação, revela um amplo processo de modificação conceitual pelo qual o autor cria uma radical teoria da constituição do humano.', '["Friedrich Nietzsche","Bildung","Erziehung","education","experimentation","Erlebnis","concept of the human"]', '10.7476/9788572166478', '9788572166478', 'https://books.scielo.org/id/qbh4w', NULL, NULL, 'https://books.scielo.org/id/qbh4w/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qbnjk', 'qbnjk', 'Entre o belo e o útil: manuais e práticas do ensino do desenho no Brasil', NULL, '["Renato Palumbo Dória"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é um estudo pioneiro e único por tratar conjuntamente da história da arte e da educação, levando em conta não somente aspectos estéticos e pedagógicos, mas, principalmente, a dimensão social das práticas do ensino do desenho no Brasil, podendo servir de referência para diferentes campos de estudo. Em uma narrativa saborosa em detalhes e experiências singulares por meio dos quais vislumbramos as grandes transformações culturais dos últimos séculos, o livro analisa as publicações dedicadas ao ensino do desenho e apresenta ainda imagens originais localizadas pelo autor em suas pesquisas nos acervos iconográficos brasileiros, em sua maioria nunca antes publicadas.', '["drawing instruction","art education history","drawing manuals","teaching practice","Brazilian art education","cultural change","iconographic archives"]', '10.7476/9788526815322', '9786586253771', 'https://books.scielo.org/id/qbnjk', NULL, NULL, 'https://books.scielo.org/id/qbnjk/cover/cover_thumbnail.jpeg', 183, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qbpkh', 'qbpkh', 'Da cor de terra: representações sociais de professores sobre os alunos no contexto da luta pela terra', NULL, '["Maria Isabel Antunes-Rocha"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Tocar nas representações sociais é delicado para toda análise. Mais delicado e desafiante quando as representações são de educadores-docentes e quando os alunos-educandos são crianças e adolescentes, jovens e adultos do campo, em contextos de luta pela terra. Que representações interferem nessa ação socioeducativa? São apenas representações de professores da escola, da pedagogia ou gestão, arraigadas em nossa formação social, política, cultural e pedagógica? A pesquisa de Maria Isabel Antunes-Rocha tem como foco os professores e as professoras não de qualquer escola, mas dos assentamentos e acampamentos das escolas do campo. O livro é um convite para repensar essas representações que tanto condicionam todas as políticas públicas, não apenas na educação, mas nas políticas agrárias, fundiárias, no projeto de campo e até na demarcação das terras indígena e quilombolas.', '["social representations","teachers","land struggle","agrarian conflict","rural schools","agricultural education","agricultural policy","land reform","indigenous land demarcation","socio-educational action"]', '10.7476/9788542303193', '9788570419156', 'https://books.scielo.org/id/qbpkh', NULL, NULL, 'https://books.scielo.org/id/qbpkh/cover/cover_thumbnail.jpeg', 177, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qbsd6', 'qbsd6', 'Interculturalidade, linguagens e formação de professores', NULL, '["Fábio Marques de Souza","Simone Dália de Gusmão Aranha"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'À sua maneira, cada um dos autores coloca em evidência a sua preocupação e o seu interesse em investigar e refletir, não somente sobre o uso de novas tecnologias, mas também sobre o fazer docente. Essa nova possibilidade de olhar e pensar a educação, dentro de uma perspectiva em que se inserem novas linguagens digitais, multiletramentos, integração e trocas interculturais, torna-se cada vez mais emergente, o que faz ser esta coletânea de textos atual e pertinente. A obra nos chama para um diálogo mais direto, propositivo e integrado entre alguns dos pilares da educação, tais como a formação docente, a instituição escolar, o fazer docente e discente e estas novas formas de se relacionar e se apropiar de novos conhecimentos.', '["interculturality","digital language","teacher professional development","multiliteracies","digital technologies in education","cultural exchange","schools","teaching practice","student learning"]', '10.7476/9788578793470', '9788578793470', 'https://books.scielo.org/id/qbsd6', 'https://books.scielo.org/id/qbsd6/pdf/souza-9788578793470.pdf', NULL, 'https://books.scielo.org/id/qbsd6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qc38p', 'qc38p', 'Do latifúndio à empresa: unidade e diversidade do capitalismo no campo', NULL, '["Juárez Rubens Brandão Lopes"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'other', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este estudo se inscreve num conjunto mais amplo que visa a esclarecer as formas diversas assumidas pela reprodução do capital no campo brasileiro.', '["latifundia","large-scale farming","capitalist reproduction","rural capitalism","agrarian structure","land tenure","Brazilian countryside"]', '10.7476/9788599662748', '9788599662748', 'https://books.scielo.org/id/qc38p', 'https://books.scielo.org/id/qc38p/pdf/lopes-9788599662748.pdf', NULL, 'https://books.scielo.org/id/qc38p/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qct4c', 'qct4c', 'Manual de gestão: arquivística de documentos em saúde', 'arquivística de documentos em saúde', '["Francisco José Aragão Pedroza Cunha","Gillian Leandro de Queiroga Lima","Louise Anunciação Fonseca de Oliveira do Amaral","Rodrigo França Meirelles","Concepción Mendo Carmona","José Antonio Moreiro González"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este manual é destinado à orientação e à reflexão dos gestores e profissionais da saúde acerca da implementação das tecnologias de informações em saúde, em especial a Gestão Arquivística de Documentos (GAD), em suas rotinas de serviços. O livro apresenta os princípios técnicos e os procedimentos voltados ao tratamento e organização dos documentos gerados, recebidos e acumulados nos Organismos Produtores de Serviços de Atenção à Saúde (Opsas).', '["medical records management","health records","health information technology","document organization"]', '10.7476/9786556309408', '9786556308111', 'https://books.scielo.org/id/qct4c', 'https://books.scielo.org/id/qct4c/pdf/cunha-9786556309408.pdf', NULL, 'https://books.scielo.org/id/qct4c/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qdgqt', 'qdgqt', 'Demografia dos povos indígenas no Brasil', NULL, '["Heloísa Pagliaro","Marta Maria do Amaral Azevedo","Ricardo Ventura Santos"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Esta obra de caráter interdisciplinar reúne estudos atuais sobre a demografia indígena no Brasil. O fato de ser interdisciplinar é enriquecedor, uma vez que admite a necessidade de diálogo e correlação entre os diferentes campos do saber, como a demografia, a antropologia e a epidemiologia, que tratam de um assunto para dizer no mínimo desconhecido da maioria da população leiga: onde estão e quem são os índios do Brasil? É a partir dessa tentativa de diálogo que os autores procuraram reunir nesta obra artigos que versam sobre diferentes temas como fecundidade, comportamento reprodutivo e mortalidade de populações indígenas.', '["indigenous demography","indigenous peoples of Brazil","fertility","reproductive behavior","mortality"]', '10.7476/9788575412541', '9788575412541', 'https://books.scielo.org/id/qdgqt', 'https://books.scielo.org/id/qdgqt/pdf/pagliaro-9788575412541.pdf', NULL, 'https://books.scielo.org/id/qdgqt/cover/cover_thumbnail.jpeg', NULL, 74, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qdhj2', 'qdhj2', 'Atualização em fisioterapia na emergência', NULL, '["Márcia Maiumi Fukujima","Sara Franco","Ébe dos Santos Monteiro","Gilmar Fernandes do Prado"]', 'Editora Fap-Unifesp', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Health Professions', '[RETIRADO/WITHDRAWN] Ao trabalho na área de saúde é imprescindível a relação multidisciplinar entre os vários profissionais envolvidos, em um processo crescente de percepção dos fatores implicados no adoecer e no curar. Nesse sentido, a fisioterapia tem-se tornado mais e mais importante em ambientes de pronto-socorro, pronto atendimento e unidades de terapia intensiva.Atualização em Fisioterapia na Emergência apresenta o resultado do trabalho desenvolvido pela equipe de fisioterapia na emergência do Hospital São Paulo, hospital universitário da Unifesp/epm. A demanda crescente por esse profissional em todos os segmentos do atendimento de pronto-socorro nos hospitais brasileiros resultou na elaboração deste livro, que procura discutir os principais temas da área de forma prática e objetiva. Os tópicos abordados incluem, entre outros, ventilação mecânica, revisões sistemáticas, gestão de serviço de fisioterapia na emergência e pronto atendimento em fisioterapia.', '["emergency department","mechanical ventilation","systematic reviews","prehospital care","multidisciplinary care","intensive care unit"]', '10.7476/9788561673673', '9788561673673', 'https://books.scielo.org/id/qdhj2', NULL, NULL, 'https://books.scielo.org/id/qdhj2/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qdy26', 'qdy26', 'O debate bioético e jurídico sobre as diretivas antecipadas de vontade', NULL, '["Matheus Massaro Mabtum","Patrícia Borba Marchetto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'As Diretivas Antecipadas de Vontade, ou testamento vital, como o instituto também é conhecido no Brasil, é o objeto de estudo da presente obra, de autoria de Matheus Massaro Mabtum e Patricia Borba Marchetto, que fazem uma análise bioética e, principalmente, jurídica do instituto ao abordar a responsabilidade civil oriunda da aplicação ou não do documento.', '["living wills","advance directives","bioethics","civil liability","clinical decision-making","end-of-life care"]', '10.7476/9788579836602', '9788579836602', 'https://books.scielo.org/id/qdy26', 'https://books.scielo.org/id/qdy26/pdf/mabtum-9788579836602.pdf', NULL, 'https://books.scielo.org/id/qdy26/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qdy2w', 'qdy2w', 'Uma nova ciência para um novo senso comum', NULL, '["Marcelo Gomes Germano"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este estudo do professor Marcelo Germano, originalmente apresentado como tese de doutorado junto ao Programa de Pós-Graduação em Educação da Universidade Federal da Paraíba sob o título "Popularização da Ciência e Tecnologia: um discurso na interface entre uma nova ciência e um novo senso comum", procura, radical e vigorosamente, resgatar o papel do saber popular no processo de comunicação da ciência e da tecnologia. O autor defende o exercício do diálogo na comunicação humana, não tanto para que cientistas e público se entendam, mas para que todos tenham uma percepção minimamente equivalente dos benefícios e riscos da ciência e da tecnologia para a civilização.', '["popularization of science","science communication","technology communication","popular knowledge","common sense","dialogue","science and society"]', '10.7476/9788578791209', '9788578791209', 'https://books.scielo.org/id/qdy2w', 'https://books.scielo.org/id/qdy2w/pdf/germano-9788578791209.pdf', NULL, 'https://books.scielo.org/id/qdy2w/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qfgmr', 'qfgmr', 'Inclusão digital: polêmica contemporânea', NULL, '["Nelson De Luca Pretto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Os artigos desse livro abordam assuntos como as diretrizes metodológicas utilizadas em ações de inclusão digital,questões relacionadas ao software livre e a análise de uma experiência de inclusão digital em ambiente educacional.', '["digital inclusion","free software","educational technology","digital inclusion policy","methodological recommendations","inclusive education"]', '10.7476/9788523212063', '9788523212063', 'https://books.scielo.org/id/qfgmr', 'https://books.scielo.org/id/qfgmr/pdf/bonilla-9788523212063.pdf', NULL, 'https://books.scielo.org/id/qfgmr/cover/cover_thumbnail.jpeg', NULL, 25, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qfk22', 'qfk22', 'A dança negra em São Paulo: dança afro, carnavais e outros palcos', 'dança afro, carnavais e outros palcos', '["Caroline Nicácio da Rocha"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Essa pesquisa desenvolve uma abordagem qualitativa teórico-prática no campo da Dança Afro, com percurso autoetnográfico entrelaçado com dados históricos e saberes estéticos trazidos pela Agremiação carnavalesca Afoxé Ilê Omo Dadá, juntamente com narrativas trazidas por entrevistas com importantes artistas, considerados mestres e mestras da dança negra paulistana. O trabalho teve o intuito de investigar o conjunto de signos codificados como Dança Afro, resultado de variadas experiências transmitidas em espaços da cidade, na sua maioria informais, escolas de capoeira e pelas agremiações de escolas de samba de São Paulo, formando e profissionalizando em dança diversos artistas negros da cidade.', '["Black dance","São Paulo","carnival","Afro-Brazilian dance","samba schools","Black artists","dance training"]', '10.7476/9786559544455', '9786559544455', 'https://books.scielo.org/id/qfk22', 'https://books.scielo.org/id/qfk22/pdf/rocha-9786559544455.pdf', NULL, 'https://books.scielo.org/id/qfk22/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qfnhd', 'qfnhd', 'Racismo religioso em escolas da Bahia: autoafirmação e inclusão de crianças e jovens de terreiro', NULL, '["Ademar Cirne"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Diante da constatação de que, de modo geral, não ocorreram mudanças no currículo das escolas após a implantação da Lei 10.639/2003, esta temática foi objeto de pesquisa pelo autor, objetivando analisar a diversidade da sociedade, procurando, por meio de um modelo de educação fundamentado nos princípios do multiculturalismo crítico, contribuir para a construção de uma sociedade cada vez mais justa e igualitária, onde os espaços de educação formal não mais tratem as crianças de religiões de matriz africana de forma preconceituosa e racista.', '["religious racism","Afro-Brazilian religions","Law 10.639/2003","multicultural education","critical multiculturalism","school curriculum","Bahia"]', '10.7476/9786586213294', '9786586213294', 'https://books.scielo.org/id/qfnhd', 'https://books.scielo.org/id/qfnhd/pdf/cirne-9786586213294.pdf', NULL, 'https://books.scielo.org/id/qfnhd/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qfx4x', 'qfx4x', 'Ética e paradigmas na psicologia social', NULL, '["Katia Simone Ploner","Lísia Regina Ferreira Michels","Luciane Maria Schlindwein","Pedrinho Arcides Guareschi"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'es', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'A Associação Brasileira de Psicologia Social (ABRAPSO) vem afirmando seu compromisso com área da Psicologia Social, constituindo um espaço de produção e divulgação científica que tem se destacado no cenário nacional. Para contribuir com a produção do conhecimento nesta área, foi realizado em novembro de 2002, o IX Encontro da Regional Sul da ABRAPSO, sediado na Universidade do Vale do Itajaí (UNIVALI), em Itajaí — a Santa Catarina com o tema Ética e Paradigmas da Psicologia Social. O referido evento reuniu estudantes e profissionais da Psicologia e áreas afins, com saberes e histórias diferenciadas. Cumprindo com um dos objetivos da comunidade científica da ABRAPSO, este livro sintetiza a busca de aprimorar e expandir as discussões realizadas neste encontro. [trecho retirado a apresentação do livro]', '["social psychology","research ethics","paradigm","research output","knowledge production"]', '10.7476/9788599662854', '9788599662854', 'https://books.scielo.org/id/qfx4x', 'https://books.scielo.org/id/qfx4x/pdf/ploner-9788599662854.pdf', NULL, 'https://books.scielo.org/id/qfx4x/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qgfnd', 'qgfnd', 'Regulando a TV: uma visão comparativa no Mercosul', NULL, '["Othon Jambeiro"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro apresenta os resultados de um trabalho que teve por objetivo conhecer e sistematizar informações sobre a regulação da TV, tanto aberta quanto por assinatura, nos países do Mercosul. Analisa comparativamente os processos regulatórios pelos quais cada um deles passou recentemente.', '["television regulation","broadcasting regulation","pay television","comparative regulation","Mercosur","regulatory process","comparative media law","media policy"]', '10.7476/9788523212285', '9788523208790', 'https://books.scielo.org/id/qgfnd', 'https://books.scielo.org/id/qgfnd/pdf/jambeiro-9788523212285.pdf', NULL, 'https://books.scielo.org/id/qgfnd/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qgj2x', 'qgj2x', 'Docentes pesquisadores', 'epistemes e metodologias = Teachers researchers: epistemes and methodologies = Docentes investigadores: epistemes y metodologías', '["Silva, Simone Bueno Borges da","Juana María Sancho Gil","Fernando Hernández-Hernández"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Esta contribuição à área da educação é baseada no entendimento de que os cursos de formação de professores geralmente não incluem cursos de metodologia de pesquisa educacional, um campo bastante complexo, que abrange diferentes dimensões e no qual, por mais que possam contribuir, não costumam participar por se sentirem despreparados e bastante sobrecarregados com suas muitas obrigações. O livro é dedicado a todos os interessados em seguir no campo da pesquisa educacional, em particular, os que decidem prosseguir com os estudos de pós-graduação sob a forma de mestrado ou doutoramento. Estão reunidas perspectivas de 23 pesquisadores que vivem em diferentes contextos educacionais e acadêmicos, no Brasil, Argentina, Chile, Portugal, Inglaterra e Espanha.', '["educational research methodology","teacher professional development","graduate education in education","doctoral education","graduate education"]', '10.7476/9786556308821', '9786556305615', 'https://books.scielo.org/id/qgj2x', 'https://books.scielo.org/id/qgj2x/pdf/silva-9786556308821.pdf', NULL, 'https://books.scielo.org/id/qgj2x/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qgydf', 'qgydf', 'Hermilo Borba Filho: memória de resistência e resistência da história', NULL, '["Geralda Medeiros Nóbrega"]', 'EDUEPB', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro, sobre o escritor pernambucano Hermilo Borba Filho, associa a cultura de resistência à cultura popular, uma sintonia com uma linguagem que busca enaltecer a visão de mundo popular, numa idiossincrasia irreverente em que o palavrão, a gíria e o calão atuam como representação de uma realidade que aponta sempre como imagens de vida e as narrativas, de forma crítica, servem de esteio para testemunhar os acontecimentos que cerceiam os desmandos do aparato policial a que são submetidas as pessoas em tempos de ditadura.', '["popular culture","resistance culture","Brazilian military dictatorship","police brutality","political testimony","memory of resistance"]', '10.7476/9788578793340', '9788578793340', 'https://books.scielo.org/id/qgydf', 'https://books.scielo.org/id/qgydf/pdf/nobrega-9788578793340.pdf', NULL, 'https://books.scielo.org/id/qgydf/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qh3hr', 'qh3hr', 'Disputas em torno do espaço urbano: processos de [re]produção', NULL, '["John Gledhill","Maria Gabriela Hita","Mariano Daniel Perelman"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A publicação é resultado de uma série de textos que dão conta de processos sociais que têm efeitos sobre os modos como as pessoas vivem na cidade. Seus organizadores propõem o fomento de discussões em torno de temas como as perspectivas históricas sobre o processo urbano no Brasil, o acesso ao espaço público e a securitização do espaço urbano e o acesso de diferentes atores sociais aos espaços da cidade. A importância dessas discussões partem do pressuposto de que diálogos interdisciplinares são essenciais para compreender e amadurecer os debates sobre o que ocorre hoje nas cidades, especialmente latino-americanas.', '["urban space","social reproduction","urban processes","access to public space","social actors","Brazilian urban history","Latin American cities"]', '10.7476/9788523217303', '9788523215972', 'https://books.scielo.org/id/qh3hr', 'https://books.scielo.org/id/qh3hr/pdf/gledhill-9788523217303.pdf', 'https://books.scielo.org/id/qh3hr/epub/gledhill-9788523217303.epub', 'https://books.scielo.org/id/qh3hr/cover/cover_thumbnail.jpeg', 433, 23, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qhhvc', 'qhhvc', 'Manicômios à brasileira: a institucionalização da loucura no século XXI', 'a institucionalização da loucura no século XXI', '["Sabrina Melo Del Sarto"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2026, '2026-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Embora a Reforma Psiquiátrica brasileira tenha transformado o modelo de atenção à saúde mental e fortalecido a luta por uma sociedade sem manicômios, pessoas continuam vivendo permanentemente em instituições psiquiátricas no país. Em Manicômios à Brasileira: a Institucionalização da Loucura no Século XXI, Sabrina Melo Del Sarto investiga essa realidade a partir de pesquisa etnográfica realizada em hospitais psiquiátricos públicos de Santa Catarina. Ao acompanhar trajetórias de moradores submetidos a longos processos de institucionalização, a autora analisa os mecanismos que contribuem para a permanência da lógica manicomial no Brasil contemporâneo, mesmo após décadas de reformas no campo da saúde mental. A obra articula etnografia, análise documental e reflexão histórica para discutir temas como institucionalização, medicalização da vida, exclusão social e desinstitucionalização. Ao dar visibilidade às experiências daqueles que permanecem vivendo em instituições psiquiátricas, o livro contribui para os debates sobre saúde mental, direitos humanos e políticas públicas, lançando luz sobre desafios ainda presentes na construção de uma sociedade sem manicômios.', '["psychiatric hospitals","institutionalization of madness","deinstitutionalization","mental health reform","medicalization of life","social exclusion","public psychiatric hospitals","Santa Catarina","mental health policy","human rights"]', '10.7476/9786557083079', '9786557082447', 'https://books.scielo.org/id/qhhvc', NULL, NULL, 'https://books.scielo.org/id/qhhvc/cover/cover_thumbnail.jpeg', 229, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qhk4g', 'qhk4g', '“Aqui nessa tribo ninguém quer a sua catequização”: pedagogia social, educação popular em saúde e perspectiva decolonial', NULL, '["Janine Moreira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '[RETIRADO/WITHDRAWN] O que faz de nós, profissionais dos campos da saúde e da educação, nos sentirmos tão necessários à vida das pessoas a ponto de ignorarmos quando elas não querem a nossa “ajuda”? Como saber se o que as pessoas demandam de nós coincide com o que elas realmente necessitam? E, afinal, quando nem a sensibilidade de ouvir, nem a comunicação estão presentes e as pessoas “nos mandam de volta para os nossos lares”; como interpretamos este recado? O livro busca a reflexão destas questões no campo da educação em saúde a partir de posicionamentos críticos da educação popular no Brasil e da pedagogia social na Espanha, tecidas pela perspectiva decolonial.', '["social pedagogy","decoloniality","health education","popular education","healthcare workers"]', '10.7476/9786586768053', '9786586768053', 'https://books.scielo.org/id/qhk4g', NULL, NULL, 'https://books.scielo.org/id/qhk4g/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qhzxr', 'qhzxr', 'Superbactérias resistentes a antimicrobianos', NULL, '["Assef, Ana Paula D''Alincourt Carvalho","Santos, Leticia Miranda Lery","Zahner, Viviane"]', 'Directory of Open access Books (OAPEN Foundation)', 'Brasil', 'SciELO Books', 'books', 2025, '2025-04-15', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'A resistência bacteriana a antimicrobianos é considerada uma das principais ameaças à saúde pública global. Reunindo especialistas de diferentes áreas, este livro apresenta os principais aspectos dessa crise: desde os mecanismos de resistência até as implicações clínicas, sociais e ambientais das infecções causadas por bactérias multirresistentes. A obra aborda ainda o conceito de Saúde Única, destaca a importância das pesquisas básicas e explora estratégias terapêuticas e de monitoramento. Voltado a estudantes, profissionais e pesquisadores da saúde, o livro é uma ferramenta essencial para compreender e enfrentar um dos grandes desafios da atualidade.', '["antimicrobial resistance","multidrug-resistant bacteria","One Health","antimicrobial resistance surveillance","public health risk"]', '10.7476/9786557082331', '9786557082331', 'https://books.scielo.org/id/qhzxr', 'https://books.scielo.org/id/qhzxr/pdf/assef-9786557082331.pdf', NULL, 'https://books.scielo.org/id/qhzxr/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qjc6f', 'qjc6f', 'Educações, culturas e hackers: escritos e reflexões', NULL, '["Nelson De Luca Pretto"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro reúne textos que trazem uma visão panorâmica de temas contemporâneos, passando pela educação, cultura, ciência, universidade e cibercultura, sistematizando o pensar do professor e pesquisador Nelson Pretto, da Faculdade de Educação da UFBA. A obra contempla, ainda, escritos menores em tamanho, os quais, na trilha dessas reflexões, provocam e convocam o leitor a um pensar crítico sobre esses temas, com o propósito de estimular ações ativistas de todos os envolvidos nos processos educacionais, sejam eles formais ou não formais.', '["education","culture","hackers","hacking","digital culture"]', '10.7476/9788523220198', '9788523220198', 'https://books.scielo.org/id/qjc6f', 'https://books.scielo.org/id/qjc6f/pdf/pretto-9788523220198.pdf', NULL, 'https://books.scielo.org/id/qjc6f/cover/cover_thumbnail.jpeg', NULL, 15, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qjjw6', 'qjjw6', 'As ilusões da liberdade: a escola Nina Rodrigues e a antropologia no Brasil', NULL, '["Mariza Corrêa"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', '"Nina Rodrigues é geralmente conhecido: pelos elogios dos seus admiradores e discípulos, por um lado; pelas críticas às suas teorias por parte dos seus detratores, por outro. Os primeiros o tratam como o herói fundador da antropologia e da medicina legal brasileiras e o primeiro a desenvolver pesquisa científica sobre a presença da África no Brasil. Os segundos o condenam pelas suas teorias fundadas no racismo científico e na criminologia biológica. Neste livro, Mariza Corrêa, na melhor tradição da antropologia, prefere evitar julgamentos anacrônicos para apresentar e compreender as obras escritas e o trabalho institucional de Nina Rodrigues no contexto social e político em que ele vivia. A autora examina a vasta obra deste cientista que morreu com apenas 44 anos em 1906 para revelar que tanto detratores como discípulos tinham um pouco de razão, mas que há muito mais a dizer sobre o professor Nina Rodrigues. Ele tinha 26 anos quando da abolição da escravidão em 1888, tendo se formado médico um ano antes. Mariza Corrêa nos leva pela luta de Nina Rodrigues para estabelecer a medicina legal como disciplina acadêmica e pelos meandros daquilo pelo qual ele seja talvez mais lembrado, isto é, o seu polêmico trabalho sobre raça e a sua condenação da mestiçagem. A autora também trata dos seus escritos sobre o que considerava os limites da liberdade no contexto do enfrentamento entre defensores do direito clássico e aqueles do direito positivo. Para completar o quadro, examina o trabalho dos discípulos de Nina Rodrigues. Dada a atuação de Nina Rodrigues nos campos da medicina legal, da psiquiatria e dos estudos sobre a questão racial, e sua constante preocupação com o destino da nação brasileira, este livro tem se tornado leitura privilegiada para todos os interessados nestes temas, que continuam tão ou mais candentes." Peter Fry, doutor em antropologia social e professor emérito do Instituto de Filosofia e Ciências Sociais da Universidade Federal do Rio de Janeiro', '["Nina Rodrigues","forensic medicine","scientific racism","biological criminology","miscegenation","Brazilian anthropology","psychiatry","Brazilian national identity","19th-century Brazil","abolition of slavery"]', '10.7476/9788575415696', '9788575414323', 'https://books.scielo.org/id/qjjw6', NULL, NULL, 'https://books.scielo.org/id/qjjw6/cover/cover_thumbnail.jpeg', 389, 99, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qjtv7', 'qjtv7', 'Trabalho, saúde e adoecimento mental: percursos na rede de atenção do SUS', NULL, '["Adriana de Paula Reis"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Este livro é resultado de uma pesquisa sobre a assistência prestada, no Sistema Único de Saúde (SUS), aos usuários com questões de saúde mental relacionadas às suas vivências nos ambientes de trabalho. Com referencial teórico-metodológico apoiado em Vygotsky, Politzer e inspirado na abordagem pluridimensional de Le Guillant, reúne de forma sensível algumas narrativas de usuários e trabalhadores de saúde de uma cidade da Região Metropolitana de Belo Horizonte (MG). São variadas e complexas as histórias e percursos de trabalho, saúde e adoecimento mental dos usuários do SUS. Dentre outras constatações, o estudo aponta para a importância do compartilhamento dos saberes entre profissionais e usuários e para a necessidade do aprimoramento da comunicação entre os pontos da rede de saúde, por meio de articulações intra e intersetorial. No processo da referida pesquisa, o trabalho é deslocado de uma quase invisibilidade no conjunto da queixa dos usuários, para a condição de categoria de análise e intervenção, visando a saúde do trabalhador. Constitui-se, dessa forma, em uma relevante contribuição à área da Saúde Mental e Trabalho.', '["mental health","work and mental health","workplace mental health","mental illness","Unified Health System (SUS)","health care networks","user narratives","healthcare workers","knowledge sharing","intersectoral coordination","employee health","Belo Horizonte"]', '10.7476/9786557080856', '9786557080245', 'https://books.scielo.org/id/qjtv7', NULL, NULL, 'https://books.scielo.org/id/qjtv7/cover/cover_thumbnail.jpeg', 265, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qk', 'qk', 'Toxicomanias: incidências clínicas e socioantropológicas', NULL, '["Antônio Nery Filho","M. Jackson Edward","Luiz Alberto Tavares","Marlize Rêgo"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'As reflexões e os debates em torno do uso e abuso de drogas traduzem as diversas formas que o humano utiliza para lidar com a dor da sua própria existência. Os leitores oriundos de diversas áreas do conhecimento, bem como as pessoas interessadas no tema, terão a possibilidade de percorrer textos que apontam questões, trazendo à tona impasses e perspectivas para a construção de múltiplas possibilidades de trabalho.', '["toxicomania","drug use","drug abuse","clinical incidence","substance use disorders"]', '10.7476/9788523208820', '9788523208820', 'https://books.scielo.org/id/qk', 'https://books.scielo.org/id/qk/pdf/nery-9788523208820.pdf', NULL, 'https://books.scielo.org/id/qk/cover/cover_thumbnail.jpeg', NULL, 6, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qkjhh', 'qkjhh', 'Prática e crítica da atuação teatral em onze ensaios', NULL, '["Lúcia Regina Vieira Romano"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Os onze ensaios aqui reunidos abordam diferentes facetas da discussão sobre o fazer de atores e atrizes. Produzidos entre 2017 e 2023, pretendem desenhar uma teoria da atuação que dialogue com outras instâncias da teoria teatral – história, estética, crítica, metodologia, processos criativos e pedagogia – ao mesmo tempo que se distanciem de uma pretensão universalizante. Examinando a arte atoral em contracenação com outras funções da criação cênica (direção, dramaturgia, recepção e ensino-aprendizado), os textos refletem a experiência de atuação no Brasil contemporâneo. Nutridos pela curiosidade sobre o que transborda as fronteiras das relações entre os saberes canônicos da tradição euro-ocidental, a problemática das matrizes de atuação modernas e as reinvenções nacionais na perspectiva das poéticas atorais, estes escritos abrem fissuras na discursividade crítica sobre a cena, diante de enunciações que emergem em atrito com o já estabelecido.', '["acting theory","actor training","theatre practice","theatre criticism","Brazilian theatre","stage direction","dramaturgy","theatrical reception"]', '10.7476/9786557145517', '9786557145517', 'https://books.scielo.org/id/qkjhh', 'https://books.scielo.org/id/qkjhh/pdf/romano-9786557145517.pdf', NULL, 'https://books.scielo.org/id/qkjhh/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qmb26', 'qmb26', 'História das ciências: uma história de historiadores ausentes - precondições para o aparecimento dos sciences studies', NULL, '["Carlos Alvarez Maia"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra focaliza os principais eventos historiográficos do século XX, situados entre as décadas de 1920 e 1970, que, sob o manto do cientificismo, alimentaram o afastamento da história das ciências das abordagens efetivamente histórico-sociais.', '["history of science","historiography of science","scientism","20th-century historiography","historians of science","social history of science"]', '10.7476/9788575114407', '9788575112700', 'https://books.scielo.org/id/qmb26', NULL, NULL, 'https://books.scielo.org/id/qmb26/cover/cover_thumbnail.jpeg', 308, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qmncm', 'qmncm', 'Diálogos entre ciência e divulgação científica: leituras contemporâneas', NULL, '["de Magalhães Porto, Cristiane","Marcos Pereira Brotas, Antonio","Terezinha Bortoliero, Simone"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', 'Este livro tem como principal objetivo traçar um perfil dos dirigentes e sindicalistas que participaram do congresso de fundação da Força Sindical: profissão, idade, sexo, entidades que representavam opiniões políticas e sindicais, etc. As informações foram obtidas através de um questionário aplicado a delegados e membros da Direção Nacional que participaram do congresso, realizado em São Paulo, no Memorial da América Latina, durante os dias 8, 9 e 10 de março de 1991.', '["trade union congress","trade union leaders","union delegates","political attitudes","labor movement","São Paulo"]', '10.7476/9788579820205', '9788579820205', 'https://books.scielo.org/id/qmncm', 'https://books.scielo.org/id/qmncm/pdf/rodrigues-9788579820205.pdf', NULL, 'https://books.scielo.org/id/qmncm/cover/cover_thumbnail.jpeg', NULL, 12, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qmy3t', 'qmy3t', 'Incidencia de los proyectos de Vinculación con la Sociedad de la Universidad Politécnica Salesiana. Volumen 2', NULL, '["Garzón Vera, Blas","Cárdenas Tapia, Juan, sdb"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2022, '2022-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Con este mismo título, en diciembre de 2021, apareció el primer volumen de este trabajo. La intención fue sistematizar algunos proyectos de vinculación que habían logrado impactos sociales en términos cualitativos y de innovación educativa. En esa oportunidad se presentó una obra con diez capítulos de reflexión, sistematización, análisis y descripción de la trascendental importancia que implica, para la UPS, la vinculación con la sociedad. Ahora, al cumplir la UPS 28 años de vida institucional, presentamos este segundo volumen, que recoge en 14 capítulos el trabajo de 3 docentes, administrativos, estudiantes e investigadores invitados de distintos campos científicos. Es la continuación de la sistematización de los proyectos de vinculación emblemáticos que se han desarrollado en las sedes de Cuenca, Quito y Guayaquil de la universidad. EN cada uno de ellos se podrá encontrar el esfuerzo que la UPS ha desarrollado en estos 28 años, desde su fundación, para conseguir transformaciones sociales. Fiel a su misión y visión institucional, ha desplegado un arduo trabajo en el capo científico, tecnológico y cultural, dándose a conocer como una institución de excelencia académica, producción científica, responsabilidad social y capacidad de incidir en el desarrollo de la sociedad ecuatoriana.', '["university-society linkage","educational innovation","social change","university social responsibility","Ecuadorian higher education"]', '10.7476/9789978108215', '9789978108215', 'https://books.scielo.org/id/qmy3t', 'https://books.scielo.org/id/qmy3t/pdf/garzon-9789978108215.pdf', NULL, 'https://books.scielo.org/id/qmy3t/cover/cover_thumbnail.jpeg', NULL, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qn56j', 'qn56j', 'O teatro adulto na cidade de São Paulo na década de 1980', NULL, '["Alexandre Mate"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro é resultado de pesquisa e reflexão prodigiosas sobre o teatro em São Paulo nos anos de 1980. A elaboração analítica de um panorama exaustivo da produção comercial produz os critérios necessários ao exame da trajetória de dois grupos – Teatro União e Olho Vivo e Apoena/Engenho Teatral -, que, por opções ética, política e estética, atuaram à margem do circuito, pagando o preço da incompreensão crítica e da invisibilidade social. Em reviravolta histórica, esses mesmos grupos se torna­ram referência para a quase totalidade dos jovens que assumiram a cena – igualmente marginal – desde o final do século XX e que respondem pelo que há de melhor na cena paulista da primeira década do século XXI. Estamos diante de obra de referência: o professor Alexandre Mate expõe a experiência de grupos essenciais em nossa cena mais exigente e generosamente disponibiliza material valioso para novas pesquisas.', '["São Paulo theatre","1980s","theatre groups","theatre criticism","theatre aesthetics","theatre ethics","theatre and politics","theatre history"]', '10.7476/9786557145364', '9786557145364', 'https://books.scielo.org/id/qn56j', 'https://books.scielo.org/id/qn56j/pdf/mate-9786557145364.pdf', NULL, 'https://books.scielo.org/id/qn56j/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qn5j6', 'qn5j6', 'O que os pares de Teletandem (não) negociam: práticas para um novo contexto online interativo para o ensino/aprendizagem de línguas estrangeiras no século XXI', NULL, '["Daniela Nogueira de Moraes Garcia"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A questão abordada neste livro é como proporcionar ao estudante brasileiro de uma língua estrangeira contato autêntico com falantes dessa língua. Para a autora, a solução está no uso das tecnologias de informação, que estão se tornando cada vez mais acessíveis – hoje, um aluno brasileiro pode conversar com pessoas de praticamente qualquer lugar do mundo via internet, ao custo de uma fração do preço de uma chamada local de telefone. O livro detalha um projeto que vem se consolidando no Brasil e que já é bastante conhecido no exterior: o “Projeto Teletandem: línguas estrangeiras para todos”, que coloca alunos universitários brasileiros desejosos de aprender uma língua estrangeira em contato com universitários de outros países que estão aprendendo português. A modalidade Tandem nasceu na Alemanha no final dos anos 1960 e há décadas é utilizado em vários países da Europa. Segundo a autora, o complicador no Brasil é a distância geográfica e cultural de outros povos e línguas e também os obstáculos técnicos e financeiros para o estabelecimento de um intercâmbio realmente eficiente e frutuoso. O livro oferece subsídios para contornar essas dificuldades e auxiliar as práticas pedagógicas desenvolvidas nas aulas de línguas baseadas nas parcerias de teletandem.', '["teletandem","tandem language learning","online language exchange","foreign language teaching","university students","Portuguese as a foreign language","teaching practice"]', '10.7476/9788539304165', '9788539304165', 'https://books.scielo.org/id/qn5j6', 'https://books.scielo.org/id/qn5j6/pdf/garcia-9788539304165.pdf', NULL, 'https://books.scielo.org/id/qn5j6/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qnvjy', 'qnvjy', 'Uma educadora republicana: a face desconhecida de Maria Lacerda de Moura', NULL, '["Paula Cristina David Guimarães"]', 'Editora UFMG', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro apresenta a face desconhecida de Maria Lacerda de Moura: a de professora republicana. No contexto da Barbacena do início do século XX, é apresentada a professora que iniciou sua carreira na Escola Normal da cidade, lugar onde mobilizou discursos, publicações e ações para validar a educação como condição primordial para a efetivação da república brasileira. Também é apresentada a reformadora social, que desafiou a sociedade patriarcal de seu tempo ao se colocar como intelectual e pesquisadora da educação, espaços pouco autorizados à mulher naquele período. Amparada na racionalidade científica e em redes de sociabilidade, Maria Lacerda se colocou como pioneira na escrita de um projeto de estudo científico da infância, materializando o desejo de implementar a escola graduada, considerada a única organização possível para a efetiva educação de uma maior parte da população. Sua postura feminista, contudo, não deixou de gerar desconfianças sobre sua atuação, que foi alvo de cerceamento pelo governo do estado.', '["Maria Lacerda de Moura","republican education","women teachers","Barbacena","early 20th century","feminist pedagogy","childhood studies","scientific rationality","patriarchy","state repression","republican discourse","history of education"]', '10.7476/9786558580829', '9786558580416', 'https://books.scielo.org/id/qnvjy', NULL, NULL, 'https://books.scielo.org/id/qnvjy/cover/cover_thumbnail.jpeg', 278, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qnx69', 'qnx69', 'Renovadas formas de hacer oposición', NULL, '["Freddy Canté","Beatriz Franco Cuervo"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2013, '2013-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este texto ofrece herramientas y conceptos para hacer una oposición política novedosa, desde el ámbito legal aporta iniciativas en cuanto a garantías y justas reglas para la actividad política, y desde el ámbito de la presión y movilización social ofrece un repertorio de estrategias, tácticas y símbolos, todo esto con ejemplos de experiencias históricas. Si pensamos en un proceso de paz exitoso es entonces imperativo ofrecer desde la academia unas herramientas y pautas para hacer política y ejercer oposición. Los aportes de este libro contribuyen a tal causa, y serán más impactantes en directa proporción a la difusión y discusión de este texto.', '["political opposition","political mobilization","social pressure","protest tactics","protest symbols","political guarantee","peace process"]', '10.7476/9789587384222', '9789587384215', 'https://books.scielo.org/id/qnx69', NULL, NULL, 'https://books.scielo.org/id/qnx69/cover/cover_thumbnail.jpeg', 338, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qny2r', 'qny2r', 'Modelos de tomada de decisão para inovação em empresas', NULL, '["Herbert Kimura","Leonardo Fernando Cruz Basso"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Business, Management and Accounting', '[RETIRADO/WITHDRAWN] Segundo dados do IBGE, 88,3% das empresas inovadoras declararam obter impactos positivos e significativos provenientes da inovação. Apesar da importância da inovação para a prática empresarial, poucos livros no Brasil exploram teorias que buscam explicar as relações entre inovação e vantagens competitivas. Nesse contexto, Modelos de tomada de decisão para inovação em empresas explora a ligação entre as teorias de finanças e as de estratégia e identifica impactos práticos de estratégias de inovação.', '["innovation","decision models","competitive advantage","innovation strategy","corporate innovation","innovation impact"]', '10.7476/9788582930519', '9788582930519', 'https://books.scielo.org/id/qny2r', NULL, NULL, 'https://books.scielo.org/id/qny2r/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qp4g6', 'qp4g6', '¿Qué nos dejó la pandemia? Retos y aprendizajes para la educación superior', NULL, '["Loyola-Illescas, Edgar"]', 'Editorial Abya-Yala', 'Ecuador', 'SciELO Books', 'books', 2021, '2021-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Experiencias, vivencias y reflexiones sobre la realidad actual de la educación universitaria forman parte de esta publicación. La transición de una educación mayoritariamente presencial a una educación de emergencia a distancia con la proyección de un futuro de un sistema híbrido, exige nuevos retos. Los cambios no pueden ser solo de forma: la crisis provocada por la pandemia demanda transformaciones en varios aspectos: la modalidad, el ritmo, los roles de estudiantes y docentes, la metodología, las formas de evaluar, las características del aprendizaje síncrono u asíncrono, el uso de la tecnología. Todo esto implica la construcción colectiva de una nueva realidad educativa orientada a la formación de una ciudadanía activa, con herramientas personales y profesionales para mejorar la realidad social actual.', '["COVID-19 pandemic","higher education","emergency distance learning","hybrid learning","teacher-student roles","assessment methods","synchronous and asynchronous learning","educational technology","active citizenship"]', '10.7476/9789978106754', '9789978106754', 'https://books.scielo.org/id/qp4g6', 'https://books.scielo.org/id/qp4g6/pdf/loyola-9789978106754.pdf', NULL, 'https://books.scielo.org/id/qp4g6/cover/cover_thumbnail.jpeg', NULL, 7, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qprrp', 'qprrp', 'Cadastro Único: tecnologia de reclassificação social', NULL, '["José Carlos da Exaltação Torres"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro analisa o processo de criação, desenvolvimento e operacionalização do sistema de Cadastro Único para Programas Sociais do Governo Federal (CadÚnico). Por meio de entrevistas, noticiário jornalístico e consultas a documentação institucional, a obra se debruça sobre a gerência das políticas sociais focalizadas que exigem a operação de uma estrutura institucional e tecnológica complexa, voltada à produção de estatísticas para se definir sobre quem são os pobres do Brasil – o público-alvo das ações assistencialistas do Estado.', '["social assistance targeting","social policy management","government social programs","poverty measurement","statistical production"]', '10.7476/9786556300115', '9786556300115', 'https://books.scielo.org/id/qprrp', 'https://books.scielo.org/id/qprrp/pdf/torres-9786556300115.pdf', NULL, 'https://books.scielo.org/id/qprrp/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qq8zp', 'qq8zp', 'Saúde do trabalhador na sociedade brasileira contemporânea', NULL, '["Carlos Minayo-Gómez","Jorge Mesquita Huet Machado","Paulo Gilvane Lopes Pena"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Medicine', 'Apresenta o estado da arte em saúde do trabalhador ao debater questões como a incorporação tecnológica e a globalização dos mercados, assim como a persistência de formas arcaicas de produção, a precarização do trabalho e a exclusão social. O foco é a saúde integral do trabalhador: os autores procuram interpretar a origem das situações seja do ponto de vista tecnológico, econômico, social ou político. Eles estudam todo o processo de trabalho, que engloba, sobretudo, as relações sociais. Entre as principais contribuições da coletânea destacam-se a incorporação do setor de serviços ao debate em saúde do trabalhador e a reflexão sobre questões de saúde mental, abordando as subjetividades, o sofrimento e o estresse dos trabalhadores. A obra também traz análises sobre políticas públicas e vigilância em saúde do trabalhador. Ao fazer um diagnóstico da área, o livro identifica avanços e lacunas e, assim, sinaliza propostas de ação.', '["employee health","globalization","precarization of work","social exclusion","service sector","mental health","worker stress","work-related suffering","subjectivity","public health policy","occupational health surveillance","Brazilian society"]', '10.7476/9788575413654', '9788575412046', 'https://books.scielo.org/id/qq8zp', 'https://books.scielo.org/id/qq8zp/pdf/minayo-9788575413654.pdf', 'https://books.scielo.org/id/qq8zp/epub/minayo-9788575413654.epub', 'https://books.scielo.org/id/qq8zp/cover/cover_thumbnail.jpeg', 540, 37, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qqbxd', 'qqbxd', 'Militância de Florestan Fernandes em defesa da escola pública brasileira (1954 – 1964)', NULL, '["Mário Borges Netto"]', 'EDUEM', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Esta obra trata da ação intelectual de Florestan Fernandes no campo educacional, no período de 1954 a 1964, quando da sua militância como intelectual em defesa da educação pública no contexto da elaboração e tramitação da LDB nº 4.024, de 1961. Sociólogo de formação, um dos principais estudiosos da constituição da sociedade e do capitalismo brasileiro, legítimo intelectual orgânico dos grupos subalternos, Florestan Fernandes ficou marcado na historiografia da educação brasileira por seu envolvimento ativo e persistente na luta pela escolarização dos filhos da classe trabalhadora.', '["Florestan Fernandes","public education","education policy","subaltern groups","history of education in Brazil"]', '10.7476/9786587626093', '9786586383911', 'https://books.scielo.org/id/qqbxd', NULL, NULL, 'https://books.scielo.org/id/qqbxd/cover/cover_thumbnail.jpeg', 150, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qqhcb', 'qqhcb', 'De volta ao lago de leite: gênero e transformação no Alto Rio Negro', NULL, '["Cristiane Lasmar"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O objetivo desta pesquisa foi refletir sobre o movimento dos habitantes do rio Uaupés (afluente do rio Negro) em direção ao mundo dos brancos, buscando delinear o seu sentido segundo os princípios da sociocosmologia nativa. Ela dedica-se a pensar as transformações que ocorrem no modo de vida dos índios uma vez que eles deixam suas comunidades de origem, situadas ao longo de toda a faixa ribeirinha, e passam a residir na cidade de São Gabriel da Cachoeira. Ao se mudar para a cidade, a população indígena realiza um movimento de descida dos rios Uaupés e Negro para se fixar no curso médio desse último. Parte do pressuposto de que uma reflexão sobre o movimento dos habitantes do Uaupés em direção à cidade precisa considerar, de um lado, suas implicações para as relações sociais e o modo como ele se vê implicado por elas; de outro, as concepções cosmológicas que informam a imagem dos índios sobre si mesmos e sobre os brancos.', '["Alto Rio Negro","São Gabriel da Cachoeira","indigenous life","indigenous cosmology","gender","social change","riverine communities"]', '10.7476/9788539302956', '9788571396210', 'https://books.scielo.org/id/qqhcb', NULL, NULL, 'https://books.scielo.org/id/qqhcb/cover/cover_thumbnail.jpeg', 288, 44, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qqjvh', 'qqjvh', 'Memória, multiplicidade e metalinguagem: modulações autorais em Manoel de Barros e Roberval Pereyr', NULL, '["José Rosa dos Santos Júnior"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O presente livro que é resultado da pesquisa de doutorado do autor tem o objetivo de refletir acerca das modulações autorais presentes nas obras de Manoel de Barros e de Roberval Pereyr. As discussões nele emprendidas estão balizadas pelos prismas da autobiografia, da multiplicidade e da metalinguagem. No processo criativo de Manoel de Barros, poeta do Mato Grosso do Sul, as lembranças ocupam lugar de destaque, criativamente representando sua vida no Pantanal. Já em Roberval Pereyr aparecem as experiências acadêmicas, artísticas e ativistas. Obras e autores que se afastam em alguns pontos, mas se aproximam em outros na habilidosa análise do autor José Rosa dos Santos Júnior.', '["Manoel de Barros","autobiographical poetry","memory","multiplicity","metalinguage","creative process","Pantanal","Brazilian poetry"]', '10.7476/9786588211083', '9788578873486', 'https://books.scielo.org/id/qqjvh', 'https://books.scielo.org/id/qqjvh/pdf/santos-9786588211083.pdf', 'https://books.scielo.org/id/qqjvh/epub/santos-9786588211083.epub', 'https://books.scielo.org/id/qqjvh/cover/cover_thumbnail.jpeg', 293, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qqx82', 'qqx82', 'Agricultura, cooperativas e multinacionais', NULL, '["Odaci Luiz Coradini","Antoinette Fredericq"]', 'Centro Edelstein', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Abordando aspectos diferentes, os dois estudos focalizam mecanismos de interpenetração crescente entre o capital agroindustrial e os produtores rurais, as estratégias que os diversos agentes utilizam e o papel das cooperativas dentro desse complexo jogo de forças. [...] [trecho retirado da apresentação do livro]', '["agricultural cooperatives","multinational corporations","rural farmers","power relations"]', '10.7476/9788579820090', '9788579820090', 'https://books.scielo.org/id/qqx82', 'https://books.scielo.org/id/qqx82/pdf/coradini-9788579820090.pdf', NULL, 'https://books.scielo.org/id/qqx82/cover/cover_thumbnail.jpeg', NULL, 14, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qrbn3', 'qrbn3', 'A representação social na construção da velhice', NULL, '["Raimunda Silva D''Alencar"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Diante do rápido envelhecimento da população brasileira, o livro expõe alguns aspectos sobre a representatividade do idoso na sociedade. Para isso, diversos autores apresentam avanços e entraves que a população idosa enfrenta, como a representação da velhice em diferentes instâncias (universidade, família, trabalho), fronteiras e aproximações entre os distintos tipos de velhice, como ativa/saudável e institucionalizada/doente e outros assuntos pertinentes à terceira idade.', '["social representations","old age","population aging","older adults","active ageing","institutionalized elderly","healthy aging","family and work"]', '10.7476/9788574554860', '9788574554860', 'https://books.scielo.org/id/qrbn3', 'https://books.scielo.org/id/qrbn3/pdf/d-9788574554860.pdf', NULL, 'https://books.scielo.org/id/qrbn3/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qrdv5', 'qrdv5', 'Movimentos e lutas sociais pela terra no sul do Brasil: questões contemporâneas', NULL, '["João Carlos Tedesco","Jonas José Seminotti","Humberto José da Rocha"]', 'Editora UFFS', 'Brasil', 'SciELO Books', 'books', 2018, '2018-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A história dos movimentos e lutas sociais ganha novos atores, e novas demandas se configuram neste início de século XXI. O processo histórico que originou movimentos sociais de luta pela terra ainda contabiliza refluxos e conquistas que impõem desafios, criam esperanças e geram frustrações, mantendo esses movimentos sociais em constante atualização. Como forma de registro de parte desse processo, este livro contempla questões contemporâneas sob perspectivas de representações do mundo rural, conflitos pela terra e pautas e políticas para o campo, de forma a oferecer diferentes ângulos de discussão da questão rural na contemporaneidade e análises específicas relacionadas com contextos mais amplos que requerem análises multidisciplinares empreendidas de forma multiescalar. Eis o cenário de pesquisa vislumbrado nesta obra para o estudo do rural na contemporaneidade.', '["land struggle","social movements","southern Brazil","land disputes","rural policy","agrarian question","multiscalar analysis"]', '10.7476/9788564905764', '9788564905764', 'https://books.scielo.org/id/qrdv5', 'https://books.scielo.org/id/qrdv5/pdf/tedesco-9788564905764.pdf', NULL, 'https://books.scielo.org/id/qrdv5/cover/cover_thumbnail.jpeg', NULL, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qt8yq', 'qt8yq', 'Geografia(s) no plural: teorias, metodologias e práticas pedagógicas', 'teorias, metodologias e práticas pedagógicas', '["Trindade, Gilmar Alves","Rangel, Maria Cristina","Chiapetti, Rita Jaqueline Nogueira"]', 'Editus', 'Brasil', 'SciELO Books', 'books', 2025, '2025-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'O livro é uma coletânea com sete textos que exploram diferentes abordagens da Geografia, com ênfase em aspectos teóricos, metodológicos e pedagógicos. A obra propõe reflexões críticas sobre o ensino e a pesquisa na área, transitando entre teoria e prática em diversas escalas de análise. Voltado para estudantes, educadores e interessados em Geografia, a obra convida ao diálogo e à construção de olhares plurais sobre temas contemporâneos, contribuindo para uma compreensão mais ampla e atual da disciplina.', '["geography education","teaching practice","theory-practice integration","scale of analysis"]', '10.7476/9788574556499', '9788574555928', 'https://books.scielo.org/id/qt8yq', NULL, NULL, 'https://books.scielo.org/id/qt8yq/cover/cover_thumbnail.jpeg', 263, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qv9kk', 'qv9kk', 'Manual de sobrevivência para divulgar ciência e saúde', NULL, '["Catarina Chagas","Luisa Massarani"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, as autoras tem como objetivo sensibilizar pesquisadores e futuros pesquisadores (estudantes de pós-graduação e de graduação) sobre a importância de manter um diálogo com a sociedade acerca de temas de ciência, tecnologia e saúde e oferecem ferramentas práticas de como fazer ações de divulgação científica.', '["science communication","health communication","science outreach","public engagement with science","science and technology","graduate students","public understanding of science"]', '10.7476/9786557080870', '9786557080276', 'https://books.scielo.org/id/qv9kk', NULL, NULL, 'https://books.scielo.org/id/qv9kk/cover/cover_thumbnail.jpeg', 156, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qv9ns', 'qv9ns', 'O tempo em perspectivas', NULL, '["Adriano Silva"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O que afinal é o tempo e qual a sua utilidade para o conhecimento? Ele realmente existe ou representa um mero fruto da imaginação humana? São perguntas que sempre nutriram a nossa curiosidade desde eras remotas. Ao longo da história, os desdobramentos dos inúmeros estudos que vêm sendo realizados serviram para valorizar e perpetuar o rico debate sobre esse fascinante tema em diferentes campos do conhecimento. Qual seria a escala temporal dos fenômenos existentes nas dimensões atômica, molecular e celular? Como o reino animal percebe a passagem do tempo? E qual a importância do tempo na literatura, sociologia e filosofia? Há estudiosos cogitando a possibilidade de viajar no tempo, enquanto outros não acreditam na sua existência. Portanto, esta obra representa um esforço, ainda inédito em nosso idioma, para condensar visões distintas oriundas de algumas áreas que têm se ocupado em investigar o significado e a importância do tempo.', '["time","nature of time","time scales","time in literature","philosophy of time","time travel"]', '10.7476/9786558462750', '9786558460787', 'https://books.scielo.org/id/qv9ns', NULL, NULL, 'https://books.scielo.org/id/qv9ns/cover/cover_thumbnail.jpeg', 612, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qvgtr', 'qvgtr', 'Petróleo e poder: envolvimento militar dos Estados Unidos no Golfo Pérsico', NULL, '["Fuser Igor"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2008, '2008-01-01', 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', 'Energy', 'Neste livro, Igor Fuser analisa em profundidade o papel do petróleo na definição da política norte-americana para o Golfo Pérsico entre 1945 e 2003, com ênfase na relação entre o aumento da dependência dos Estados Unidos em relação aos combustíveis importados e seu crescente intervencionismo na região. O autor demonstra que, para entender os motivos da invasão do Iraque pelos Estados Unidos, é preciso ir muito além de temas como terrorismo, armas de destruição em massa e o suposto interesse norte-americano na promoção da democracia. A postura unilateral e belicosa adotada pelo presidente George W. Bush após os atentados de 11 de setembro, sem dúvida, ajuda a explicar a polêmica iniciativa militar. Ainda assim, a história da política dos Estados Unidos no Oriente Médio nos últimos sessenta anos revela uma notável continuidade entre a agressão militar ao Iraque e a conduta dos governos anteriores – republicanos ou democratas. Entre os objetivos permanentes que a maior potência do planeta persegue naquela região, destaca-se, em primeiro plano, o controle de suas imensas reservas de petróleo.', '["Persian Gulf","US foreign policy","oil and geopolitics","US military intervention","Iraq War","oil dependence","US interventionism","Middle East","George W. Bush","September 11 attacks","oil reserves"]', '10.7476/9788595461963', '9788571398191', 'https://books.scielo.org/id/qvgtr', NULL, NULL, 'https://books.scielo.org/id/qvgtr/cover/cover_thumbnail.jpeg', 254, 3, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qvpyx', 'qvpyx', 'La tradición política en la obra de Hannah Arendt', NULL, '["Mery Castillo C."]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2014, '2014-01-01', 'es', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Los temas que constituyen el conjunto de este libro tienen diferentes pretextos teóricos. El interés principal ha sido recabar en este escrito un conjunto de reflexiones articuladas sobre la idea del poder y el proceso de comprensión del pasado que aborda Arendt. Este no se desarrolla a través de un proceder sistemático –como no lo es tampoco el pensamiento arendtiano– ni por medio de argumentos que supongan premisas necesarias para alcanzar las conclusiones buscadas. Cada uno de los capítulos emularía más bien la pieza de un “rompecabezas” que, al articularse y combinarse con las demás, logra construir ese cuadro representado por la teoría arendtiana. Por ello, si bien cada uno de ellos puede leerse por separado, asimismo cada uno de ellos resulta necesario para completar el panorama buscado, es decir, la construcción integral del “rompecabezas” en los rubros del poder y la violencia.', '["Hannah Arendt","political tradition","violence","understanding the past","political philosophy"]', '10.7476/9789587384796', '9789587384789', 'https://books.scielo.org/id/qvpyx', NULL, NULL, 'https://books.scielo.org/id/qvpyx/cover/cover_thumbnail.jpeg', 82, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qvtd7', 'qvtd7', 'Cinema, circuitos culturais e espaços formativos: novas sociabilidades e ambiência na Bahia (1968-1978)', NULL, '["Izabel de Fátima Cruz Melo"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Este livro, fruto da pesquisa de doutoramento defendida em 2018, está filiado a uma compreensão de história do cinema na qual a atividade cinematográfica se desdobra e se espraia por diversos caminhos e atividades, além do próprio filme. Tratamos aqui, com uma abordagem até então inédita, das trajetórias do Clube de Cinema da Bahia (CCB), do Grupo Experimental de Cinema (GEC) e da Jornada de Cinema da Bahia entre os anos de 1968 e 1978, compreendendo-os como suportes essenciais para a constituição de uma cultura cinematográfica responsável por criar um espaço de formação de público, cineastas, críticos, produtores, gestores em Salvador.', '["film history","film festivals","film clubs","film education","film audiences","film criticism","film production","film management","sociability","ambience","Salvador, Bahia"]', '10.7476/9786588211564', '9786588211489', 'https://books.scielo.org/id/qvtd7', 'https://books.scielo.org/id/qvtd7/pdf/melo-9786588211564.pdf', 'https://books.scielo.org/id/qvtd7/epub/melo-9786588211564.epub', 'https://books.scielo.org/id/qvtd7/cover/cover_thumbnail.jpeg', 250, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qwb6r', 'qwb6r', 'A Escrita grega no Império Romano: recepção e transmissão', NULL, '["Baracat Jr., José C.","Silva, Maria Aparecida de Oliveira"]', 'Editora da UFRGS', 'Brasil', 'SciELO Books', 'books', 2020, '2020-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A língua grega não perdeu sua importância com a ascensão de Roma. Não apenas continuou a ser o principal idioma de expressão intelectual nas regiões conquistadas por Alexandre, o Grande, como também se inseriu no coração do mundo romano, onde não poucos a falavam e nela preferiram escrever suas obras. Atentos à importância da língua grega durante toda a Antiguidade, bem como à escassez no Brasil de estudos sobre autores que escreveram em grego durante o Império Romano, o primeiro objetivo desta coletânea é, assim, oferecer uma amostra da riqueza intelectual desse período através de estudos que não apenas escreveram em grego, mas também deram continuidade à tradição literária, filosófica e historiográfica grega. O arco temporal coberto pelos autores presentes neste livro vai do primeiro ao terceiro século da era cristã. São estudos que abordam Paulo de Tarso, Plutarco, Epiteto, Élio Aristides, Luciano de Samósata, Filóstrato, Bábrio, Apolodoro, Máximo de Tiro, Diógenes Láercio e Plotino.', '["Greek language","Roman Empire","reception of Greek literature","ancient Greek philosophy","Greek historiography","Greek literary tradition","Paul the Apostle","Plutarch","Epictetus","Lucian of Samosata","Philostratus","Apollodorus"]', '10.7476/9786557251218', '9786557251218', 'https://books.scielo.org/id/qwb6r', 'https://books.scielo.org/id/qwb6r/pdf/baracat-9786557251218.pdf', NULL, 'https://books.scielo.org/id/qwb6r/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qwp85', 'qwp85', 'Georges Snyders: por uma pedagogia da alegria e do antipreconceito: subsídios para a formação de professores', NULL, '["Renata de Almeida Vieira"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2016, '2016-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Quem foi Georges Snyders? Qual o seu legado para o campo educacional brasileiro na atualidade? Por que o tema alegria amplamente divulgado em suas obras pedagógicas ainda nos toca e nos desafia? Aliás, o que é, de fato, alegria na perspectiva snyderiana? De que modo este tema está relacionado ao antipreconceito? Afinal, poderá a pedagogia da alegria nos inspirar na condução de um ensino do antipreconceito? Estas questões são orientadoras para conduzir a discussão na obra Georges Snyders – por uma pedagogia da alegria e do antipreconceito: subsídios para a formação de professores.', '["teacher professional development","Brazilian education"]', '10.7476/9788576286950', '9788576286493', 'https://books.scielo.org/id/qwp85', NULL, NULL, 'https://books.scielo.org/id/qwp85/cover/cover_thumbnail.jpeg', 214, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qx8r5', 'qx8r5', 'As chuvas e as massas de ar no estado de Mato Grosso do Sul: estudo geográfico com vista à regionalização climática', NULL, '["João Afonso Zavattini"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2009, '2009-01-01', 'pt', 'book', 'natural-sciences', 'Ciencias Naturales y Exactas', 'Environmental Science', 'Obra climatológica que oferece tratamento dinâmico às questões climáticas do Mato Grosso do Sul, principalmente à circulação atmosférica regional e às implicações pluviais. Considerando-se que tal região, a exemplo do que ocorre com o território paulista, encontra-se na confluência dos principais sistemas atmosféricos da América do Sul, possuindo mais de um tipo de regime pluviométrico (áreas com regime do tipo Brasil Central e outras com regime do tipo Brasil Meridional), o autor deste livro procura compreender a relevância de estudos que privilegiam a distribuição das chuvas como um dos indicadores do seu mosaico climático. Para tanto descreve as chuvas anuais, sazonais e mensais do período de 1966 a 1985 e, depois, as chuvas diárias do triênio 1983-1985, analisando-as do ponto de vista rítmico. Trata-se de um estudo original, uma vez que se fundamenta na dinâmica das massas de ar, isto é, das cadeias fundamentais dos tipos de tempo, dos mecanismos frontológicos e dos ritmos pluviais, metodologia que possibilitou não apenas entrever as relações atmosfera-território sulmatogrossense como, também, propor uma classificação climática de base genética, ainda que sob a forma de tentativa', '["rainfall","air masses","climatic regionalization","Mato Grosso do Sul","atmospheric circulation","frontogenesis","precipitation regime","climate classification","seasonal rainfall"]', '10.7476/9788579830020', '9788579830020', 'https://books.scielo.org/id/qx8r5', 'https://books.scielo.org/id/qx8r5/pdf/zavattini-9788579830020.pdf', NULL, 'https://books.scielo.org/id/qx8r5/cover/cover_thumbnail.jpeg', NULL, 30, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qxhc3', 'qxhc3', 'Reviravolta na saúde origem e articulação do movimento sanitário', NULL, '["Sarah Escorel"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 1999, '1999-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Um ''movimento de pessoas'' lutando por mudanças na maneira de olhar o paciente, a medicina e a política no setor. Uma verdadeira Reviravolta na Saúde, começada no movimento estudantil, no interior de movimentos médicos e na própria academia. Sarah Escorel detalha o início do movimento sanitário no Brasil, a partir do governo Figueiredo. Para isso, utilizou não somente documentos, mas depoimentos. É a história contada pelos próprios atores.', '["health movement","health policy","medical profession","student movement","Fernando Collor government","health politics"]', '10.7476/9788575413616', '9788575413616', 'https://books.scielo.org/id/qxhc3', 'https://books.scielo.org/id/qxhc3/pdf/escorel-9788575413616.pdf', NULL, 'https://books.scielo.org/id/qxhc3/cover/cover_thumbnail.jpeg', NULL, 161, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qxsht', 'qxsht', 'Émile Benveniste: a gênese de um pensamento', NULL, '["Irène Fénoglio"]', 'Editora Universidade de Brasília', 'Brasil', 'SciELO Books', 'books', 2019, '2019-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'A definição comum de gênese, quando aplicada à ideia de pensamento, geralmente leva a crer que se busca explicar o desenvolvimento gradual desse pensamento. A gênese do pensamento de Benveniste que se delineia neste livro, embora não esteja em posição antagônica a essa, não poderia ser suficientemente compreendida se não se considerasse, também, que a autora do livro esforça-se para traçar a história do nascimento de uma obra, a partir de traços – manuscritos – antes desconhecidos do público. O livro reúne seis estudos de Irène Fenoglio sobre o acervo de manuscritos do linguista Émile Benveniste. Trata-se de um conjunto de trabalhos que, com base na crítica genética, busca recompor a gênese do pensamento de um dos linguistas mais importantes do século XX. O celebrado linguista recebe, assim, uma justa homenagem feita por uma especialista que não desconhece que a escrita diz muito de quem escreve, sem dúvida, mas também de quem a lê. A autora é, hoje em dia, uma das principais especialistas na obra de Benveniste. Recentemente, organizou, com Jean-Claude Coquet, a edição das últimas aulas de Benveniste no Collège de France, trabalho fruto de cuidadosa recuperação feita a partir de fontes manuscritas do linguista e de seus alunos à época. Os textos que integram esta coletânea retomam as últimas aulas de Benveniste e acrescentam informações nunca antes divulgadas em torno da obra do autor.', '["Émile Benveniste","genesis of thought","intellectual development","unpublished manuscripts"]', '10.7476/9788523013431', '9788523009564', 'https://books.scielo.org/id/qxsht', NULL, NULL, 'https://books.scielo.org/id/qxsht/cover/cover_thumbnail.jpeg', 306, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qycmp', 'qycmp', 'Que controle social? Os conselhos de saúde como instrumento', NULL, '["Maria Valéria Costa Correia"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2000, '2000-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'PrefácioPode-se sentir, diariamente, a importância de se discutir controle social, ao acompanharmos as denúncias pela imprensa dos desvios, corrupção e apropriações indevidas do dinheiro público, do fisiologismo e clientelismo com a máquina estatal presentes nos três poderes das unidades federativas.Maria Valéria Costa Correia aborda este tema, enfocando a necessidade do controle social sobre os recursos públicos, elegendo, como categoria de estudo, o fundo público.Assim, inicia o livro apresentando o panorama do fundo público nos países desenvolvidos e no Brasil desde a crise do Welfare State até a década de 90, mostrando a preocupante tendência da sua utilização para o financiamento da reprodução do capital em detrimento do financiamento da reprodução da força de trabalho.Neste debate, insere a (des)constituição da esfera pública, das políticas públicas e da democracia.O recorte específico na política de saúde é dado no segundo capítulo, em que se acompanha o percurso do fundo público da saúde no rastro da previdência social e, a partir de 1988, no rastro da seguridade social.A história do controle social na saúde emergindo da relação Estado/ sociedade é descrita no terceiro capítulo, em que analisa o respaldo legal deste controle sobre o fundo público da saúde na Lei 8.142/90, sua legitimação nas Conferências Nacionais de Saúde e nas Normas Operacionais Básicas do SUS.No quarto capítulo, Valéria mostra um estudo de caso em que articula os conceitos trabalhados nos capítulos anteriores com a realidade do conselho de saúde de um município brasileiro, apresentando os avanços e os limites do controle social sobre o Fundo Municipal de Saúde.Este livro possibilita a todos uma compreensão, para além do aparente, do rumo perigoso que muitas vezes tem tomado a política de saúde brasileira.Mas vai além, mostrando que o caminho da superação desses desvios passa pela efetivação do controle social.Nesta perspectiva de análise dos limites da função do fundo público no capitalismo, Marcelo Ridenti (1994) considera a proposta formulada por José Giannoti (1983), de autogestão dos trabalhadores -em que estes tenham uma representação dentro e fora do Estado, com o fim de controlar o fundo público, subvertendo o fundamento material do Estado e do capitalismo contemporâneo -, como uma formulação que tem parentesco com as tradições da social-democracia européia, na qual o socialismo poderia ser alcançado pelo controle gradativo sobre o tesouro do Estado.No entanto, Ridenti concorda com Giannoti no destaque dado ao papel central do fundo público no capitalismo de hoje "com implicações na constituição e nas lutas de classes" (Ridenti, 1984:103).Faz, porém, uma crítica ao fato de Giannoti apresentar tal ideal -a democratização da gestão e da aplicação do fundo público -como mais viável do que os projetos marxistaleninista e anarquista.E situa esse ideal dentro do limite da social-democracia, que "tem se revelado incapaz de contrapor-se ao capitalismo contemporâneo, de ser uma alternativa à barbárie do presente, constituindo-se no máximo em resistência setorial a ela, senão mesmo em gestor do capitalismo" (Ridenti, 1994:104).Entretanto, Ridenti não nega a importância das lutas pela democratização do fundo público em uma sociedade como a brasileira, "na qual os direitos à cidadania são recusados à maior parte da população", pois, nesta realidade, "chega mesmo a ser subversiva a luta pela construção de uma esfera pública" (Ridenti, 1994:107).Isso porque se assiste à tendência à utilização do fundo público para atender aos interesses privativistas e clientelistas expressos no financiamento da acumulação de capital e nos escândalos de corrupção relacionados a desvio de verbas nos orçamentos públicos.A democratização do fundo público, que implica a interferência da sociedade organizada na destinação do gasto público, abala, de certa forma, o monopólio das classes dominantes sobre os recursos que, sendo públicos, deveriam ser gastos, cada vez mais, com bens e serviços coletivos.Destaca-se a importância de a sociedade criar espaços democráticos para interferir ou mesmo controlar as ações do Estado e o gasto público, para que este não se restrinja aos interesses clientelistas e privatizantes da classe dominante.O fundo público deve se voltar para finalidades sociais, estruturando e ampliando a esfera pública brasileira, ou seja, deve ser utilizado na educação, saúde, transporte, habitação popular, ou seja, em bens de consumo coletivo que não buscam o lucro.É nessa perspectiva que se aborda aqui o controle social, ou seja, o controle da sociedade sobre as ações do Estado e, conseqüentemente, sobre o gasto público.* Medicamento é um subitem da despesa com material de consumo; seus valores estão, portanto, incluídos no item ''Material de consumo''.** Neste total estão incluídos o saldo das contas do SIA/SUS (R$ 30,44) e da folha de pagamento dos funcionários (R$ 43,08), que somam R$ 73,52.', '["social control","health councils","public fund","health policy","social security","welfare state crisis","National Health Conference","state-society relations","public sphere","democracy","health care financing","capital reproduction"]', '10.7476/9788575415221', '9788575415221', 'https://books.scielo.org/id/qycmp', 'https://books.scielo.org/id/qycmp/pdf/correia-9788575415221.pdf', NULL, 'https://books.scielo.org/id/qycmp/cover/cover_thumbnail.jpeg', NULL, 47, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qyhcv', 'qyhcv', 'Poesia bucólica: Virgílio, Calpúrnio Sículo, Nemesiano', NULL, '["Alessandro Rolim de Moura"]', 'Editora da Unicamp', 'Brasil', 'SciELO Books', 'books', 2022, '2022-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Poesia bucólica discute as bases desse subgênero literário na Antiguidade greco-romana e apresenta e interpreta seus principais textos, com destaque para os de poetas latinos, mormente Virgílio, autor das Bucólicas ou Éclogas, obra que é objeto de abordagem detalhada, quase verso a verso. O trabalho começa com uma investigação sobre as origens da poesia bucólica na literatura grega, contexto em que Teócrito é o nome de maior relevância. O livro inclui uma análise da tradição crítica referente à bucólica, esclarecendo questões de nomenclatura, definição ou recepção (da noção de Arcádia , por exemplo) e sublinhando as contribuições da retórica e da poética antigas. Poetas menos conhecidos, como Calpúrnio Sículo e Nemesiano, são objeto de discussão que valoriza sua originalidade. Traduções apoiam a análise crítica e comparecem também na breve antologia do final do volume.', '["pastoral poetry","Latin poetry","Virgil","Eclogues","Calpurnius Siculus","Nemesianus","Theocritus","Greek bucolic poetry","Arcadia","classical rhetoric","ancient poetics"]', '10.7476/9788526816695', '9788526815575', 'https://books.scielo.org/id/qyhcv', NULL, NULL, 'https://books.scielo.org/id/qyhcv/cover/cover_thumbnail.jpeg', 567, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qzvpx', 'qzvpx', 'Infinitude subjetiva e estética: natureza e arte em Schelling e Schopenhauer', NULL, '["Jair Barboza"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2005, '2005-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'O diferencial desta obra é o estabelecimento, pelo autor, de um confronto direto entre Schelling e Schopenhauer, utilizando-se basicamente dos escritos deste último, a partir de material inédito do Schopenhauer-Archiv de Frankfurt. Apresenta um viés interpretativo que acrescenta Schelling e Fichte à linha Platão-Kant-Schopenhauer, preenchendo uma lacuna de consideráveis implicações. Demonstra como os filósofos Schelling e Schopenhauer chegam à mesma resposta da experiência estética da beleza e de sua íntima ligação com a natureza exterior a nós que o supra-sensível pode ser atingido e têm a mesma reação à negatividade crítica kantiana relacionada ao mundo inteligível, em oposição ao sensível, e como o sistema teórico de um autor ilumina o outro. O autor também chama a atenção para a presença de conceitos como vontade e intuição intelectual nos escritos schellinguianos, já em 1795, o que permite compreender um contexto cultural e filosófico no qual o idealismo transcendental kantiano é retrabalhado.', '["Friedrich Schelling","Arthur Schopenhauer","aesthetic experience","beauty","art and nature","Kantian critique","intelligible world","wills","intellectual intuition","transcendental idealism"]', '10.7476/9788539303182', '9788571395923', 'https://books.scielo.org/id/qzvpx', NULL, NULL, 'https://books.scielo.org/id/qzvpx/cover/cover_thumbnail.jpeg', 320, 8, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qzy6v', 'qzy6v', 'Entre a teoria e a história: a política comercial dos Estados Unidos na década de 1980', NULL, '["Filipe Almeida do Prado Mendonça"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2011, '2011-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'Neste livro, Filipe Mendonça faz uma análise da política comer­cial norte-americana dos anos 1980, mas nos oferece uma visão abrangente. Trata-se de análise especializada, com amplo olhar sobre questões fundamentais para a compreensão daquela política. Por isso o peso que tem a política externa e internacional, sempre focando nas relações dos âmbitos doméstico e internacional. O autor busca, ao longo do trabalho, demonstrar as motivações principais das mudanças na política norte-americana, muito forte­mente marcadas pelo Omnibus and Trade Competitiveness Act de 1988, que marca a definitiva implementação do fair trade, interna­cionalmente conhecido pela revitalização do sistema de sanções pelas Super 301 e Special 301. Trabalho ganhador do disputado Prêmio Franklin Delano Roose-velt de Estudos sobre os Estados Unidos da América 2011, atribuí­do pela embaixada dos Estados Unidos em Brasília.', '["United States trade policy","1980s","fair trade","trade sanctions","US foreign policy","trade policy theory"]', '10.7476/9786557145265', '9786557145265', 'https://books.scielo.org/id/qzy6v', 'https://books.scielo.org/id/qzy6v/pdf/mendon%C3%A7a-9786557145265.pdf', NULL, 'https://books.scielo.org/id/qzy6v/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-qzyh6', 'qzyh6', 'Capitalismo, trabalho e formação profissional: dilemas do trabalho cotidiano dos assistentes sociais em Ribeirão Preto', NULL, '["Élidi Cristina Tinti"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2015, '2015-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Neste livro, a autora tem a coragem de lidar com um velho e novo dilema que perpassa o Serviço Social brasileiro: Como os assistentes sociais conduzem seu trabalho cotidiano? A partir de qual referencial teórico-metodológico, ético-político e técnico-operativo? Para enfrentar essas questões, a autora reivindica uma perspectiva de totalidade, a qual leva-a a se debruçar sobre as condições objetivas que incidem no trabalho profissional dos assistentes sociais, na sua formação profissional e nas respostas que oferecem no dia a dia do seu trabalho. A pesquisadora analisa como o assistente social, enquanto trabalhador assalariado, realiza seu trabalho sob determinadas condições. Para isso, considera a forma como esse trabalho se configura a partir do modo de produção capitalista (alienado, reificado), mas elucida também como os profissionais de Serviço Social, enquanto seres sociais dotados de uma teleologia, de aportes teórico-metodológicos, ético-políticos que os alicerçam (os quais deveriam ser garantidos na formação profissional), podem exercer a sua autonomia enquanto profissionais e propor um trabalho inventivo, criativo, diante das velhas e novas manifestações da questão social brasileira. A autora problematiza, ainda, a formação econômico-social contemporânea e seus rebatimentos na formação e no trabalho do assistente social brasileiro, considerando a imbricação subjacente entre esses elementos.', '["social workers","social work practice","professional training","capitalism","alienation","reification","working conditions","professional autonomy","social question","Brazilian social work","everyday work","Ribeirão Preto"]', '10.7476/9788579836558', '9788579836558', 'https://books.scielo.org/id/qzyh6', 'https://books.scielo.org/id/qzyh6/pdf/tinti-9788579836558.pdf', NULL, 'https://books.scielo.org/id/qzyh6/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r2w8m', 'r2w8m', 'Escutas do indizível: a urgência subjetiva dos universitários', 'a urgência subjetiva dos universitários', '["Marcelo Veras","Luiz Felipe Monteiro","Rogério Paes Henriques"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2024, '2024-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'O crescimento vertiginoso de casos de tentativas de suicídio vem, há um tempo, assustando a comunidade acadêmica. A mobilização para entender e atuar nesse cenário constatou, a priori, que a universidade é um microcosmos complexo que reproduz disputas de poder, com inevitáveis tensões e conflitos – muitas vezes, o resultado é intenso sofrimento psíquico. Nesse cenário, o Programa de Saúde Mental e Bem-Estar (PsiU) da UFBA surge para afinar os ouvidos e dar outro destino a esse sofrimento. O livro é um retrato abrangente dessa experiência-modelo, com textos teóricos até conversações clínicas e relatos de caso. A rede criada por Marcelo Veras na UFBA é um modelo para todas as universidades que enfrentam desafios semelhantes de como despertar do pesadelo e voltar a sonhar.', '["university students","suicide attempts","mental health","psychological suffering","listening","clinical interview","Universidade Federal da Bahia"]', '10.7476/9786556308951', '9786556306087', 'https://books.scielo.org/id/r2w8m', NULL, NULL, 'https://books.scielo.org/id/r2w8m/cover/cover_thumbnail.jpeg', 384, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r3dbw', 'r3dbw', 'Racismo linguístico e os indígenas Gavião na universidade: língua como linha de força do dispositivo colonial', 'língua como linha de força do dispositivo colonial', '["Flávia Marinho Lisbôa"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'A obra reflete sobre a diversidade de sujeitos que têm conquistado acesso na universidade pública brasileira nos últimos anos e o papel da língua como uma potente linha de força da colonialidade. A autora descreve as linhas de subjetividade e força do dispositivo colonial que atravessam as dificuldades materiais, socioculturais, pedagógicas e epistemológicas para permanência desses discentes. Tal descrição ultrapassa o âmbito acadêmico e envolve a crítica à histórica exclusão racial dos povos originários no Brasil, tomando a língua como objeto que ajuda a explicar o pensamento e as relações sociais brasileiras.', '["linguistic racism","Indigenous students","higher education access","coloniality","power of words","racial exclusion","indigenous languages","subjectivity","indigenous peoples of Brazil"]', '10.7476/9786556308791', '9786556305486', 'https://books.scielo.org/id/r3dbw', 'https://books.scielo.org/id/r3dbw/pdf/lisboa-9786556308791.pdf', NULL, 'https://books.scielo.org/id/r3dbw/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r3hc2', 'r3hc2', 'Os impactos sociais da Covid-19 no Brasil: populações vulnerabilizadas e respostas à pandemia', NULL, '["Gustavo Corrêa Matta","Rego, Sergio","Souto, Ester Paiva","Segata, Jean"]', 'Série Informação para ação na Covid-19 | Fiocruz', 'Brasil', 'SciELO Books', 'books', 2021, '2021-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Passados os primeiros meses da pandemia do novo coronavírus no Brasil, o Observatório Covid-19 Fiocruz, em parceria com a Editora Fiocruz e com o apoio da Rede SciELO Livros, traz para o público leitor um conjunto de livros instantâneos sobre as análises nele realizadas desde que foi criado para subsidiar o seu combate. Nesta série Informação para Ação na Covid-19 será apresentado um balanço do conjunto de documentos (notas e relatórios técnicos, boletins, ensaios, informes, recomendações, ensaios, artigos, entre outros) produzidos em resposta à pandemia. Cada volume da série se estrutura em torno de um tema: aspectos globais da pandemia e da diplomacia em saúde; cenários epidemiológicos e vigilância em saúde; as políticas e a gestão dos serviços e sistemas de saúde; orientações para os cuidados e a saúde dos trabalhadores da saúde; impactos sociais e desigualdades sociais na pandemia. Com a publicação destes estudos em livros instantâneos e de acesso aberto colocamos à disposição do público o conjunto de informações e conhecimentos gerados no âmbito do Observatório Covid-19 Fiocruz, realizamos um balanço e uma reflexão sobre como chegamos ao cenário atual e apontamos caminhos para um futuro próximo. E, ao mesmo tempo, mantemos o registro histórico desse conhecimento produzido a quente, no calor da hora.', '["COVID-19 pandemic","social impact","vulnerable populations","social inequality","pandemic response","health diplomacy","epidemiological scenarios","health surveillance","health policy","health services administration","Brazil"]', '10.7476/9786557080320', '9786557080320', 'https://books.scielo.org/id/r3hc2', 'https://books.scielo.org/id/r3hc2/pdf/matta-9786557080320.pdf', NULL, 'https://books.scielo.org/id/r3hc2/cover/cover_thumbnail.jpeg', NULL, 156, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r3jp8', 'r3jp8', 'Economia, poder e influência externa: o Banco Mundial e os anos de ajuste na América Latina', NULL, '["Jaime César Coelho"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2012, '2012-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro analisa o papel do Grupo Banco Mundial no período das grandes reformas neoliberais na América Latina, durante os anos 1980 e 1990. Nessa perspectiva, destacam-se os programas de ajustamento estrutural e a questão da influência externa sobre a tomada de decisão no plano doméstico, fator fundamental para o entendimento das transformações pelas quais passou a região. Assim, pode-se observar como as grandes potências manobraram as instituições internacionais em função de seus intereses e examinar a questão do poder no âmbito internacional, a partir de uma abordagem que reúne contribuições teóricas da economia, da história, da sociologia e da ciência política.', '["World Bank","structural adjustment programs","neoliberal reforms","external influence","international institutions","power in international relations","Latin America","1980s-1990s","economic policy-making"]', '10.7476/9788595461956', '9788539302550', 'https://books.scielo.org/id/r3jp8', NULL, NULL, 'https://books.scielo.org/id/r3jp8/cover/cover_thumbnail.jpeg', 296, 4, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r3wvb', 'r3wvb', 'Justicia para los vasallos de su majestad. Administración de justicia en la villa de San Gil, siglo XVIII', NULL, '["Julián Andrei Velasco Pedraza"]', 'Editorial Universidad del Rosario', 'Colombia', 'SciELO Books', 'books', 2015, '2015-01-01', 'es', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Para la monarquía hispánica gobernar era hacer justicia. Bajo este fundamento, la corona de Castilla construyó todo un complejo aparato de tribunales en sus dominios americanos. Esta obra analiza una parte de ese gobierno por medio de la administración de justicia de la villa de San Gil en el siglo XVIII. Desde una perspectiva histórico-jurídica, fundamentada en nuevas visiones sobre el derecho y las instituciones, se estudia cómo en un ámbito local funcionaban y se adaptaban criterios culturales y principios jurídicos generales de la tradición jurídica de Occidente. Mediante el estudio de las condiciones locales, las jurisdicciones y jueces que las ejercían, así como de otros elementos del gobierno, se traza un panorama de la lógica de funcionamiento de una parte de la monarquía. Un tema poco estudiado para el virreinato de Santa Fe y que puede ayudar al mejor entendimiento de las lógicas político-administrativas del siglo XVIII, además de comprender, de forma menos anacrónica, las fuentes judiciales que eran producto de una cultura jurídica distinta a la de nuestros días.', '["judicial administration","San Gil","colonial courts","Spanish monarchy","colonial administration","judicial institutions","judges","legal history","18th century","legal culture","Crown of Castile","local government"]', '10.7476/9789587386547', '9789587386530', 'https://books.scielo.org/id/r3wvb', NULL, NULL, 'https://books.scielo.org/id/r3wvb/cover/cover_thumbnail.jpeg', 276, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r3xgc', 'r3xgc', 'Whatsapp e educação: entre mensagens, imagens e sons', NULL, '["Porto, Cristiane","Oliveira, Kaio Eduardo","Alexandre Meneses Chagas"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Na Cibercultura uma boa parte dos indivíduos usam as tecnologias digitais e os aplicativos para encontrar a informação ou para explorar os seus centros de interesses que vão além do que eles têm acesso na escola ou o que eles encontram em sua comunidade local. O aplicativo WhatsApp, assim, ganhou popularidade incontestável, principalmente entre os mais jovens. Esse livro que tem no aplicativo seu objeto de estudo como espaço de formação, ensino e aprendizagem. Os capítulos que o compõem apresentam experiências de pesquisadores, propostas de ensino e aprendizagem, e outras formas de ensinar e aprender que tem o WhatsApp como mediador do processo.', '["WhatsApp","social media in education","online learning","mobile learning","youth","teaching-learning process","learning mediation","digital culture"]', '10.7476/9788523220204', '9788523220204', 'https://books.scielo.org/id/r3xgc', 'https://books.scielo.org/id/r3xgc/pdf/porto-9788523220204.pdf', NULL, 'https://books.scielo.org/id/r3xgc/cover/cover_thumbnail.jpeg', NULL, 10, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r48n5', 'r48n5', 'Retalhos de experiências modernas: história, culturas e cidades no interior paulista – Primeira República', NULL, '["Humberto Perinelli Neto"]', 'Editora UNESP', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Este livro reúne textos dedicados a compreender experiências sociais provocadas pela modernização levada pela economia cafeeira às cidades do interior paulista, durante a Primeira República. Os textos conectam-se ao trabalho de José Evaldo de Melo Doin, docente que orientou os autores por mais de duas décadas na Faculdade de Ciências Sociais e Humanas da Universidade Estadual Paulista (Unesp), campus de Franca. Melo Doin dedicou-se ao estudo da construção histórica da contemporaneidade, por meio de análises do intricado diálogo entre História, Economia, Ciência Política, Arquitetura e Urbanismo. Nesta obra, fontes diversas – almanaques, fotos, crônicas, jornais, memórias, álbuns, entre outros – são interpretadas para compreender as vivências urbanas construídas com a chegada de tecnologias e hábitos novos, ao mesmo tempo em que traços de antiga sociabilidade e certos limites materiais e técnicos continuam preservados. Assim, Ribeirão Preto, Barretos, Mococa, São Carlos, Rio Claro, Batatais, Santa Bárbara D’Oeste e Franca revelam paisagens e cotidianos dotados de tensões, particularidades, permanências e possibilidades.', '["First Brazilian Republic","coffee economy","modernization","urban history","São Paulo interior","social history","urban everyday life","urban landscape","sociability","Ribeirão Preto","Barretos","São Carlos, São Paulo"]', '10.7476/9788595461758', '9788595461758', 'https://books.scielo.org/id/r48n5', 'https://books.scielo.org/id/r48n5/pdf/perinelli-9788595461758.pdf', NULL, 'https://books.scielo.org/id/r48n5/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r48s2', 'r48s2', 'Migrações e identidades: várias óticas e perspectivas', NULL, '["Maria Luiza Ramos Vieira Santos","Clodoaldo Silva da Anunciação","Vanessa Ribeiro Simon Cavalcanti"]', 'EDITUS', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Social Sciences', 'Em agosto do ano de 2015, realizamos o I SIMI -Seminário Internacional Migrações e Identidades na cidade de Salvador, na Bahia/Brasil.O evento teve como objetivo viabilizar e socializar a discussão sobre os temas por meio de diversas esferas, como universidades públicas, faculdades privadas, organizações não governamentais, Estado, órgãos de governo, Ministério Público e Sociedade Civil.Contou com a participação de palestrantes das diversas áreas, mas com um interesse comum: o estudo das Migrações e da Identidade.Esses assuntos se fazem presentes em várias ciências, na realidade social e nos meios de comunicação.Discutir os temas das Migrações e Identidades pressupõe a necessidade de investigações e contextualização no tempo e no espaço de dois fenômenos que, apesar de independentes, estão imbricados, tanto nas discussões das sociedades contemporâneas como nas sociedades antigas, tanto numa ambiência local como global.São vários matizes a serem analisados que perpassam por conceitos como hibridismo, xenofobia, etnocentrismo, preconceito, cultura, fundamentalismo, turismo, refúgio..., trazendo à tona discussões ricas que entrelaçam História, Estatística, Geografi a, Sociologia, Direito, Psicologia, Antropologia, Ciência Política, Biologia, fazendo com que coloquemos em contato autores e teorias dos diversos segmentos, criando, assim, discussões ricas para as áreas acadêmicas e sociais.Do I SIMI, alguns artigos apresentados foram objeto da primeira produção do evento.São nove apresentações que, traduzidas em ensaios, discutem os temas que poderão servir como registro e fontes de pesquisa para os iniciantes no percurso da investigação.A seguir, listamos os textos contidos nesse material, ressaltando que eles não se esgotam na sua produção e serão, como boas produções de pesquisa, objeto de discussões juntamente com as demais produções que pretendemos organizar e sistematizar para o aprofundamento nos temas. Parte 1 -MIGRAÇÃO E GÊNEROOs professores Vanessa Cavalcanti e Antonio Carlos da Silva trazem o artigo "Histórias e geografi as sem fronteiras?Migrações, gênero e (in)tolerâncias entre Brasil, Portugal e Espanha", nele fazem uma análise sobre o papel da imprensa nacional e internacional na divulgação sobre migrações de mulheres baianas para a Espanha, especialmente levando em consideração as políticas públicas, diretrizes de agências internacionais e programas de organismos não governamentais.Rilton Gonçalo Bonfi m Primo apresenta o artigo "Gênero e migrações forçadas na América Latina e no Caribe: marcos de transição da agenda de pesquisa em torno de 2014".O texto trata das migrações forçadas, situações de refúgio, reassentamento e o pouco aproveitamento dos debates diante de indícios de correlação positiva entre desterros e variáveis de gênero.Mary Garcia Castro apresenta seu artigo "Juventudes e migrações internacionais.Crítica de narrativas políticas por lições de gênero", nele combina os conceitos de juventude, gênero e migração discutindo as políticas sobre migrações e para a juventude, ressaltando a representação com que os jovens aparecem em textos da ONU -Organização das Nações Unidas. Parte 2 -MIGRAÇÃO, CULTURA E DIREITOS HUMANOSNatália Medina Araújo apresenta o trabalho "Direitos Humanos dos migrantes indocumentados: entre a teoria e a prática", que discute a universalidade desses direitos na teoria e sua realidade na prática, observando a carência na fi scalização dos sistemas de proteção aos direitos humanos e a sua seletividade.As professoras Gina Marcilio Pompeu e Ana Carla Pinheiro Freitas apresentam o trabalho intitulado "O Direito Humano à migração e ao refúgio: o Direito Humano do Outro", que traz a trajetória sobre a história dos Direitos Humanos e suas relações com uma abordagem psicanalítica, a ideia do conceito de não lugar e a legalização do direito do outro.Maria Luiza Silva Santos discorre sobre a "tradução" de pesquisas científi cas nas áreas de migrações e identidade no contexto da literatura, dando ênfase a quatro obras: dois livros resultantes de trabalhos acadêmicos e dois infantojuvenis, todos de sua autoria, na perspectiva de aproximar conceitos e cotidiano, cultura e formação. Parte 3 -MIGRAÇÃO E ESTADOPhilippe Hubert Gidon analisa em seu artigo "O impacto das migrações nas Relações Internacionais no século XXI" o desafi o que o fenômeno migratório representa para a disciplina das relações internacionais no século XXI, evidenciando as grades teóricas de leitura e análise das ocorrências em nível mundial, remetendo-se ao surgimento do Estado-nação no contexto de convivência competitiva.Rosa Júlia Plá Coelho analisa em seu trabalho "A construção de Estados Plurinacionais: há coexistência possível entre a universalidade e os particularismos?" os desafi os do migrante no seu destino, suas novas oportunidades e sua participação social.O confronto com o desafi o de se estabelecer, refazer vidas e integrar seus valores no novo contexto calcado na assimilação e no multiculturalismo.', '["migration","identity","gender","hybridity","xenophobia","ethnocentrism","prejudice","culture","fundamentalism","tourism","refugees","gender and migration"]', '10.7476/9788574554921', '9788574554921', 'https://books.scielo.org/id/r48s2', 'https://books.scielo.org/id/r48s2/pdf/santos-9788574554921.pdf', NULL, 'https://books.scielo.org/id/r48s2/cover/cover_thumbnail.jpeg', NULL, 1, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r4gyk', 'r4gyk', 'Uma História Global e Brasileira da Aids, 1986-2021', NULL, '["Marcos Cueto","Gabriel Lopes"]', 'Editora FIOCRUZ', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'humanities', 'Humanidades y Artes', 'Arts and Humanities', 'Em Uma História Global e Brasileira da Aids, 1986-2021, Marcos Cueto e Gabriel Lopes oferecem aos seus leitores uma espécie de aula magistral sobre como escrever a história da saúde coletiva na era global. Eles capturam a natureza interativa do sistema global contemporâneo, que certamente é caracterizado por muitas formas de desigualdade combinadas em configurações frequentemente neocoloniais. Eles também nos mostram que existe espaço para trocas bidirecionais e, mesmo no contexto da hegemonia neocolonial, é possível validar perspectivas alternativas de forma importante. Eles demonstram claramente que o tempo da análise histórica atrelada somente a unidades delimitadas, sejam comunidades locais sejam Estados-nação específicos, passou. A história da saúde e da medicina, na era da saúde global, só pode ser adequadamente compreendida com a devida atenção à complexidade das interações e interseções globais. Se os desenvolvimentos históricos locais e nacionais são profundamente impactados por processos e estruturas transnacionais, a saúde global também é influenciada e moldada por desenvolvimentos que ocorrem nacional e localmente; poucos estudos de caso estendidos ilustram isso tão claramente quanto esta história da resposta à aids no Brasil e das contribuições do Brasil para a resposta à aids no mundo.', '["AIDS","HIV/AIDS history","global health","history of public health","global health inequities","neocolonialism"]', '10.7476/9786557082188', '9786557081839', 'https://books.scielo.org/id/r4gyk', NULL, NULL, 'https://books.scielo.org/id/r4gyk/cover/cover_thumbnail.jpeg', 174, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r4s9v', 'r4s9v', 'Altas habilidades/superdotação: temas para pesquisa e discussão', NULL, '["Rosemeire de Araújo Rangni","Mayra Berto Massuda","Maria da Piedade Resende da Costa"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2017, '2017-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', '[RETIRADO/WITHDRAWN] Esta coletânea apresenta capítulos os quais são frutos de temas apresentados no 1º Seminário de Altas habilidades: disseminando conhecimentos e práticas ocorrido na Universidade Federal de São Carlos no ano de 2016. Os temas abordados versam sobre atendimento escolar nacional e internacional (Chile), dupla excepcionalidade, precocidade infantil, relato familiar e pesquisa. Entendemos que os capítulos selecionados para esta obra são interessantes para pais, professores e pesquisadores tendo em vista a escassez de literatura especializada da área ainda verificada no Brasil. Esperamos, sobretudo, contribuir para o conhecimento dos leitores.', '["giftedness","high abilities","superdotation","school support for gifted students","dual exceptionality","family narratives","giftedness research"]', '10.7476/9786580216109', '9786580216109', 'https://books.scielo.org/id/r4s9v', NULL, NULL, 'https://books.scielo.org/id/r4s9v/cover/cover_thumbnail.jpeg', NULL, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r5xn3', 'r5xn3', 'Brazil - United States relations: XX and XXI centuries', NULL, '["Sidnei José Munhoz","Francisco Carlos Teixeira da Silva"]', 'LA Referencia (Red Federada de Repositorios Institucionales de Publicaciones Científicas)', 'Brasil', 'SciELO Books', 'books', 2013, '2013-01-01', 'en', 'book', 'social-sciences', 'Ciencias Sociales y Educación', 'Economics, Econometrics and Finance', 'This book studies relations between Brazil and the USA during the 20th century and outlines some perspectives for the start of the 21st century. Issues related to a wide variety of aspects of the relationship are addressed by bringing together a number of texts by Brazilian and American historians and political scientists. The reader will find studies relating to different historical periods on the economic, political, military, social and cultural relations of these two countries.', '["Brazil–United States relations","bilateral relations","20th century","21st century","economic relations","political relations","military relations","interpersonal relationships","cultural relations","international relations history"]', '10.7476/9788576286592', '9788576285328', 'https://books.scielo.org/id/r5xn3', NULL, NULL, 'https://books.scielo.org/id/r5xn3/cover/cover_thumbnail.jpeg', 460, 5, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r5zgj', 'r5zgj', 'Entre os muros da exclusão', NULL, '["Patrick Moraes Sepúlveda"]', 'EDUNEB', 'Brasil', 'SciELO Books', 'books', 2023, '2023-01-01', 'pt', 'book', 'medical-health', 'Ciencias Médicas y de la Salud', 'Psychology', 'Este livro analisa a trajetória de três internos do Asilo São João de Deus, situado na cidade de Salvador, durante as primeiras décadas do século XX. Por meio de fontes como periódicos, processos crimes e cíveis, foi possível compreender aspectos sociais, culturais e cotidianos de suas experiências de vida sob diversos aspectos.', '["psychiatric hospitals","institutionalized persons","life trajectories","social exclusion","everyday life","cultural life","Salvador, Bahia","early 20th century","history of psychiatry"]', '10.7476/9788585813338', '9786588211724', 'https://books.scielo.org/id/r5zgj', 'https://books.scielo.org/id/r5zgj/pdf/sepulveda-9788585813338.pdf', 'https://books.scielo.org/id/r5zgj/epub/sepulveda-9788585813338.epub', 'https://books.scielo.org/id/r5zgj/cover/cover_thumbnail.jpeg', 183, 2, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
INSERT INTO publications (id, oai_identifier, title, subtitle, authors_json, publisher, country, collection, collection_code, publication_year, publication_date, language, doc_type, oecd_area, oecd_area_label, oecd_subarea, abstract, keywords_json, doi, isbn, scielo_url, pdf_url, epub_url, cover_url, page_count, cited_by_count, source_origin, raw_set_spec, updated_at) VALUES ('scielo-book-r65k3', 'r65k3', 'História da arquitetura e da cidade no Brasil e em Portugal', 'séculos XVI ao XIX: antologia crítica - Volume 1', '["Jucá Neto, Clovis Ramiro","Baeta, Rodrigo Espinha"]', 'EDUFBA', 'Brasil', 'SciELO Books', 'books', 2026, NULL, 'pt', 'book', 'engineering-tech', 'Ingeniería y Tecnología', NULL, 'Esta antologia reúne pesquisadores e pesquisadoras do Brasil e de Portugal em torno de um amplo panorama da produção historiográfica recente sobre arquitetura e cidade entre os séculos XVI e XIX. Ao explorar a circulação de ideias, formas, agentes e saberes no universo português, a obra evidencia as conexões transnacionais que moldaram a arquitetura, o urbanismo e as artes em diferentes contextos locais. Dividido em cinco seções temáticas, o livro aborda desde processos de transculturação e fundação de núcleos urbanos até arquitetura civil, religiosa e formas de representação pictórica e gráfica. As análises revelam a diversidade da arquitetura brasileira e portuguesa, destacando a relação entre cidade, paisagem, poder e cultura material, além de iluminar os intercâmbios que marcaram a constituição da escola barroca e da experiência urbana no mundo luso-brasileiro.', '[]', '10.7476/9786556309927', '9786556309484', 'https://books.scielo.org/id/r65k3', 'https://books.scielo.org/id/r65k3/pdf/juca-9786556309927.pdf', 'https://books.scielo.org/id/r65k3/epub/juca-9786556309927.epub', 'https://books.scielo.org/id/r65k3/cover/cover_thumbnail.jpeg', 442, 0, 'openalex', NULL, datetime('now')) ON CONFLICT(id) DO UPDATE SET title = excluded.title, authors_json = CASE WHEN excluded.authors_json != '[]' THEN excluded.authors_json ELSE publications.authors_json END, country = CASE WHEN publications.country = 'Internacional' THEN excluded.country ELSE publications.country END, abstract = CASE WHEN length(excluded.abstract) > length(COALESCE(publications.abstract, '')) THEN excluded.abstract ELSE publications.abstract END, pdf_url = COALESCE(excluded.pdf_url, publications.pdf_url), epub_url = COALESCE(excluded.epub_url, publications.epub_url), cover_url = COALESCE(excluded.cover_url, publications.cover_url), doi = COALESCE(excluded.doi, publications.doi), isbn = COALESCE(excluded.isbn, publications.isbn), cited_by_count = MAX(excluded.cited_by_count, publications.cited_by_count), language = CASE WHEN excluded.language != 'other' THEN excluded.language ELSE publications.language END, publication_year = COALESCE(publications.publication_year, excluded.publication_year), page_count = COALESCE(publications.page_count, excluded.page_count), updated_at = datetime('now');
